// ============================================================================
// skin-ini.js - skin.ini 解析、字体前缀规则与 Mania 配置写入
// 依赖：core/state.js
// ============================================================================

        // skin.ini NoteBodyStyle: 0=Stretch, 1=FromTail, 2=FromHead, 3=TopAndBottom。
        // 同时兼容部分旧 skin 使用的 4=TopAndBottom。
        // 内部统一使用 0=Stretch, 1=FromTail, 2=FromHead, 3=TopAndBottom。
        function normalizeNoteBodyStyleValue(value) {
            const text = String(value == null ? '' : value).trim();
            const raw = parseInt(text, 10);
            if (!isNaN(raw)) {
                if (raw === 0) return NOTE_BODY_STYLE.Stretch;
                if (raw === 1) return NOTE_BODY_STYLE.RepeatFromTail;
                if (raw === 2) return NOTE_BODY_STYLE.RepeatFromHead;
                if (raw === 3 || raw === 4) return NOTE_BODY_STYLE.RepeatTopAndBottom;
                return null;
            }

            const low = text.toLowerCase();
            if (low === 'stretch') return NOTE_BODY_STYLE.Stretch;
            if (low.includes('topandbottom') || low.includes('topandb') || low.includes('both')) {
                return NOTE_BODY_STYLE.RepeatTopAndBottom;
            }
            if (low === 'repeatfromtail' || low === 'repeattail' || low.includes('top')) {
                return NOTE_BODY_STYLE.RepeatFromTail;
            }
            if (low === 'repeatfromhead' || low === 'repeathead' || low.includes('bottom')) {
                return NOTE_BODY_STYLE.RepeatFromHead;
            }
            return null;
        }

        // 连击数字 (Combo) 字体贴图前缀解析 —— 唯一真源，renderer.js 与 ui.js 必须共用。
        //  1. [Mania] FontCombo  : 键位区块内单独指定连击数字使用的贴图组 (优先级最高)
        //  2. [Fonts] ComboPrefix : 全局连击数字贴图前缀 (仅 ini 显式写了才算)
        //     单独的 Combo: 不是这个键。stable 不读取它，连击会退回 score。
        // 两者都没有时返回 null，语义 = 「连击数字与 score 共用同一套字体贴图」。
        // 注意：不要在这里做「名字必须含 score」的过滤，FontCombo 就是用来指定非 score 命名的贴图组的。
        function getExplicitComboFontPrefix(keyCount) {
            const cfg = (keyCount != null) ? getManiaConfigForKeys(keyCount) : null;
            if (cfg && cfg.FontCombo != null) {
                const v = String(cfg.FontCombo).trim();
                if (v) return v;
            }
            if (skinFontsConfig.hasExplicitComboPrefix && skinFontsConfig.comboPrefix) {
                const v = String(skinFontsConfig.comboPrefix).trim();
                if (v) return v;
            }
            return null;
        }

        // 根据前缀与目标字符生成候选贴图标识（包含常规数字、百分号、小数点、逗号、连击x及备选格式）
        function parseSkinIniLazer(text) {
            function splitKeyVal(line) {
                const commentIdx1 = line.indexOf('//');
                if (commentIdx1 >= 0) line = line.substring(0, commentIdx1);
                const commentIdx2 = line.indexOf('#');
                if (commentIdx2 >= 0) line = line.substring(0, commentIdx2);
                const idx = line.indexOf(':');
                if (idx < 0) return null;
                return { Key: line.substring(0, idx).trim(), Value: line.substring(idx + 1).trim() };
            }
            function parseArrayValue(value, output, applyScaleFactor) {
                const parts = value.split(',');
                if (parts.length === 1 && output.length > 1) {
                    let v = parseFloat(parts[0].trim());
                    if (!isNaN(v)) {
                        if (applyScaleFactor) v *= STABLE_MAGIC_SCALE_FACTOR;
                        output.fill(v);
                        return;
                    }
                }
                for (let i = 0; i < parts.length; i++) {
                    if (i >= output.length) break;
                    let v = parseFloat(parts[i].trim());
                    if (isNaN(v)) v = 0;
                    if (applyScaleFactor) v *= STABLE_MAGIC_SCALE_FACTOR;
                    output[i] = v;
                }
            }
            function createConfig(keys) {
                const DEFAULT_COLUMN_SIZE = 30;
                const DEFAULT_HIT_POSITION = 402;
                const cw = new Array(keys); cw.fill(DEFAULT_COLUMN_SIZE);
                const clw = new Array(keys + 1); clw.fill(2);
                const cs = new Array(Math.max(0, keys - 1)); cs.fill(0);
                const ew = new Array(keys); ew.fill(0);
                const hlw = new Array(keys); hlw.fill(0);
                const colLight = new Array(keys);
                for (let i = 0; i < keys; i++) colLight[i] = { r: 255, g: 255, b: 255, a: 255 };
                const colColours = new Array(keys);
                for (let i = 0; i < keys; i++) colColours[i] = { r: 0, g: 0, b: 0, a: 255 };
                return {
                    Keys: keys,
                    SkinVersion: globalSkinVersion,
                    CustomColours: {},
                    ImageLookups: new Map(),
                    WidthForNoteHeightScale: 0,
                    ColumnLineWidth: clw,
                    ColumnSpacing: cs,
                    ColumnWidth: cw,
                    ColumnColour: colColours,
                    ExplosionWidth: ew,
                    ComboBreakColour: { r: 255, g: 0, b: 0 },
                    ColourHold: { r: 255, g: 191, b: 51, a: 255 },
                    ColourLight: colLight,
                    GlobalColourLight: null,
                    HoldNoteLightWidth: hlw,
                    HitPosition: DEFAULT_HIT_POSITION,
                    LightPosition: 413,
                    ComboPosition: 111,
                    ScorePosition: 300,
                    FontCombo: null,
                    ComboOverlap: null,
                    FontScore: null,
                    ScoreOverlap: null,
                    BarLineHeight: 1.2,
                    ColourBarline: { r: 255, g: 255, b: 255, a: 255 },
                    ShowJudgementLine: true,
                    KeysUnderNotes: globalKeysUnderNotes !== undefined ? globalKeysUnderNotes : 0,
                    LightFramePerSecond: 60,
                    NoteBodyStyle: null,
                    NoteBodyStyles: new Array(keys).fill(null),
                    ColumnStart: 136,
                    ColumnRight: 19,
                    UpsideDown: false,
                    SplitStages: false,
                    StageSeparation: 40,
                    FlipSettings: new Map(),
                };
            }

            const output = [];
            let currentConfig = null;
            const pendingLines = [];

            globalSkinImageLookups.clear();
            let globalKeysUnderNotes = 0;
            // 注意：这里不能再用 let 声明，否则会遮蔽顶层的 globalSkinVersion，
            // 使 renderer.js / getManiaSkinConfig 读到的仍是旧值（甚至抛 ReferenceError）。
            // 每次解析 skin.ini 都重置为默认值，再按 [General] Version 覆盖。
            globalSkinVersion = 2.7; // 默认最新版本 (>= 2.5)

            currentSkinMetadata = {
                general: {
                    Name: 'Custom Mania Skin',
                    Author: 'Unknown',
                    Version: 'latest',
                    AnimationFramerate: 60,
                },
                colours: {},
                fonts: {},
                rawSections: {},
                rawIniText: text
            };

            const lines = text.split(/\r?\n/);
            let section = '';
            let sectionOriginal = '';

            for (const rawLine of lines) {
                let line = rawLine;
                const headerMatch = line.match(/^\s*\[([^\]]+)\]\s*$/);
                if (headerMatch) {
                    if (currentConfig !== null) flushPendingLazer();
                    pendingLines.length = 0;
                    currentConfig = null;
                    sectionOriginal = headerMatch[1].trim();
                    section = officialSkinIniSection(sectionOriginal) || '';
                    if (section === 'Mania') {
                        // 进入新的 [Mania] 区块，创建临时配置对象
                        currentConfig = createConfig(0);
                    }
                    continue;
                }

                const pair = splitKeyVal(line);
                if (!pair) continue;

                // 正式键按 wiki 拼写保存；不认识的键保留原文，导出时原样接回。
                const storedKey = officialSkinIniKeyName(section, pair.Key) || pair.Key;
                if (section === 'General') {
                    currentSkinMetadata.general[storedKey] = pair.Value;
                } else if (section === 'Colours') {
                    currentSkinMetadata.colours[storedKey] = pair.Value;
                } else if (section === 'Fonts') {
                    currentSkinMetadata.fonts[storedKey] = pair.Value;
                } else if (!section && sectionOriginal) {
                    if (!currentSkinMetadata.rawSections[sectionOriginal]) currentSkinMetadata.rawSections[sectionOriginal] = {};
                    currentSkinMetadata.rawSections[sectionOriginal][pair.Key] = pair.Value;
                } else if (section && section !== 'Mania') {
                    if (!currentSkinMetadata.rawSections[section]) currentSkinMetadata.rawSections[section] = {};
                    currentSkinMetadata.rawSections[section][storedKey] = pair.Value;
                }

                const K = pair.Key, V = pair.Value;
                if (section === 'General' && K === 'Version') {
                    const rawVal = V.trim().toLowerCase();
                    if (rawVal === 'latest') {
                        globalSkinVersion = 2.7;
                    } else {
                        const vNum = parseFloat(rawVal);
                        if (!isNaN(vNum)) globalSkinVersion = vNum;
                    }
                    if (currentConfig) currentConfig.SkinVersion = globalSkinVersion;
                }
                if (section === 'Mania' && isOfficialManiaImageKey(K)) {
                    globalSkinImageLookups.set(K, V);
                }

                // osu! wiki 规范: 解析 [Fonts] 区块。只认 ComboPrefix，不把 Combo 当成前缀。
                if (section === 'Fonts') {
                    switch (K) {
                        case 'ScorePrefix':
                            skinFontsConfig.scorePrefix = V.trim();
                            break;
                        case 'ScoreOverlap': {
                            const n = parseInt(V.trim(), 10);
                            if (!isNaN(n)) {
                                skinFontsConfig.scoreOverlap = n;
                                skinFontsConfig.hasExplicitScoreOverlap = true;
                            }
                            break;
                        }
                        case 'ComboPrefix': {
                            skinFontsConfig.comboPrefix = V.trim() || 'combo';
                            skinFontsConfig.hasExplicitComboPrefix = true;
                            break;
                        }
                        case 'ComboOverlap': {
                            const n = parseInt(V.trim(), 10);
                            if (!isNaN(n)) {
                                skinFontsConfig.comboOverlap = n;
                                skinFontsConfig.hasExplicitComboOverlap = true;
                            }
                            break;
                        }
                        case 'HitCirclePrefix':
                            skinFontsConfig.hitCirclePrefix = V.trim();
                            break;
                        case 'HitCircleOverlap': {
                            const n = parseInt(V.trim(), 10);
                            if (!isNaN(n)) skinFontsConfig.hitCircleOverlap = n;
                            break;
                        }
                    }
                    continue;
                }

                if (section !== 'Mania') continue;

                if (pair.Key === 'Keys') {
                    const n = parseInt(pair.Value, 10);
                    if (!isNaN(n) && n > 0) {
                        if (!currentConfig) currentConfig = createConfig(n);
                        currentConfig.Keys = n;
                        // 初始化各数组长度为 n
                        if (!currentConfig.ColumnWidth || currentConfig.ColumnWidth.length !== n) {
                            const oldW = currentConfig.ColumnWidth;
                            currentConfig.ColumnWidth = new Array(n).fill(30);
                            if (oldW && oldW.length > 0) {
                                for (let i = 0; i < Math.min(n, oldW.length); i++) currentConfig.ColumnWidth[i] = oldW[i];
                            }
                        }
                        const spacingCount = Math.max(0, n - 1);
                        if (!currentConfig.ColumnSpacing || currentConfig.ColumnSpacing.length !== spacingCount) {
                            const oldS = currentConfig.ColumnSpacing;
                            currentConfig.ColumnSpacing = new Array(spacingCount).fill(0);
                            if (oldS && oldS.length > 0) {
                                for (let i = 0; i < Math.min(spacingCount, oldS.length); i++) currentConfig.ColumnSpacing[i] = oldS[i];
                            }
                        }
                        if (!currentConfig.ColumnLineWidth || currentConfig.ColumnLineWidth.length !== n + 1) {
                            const oldL = currentConfig.ColumnLineWidth;
                            currentConfig.ColumnLineWidth = new Array(n + 1).fill(2);
                            if (oldL && oldL.length > 0) {
                                for (let i = 0; i < Math.min(n + 1, oldL.length); i++) currentConfig.ColumnLineWidth[i] = oldL[i];
                            }
                        }
                        if (!currentConfig.ExplosionWidth || currentConfig.ExplosionWidth.length !== n) {
                            const oldEw = currentConfig.ExplosionWidth;
                            currentConfig.ExplosionWidth = new Array(n).fill(0);
                            if (oldEw && oldEw.length > 0) {
                                for (let i = 0; i < Math.min(n, oldEw.length); i++) currentConfig.ExplosionWidth[i] = oldEw[i];
                            }
                        }
                        if (!currentConfig.HoldNoteLightWidth || currentConfig.HoldNoteLightWidth.length !== n) {
                            const oldHlw = currentConfig.HoldNoteLightWidth;
                            currentConfig.HoldNoteLightWidth = new Array(n).fill(0);
                            if (oldHlw && oldHlw.length > 0) {
                                for (let i = 0; i < Math.min(n, oldHlw.length); i++) currentConfig.HoldNoteLightWidth[i] = oldHlw[i];
                            }
                        }
                        if (!currentConfig.ColourLight || currentConfig.ColourLight.length !== n) {
                            const oldCl = currentConfig.ColourLight;
                            currentConfig.ColourLight = new Array(n);
                            for (let i = 0; i < n; i++) {
                                currentConfig.ColourLight[i] = (oldCl && oldCl[i]) ? oldCl[i] : (currentConfig.GlobalColourLight || { r: 255, g: 255, b: 255, a: 255 });
                            }
                        }
                        if (!currentConfig.ColumnColour || currentConfig.ColumnColour.length !== n) {
                            const oldCc = currentConfig.ColumnColour;
                            currentConfig.ColumnColour = new Array(n);
                            for (let i = 0; i < n; i++) {
                                currentConfig.ColumnColour[i] = (oldCc && oldCc[i]) ? oldCc[i] : { r: 0, g: 0, b: 0, a: 255 };
                            }
                        }
                        // 加入 output（若已有同键位配置则替换或合并）
                        const existingIdx = output.findIndex(c => c.Keys === n);
                        if (existingIdx >= 0) {
                            output[existingIdx] = currentConfig;
                        } else {
                            output.push(currentConfig);
                        }
                        flushPendingLazer();
                    }
                } else {
                    pendingLines.push(line);
                    if (currentConfig !== null) flushPendingLazer();
                }
            }
            if (currentConfig !== null) flushPendingLazer();

            function flushPendingLazer() {
                if (!currentConfig) return;
                for (const l of pendingLines) {
                    const p = splitKeyVal(l);
                    if (!p) continue;
                    const K = p.Key, V = p.Value;
                    if (!isOfficialManiaKey(K)) continue;

                    switch (K) {
                        case 'ColumnWidth':
                            parseArrayValue(V, currentConfig.ColumnWidth, false); break;
                        case 'ColumnSpacing':
                            parseArrayValue(V, currentConfig.ColumnSpacing, false); break;
                        case 'ColumnLineWidth':
                            parseArrayValue(V, currentConfig.ColumnLineWidth, false); break;
                        case 'BarlineHeight': {
                            const v = parseFloat(V); if (!isNaN(v)) currentConfig.BarLineHeight = v;
                            break;
                        }
                        case 'HitPosition': {
                            let v = parseFloat(V);
                            if (isNaN(v)) break;
                            v = Math.max(0, Math.min(480, v));
                            currentConfig.HitPosition = v;
                            break;
                        }
                        case 'LightPosition': {
                            const v = parseFloat(V);
                            if (isNaN(v)) break;
                            currentConfig.LightPosition = v;
                            break;
                        }
                        case 'ComboPosition': {
                            const v = parseFloat(V);
                            if (isNaN(v)) break;
                            currentConfig.ComboPosition = v;
                            break;
                        }
                        case 'ScorePosition': {
                            const v = parseFloat(V);
                            if (isNaN(v)) break;
                            currentConfig.ScorePosition = v;
                            break;
                        }
                        case 'FontCombo':
                            currentConfig.FontCombo = V.trim();
                            break;
                        case 'ComboOverlap': {
                            const n = parseInt(V, 10);
                            if (!isNaN(n)) currentConfig.ComboOverlap = n;
                            break;
                        }
                        case 'FontScore':
                            currentConfig.FontScore = V.trim();
                            break;
                        case 'ScoreOverlap': {
                            const n = parseInt(V, 10);
                            if (!isNaN(n)) currentConfig.ScoreOverlap = n;
                            break;
                        }
                        case 'JudgementLine':
                            currentConfig.ShowJudgementLine = (V === '1');
                            break;
                        case 'KeysUnderNotes':
                            currentConfig.KeysUnderNotes = (V === '1') ? 1 : 0;
                            break;
                        case 'LightingNWidth':
                            parseArrayValue(V, currentConfig.ExplosionWidth, false); break;
                        case 'ColourBreak': {
                            const parts = V.split(',').map(s => parseInt(s.trim(), 10));
                            if (parts.length >= 3 && !isNaN(parts[0]) && !isNaN(parts[1]) && !isNaN(parts[2])) {
                                currentConfig.ComboBreakColour = { r: parts[0], g: parts[1], b: parts[2] };
                            }
                            break;
                        }
                        case 'ColourHold': {
                            const parts = V.split(',').map(s => parseInt(s.trim(), 10));
                            if (parts.length >= 3 && !isNaN(parts[0]) && !isNaN(parts[1]) && !isNaN(parts[2])) {
                                const a = (parts.length >= 4 && !isNaN(parts[3])) ? parts[3] : 255;
                                currentConfig.ColourHold = { r: parts[0], g: parts[1], b: parts[2], a: a };
                            }
                            break;
                        }
                        case 'ColourBarline': {
                            const parts = V.split(',').map(s => parseInt(s.trim(), 10));
                            if (parts.length >= 3 && !isNaN(parts[0]) && !isNaN(parts[1]) && !isNaN(parts[2])) {
                                const a = (parts.length >= 4 && !isNaN(parts[3])) ? parts[3] : 255;
                                currentConfig.ColourBarline = { r: parts[0], g: parts[1], b: parts[2], a: a };
                            }
                            break;
                        }
                        case 'LightingLWidth':
                            parseArrayValue(V, currentConfig.HoldNoteLightWidth, false); break;
                        case 'NoteBodyStyle': {
                            const style = normalizeNoteBodyStyleValue(V);
                            if (style != null) currentConfig.NoteBodyStyle = style;
                            break;
                        }
                        case 'WidthForNoteHeightScale': {
                            const v = parseFloat(V);
                            if (!isNaN(v)) currentConfig.WidthForNoteHeightScale = v;
                            break;
                        }
                        case 'LightFramePerSecond': {
                            const n = parseInt(V, 10);
                            if (!isNaN(n)) currentConfig.LightFramePerSecond = (n > 0) ? n : 24;
                            break;
                        }
                        case 'UpsideDown':
                            currentConfig.UpsideDown = (V === '1'); break;
                        case 'SplitStages':
                            currentConfig.SplitStages = (V === '1'); break;
                        case 'SeparateScore':
                            currentConfig.SeparateScore = (V === '1');
                            break;
                        case 'StageSeparation': {
                            const v = parseFloat(V); if (!isNaN(v)) currentConfig.StageSeparation = v; break;
                        }
                        case 'ColumnStart': {
                            const v = parseFloat(V);
                            if (!isNaN(v)) currentConfig.ColumnStart = v;
                            break;
                        }
                        case 'ColumnRight': {
                            const v = parseFloat(V);
                            if (!isNaN(v)) currentConfig.ColumnRight = v;
                            break;
                        }
                        case 'SpecialStyle': {
                            const style = parseInt(V, 10);
                            if (style >= 0 && style <= 2) currentConfig.SpecialStyle = style;
                            break;
                        }
                        case 'ComboBurstStyle': {
                            const namedStyles = { Left: 0, Right: 1, Both: 2 };
                            const style = namedStyles[String(V || '').trim()] != null
                                ? namedStyles[String(V || '').trim()]
                                : parseInt(V, 10);
                            if (style >= 0 && style <= 2) currentConfig.ComboBurstStyle = style;
                            break;
                        }
                        default: {
                            const lightMatch = K.match(/^ColourLight(\d+)$/);
                            const columnMatch = K.match(/^Colour(\d+)$/);
                            const bodyMatch = K.match(/^NoteBodyStyle(\d+)$/);
                            if (lightMatch) {
                                const colIdx = maniaColourColumnIndex(lightMatch[1]);
                                const parts = V.split(',').map(s => parseInt(s.trim(), 10));
                                if (colIdx != null && parts.length >= 3 && !parts.slice(0, 3).some(isNaN)) {
                                    const r = Math.min(255, Math.max(0, parts[0]));
                                    const g = Math.min(255, Math.max(0, parts[1]));
                                    const b = Math.min(255, Math.max(0, parts[2]));
                                    const a = (parts.length >= 4 && !isNaN(parts[3])) ? Math.min(255, Math.max(0, parts[3])) : 255;
                                    if (!currentConfig.ColourLight) currentConfig.ColourLight = [];
                                    currentConfig.ColourLight[colIdx] = { r, g, b, a };
                                }
                            } else if (columnMatch) {
                                const colIdx = maniaColourColumnIndex(columnMatch[1]);
                                const parts = V.split(',').map(s => parseInt(s.trim(), 10));
                                if (colIdx != null && parts.length >= 3 && !parts.slice(0, 3).some(isNaN)) {
                                    const r = Math.min(255, Math.max(0, parts[0]));
                                    const g = Math.min(255, Math.max(0, parts[1]));
                                    const b = Math.min(255, Math.max(0, parts[2]));
                                    const a = (parts.length >= 4 && !isNaN(parts[3])) ? Math.min(255, Math.max(0, parts[3])) : 255;
                                    if (!currentConfig.ColumnColour) currentConfig.ColumnColour = [];
                                    currentConfig.ColumnColour[colIdx] = { r, g, b, a };
                                }
                            } else if (bodyMatch) {
                                const colIdx = maniaColumnIndex(bodyMatch[1]);
                                const sVal = normalizeNoteBodyStyleValue(V);
                                if (sVal !== null && colIdx != null && colIdx < currentConfig.Keys) {
                                    if (!Array.isArray(currentConfig.NoteBodyStyles)) currentConfig.NoteBodyStyles = new Array(currentConfig.Keys).fill(null);
                                    currentConfig.NoteBodyStyles[colIdx] = sVal;
                                }
                            } else if (isOfficialManiaImageKey(K)) {
                                currentConfig.ImageLookups.set(K, V);
                            } else if (K.startsWith('KeyFlipWhenUpsideDown') || K.startsWith('NoteFlipWhenUpsideDown')) {
                                currentConfig.FlipSettings.set(K, V);
                            }
                            break;
                        }
                    }
                }
                pendingLines.length = 0;
            }

            for (const c of output) maniaSkinConfigurations.set(c.Keys, c);
            updateSkinEditorKeyPills();
        }
// --- END skin/skin-ini.js ---

// --- BEGIN skin/mania-config.js ---
// ============================================================================
// mania-config.js - 默认 Mania 配置、字段读取与逐轨贴图名解析
// 依赖：core/state.js、skin/skin-ini.js
// ============================================================================

        let editableDefaultSkinWorkspaceActive = false;

        function getManiaConfigForKeys(keyCount) {
            if (maniaSkinConfigurations.size === 0) return null;
            if (maniaSkinConfigurations.has(keyCount)) return maniaSkinConfigurations.get(keyCount);
            let bestKeys = null, bestDelta = Infinity;
            for (const k of maniaSkinConfigurations.keys()) {
                const d = Math.abs(k - keyCount);
                if (d < bestDelta) { bestDelta = d; bestKeys = k; }
            }
            return bestKeys !== null ? maniaSkinConfigurations.get(bestKeys) : null;
        }

        // 构造一份「完整的」默认 mania 配置（字段与 parseSkinIniLazer 内部的 createConfig 对齐）。
        // 用途：「未导入皮肤 / 只导入谱面（展示默认皮肤）」时用户在画布上直接点选并编辑。
        // 必须补齐 getManiaSkinConfig 会访问到的**所有数组字段**，否则一旦把不完整的配置写回
        // maniaSkinConfigurations，getManiaSkinConfig 读 `cfg.ColumnWidth.length` 就会直接抛
        // TypeError: Cannot read properties of undefined (reading 'length')，整个 drawFrame 崩掉。
        function createDefaultManiaSkinConfiguration(keyCount) {
            const k = Math.max(1, keyCount | 0);
            const cw = new Array(k).fill(30);
            const clw = new Array(k + 1).fill(2);
            const cs = new Array(Math.max(0, k - 1)).fill(0);
            const colColours = new Array(k);
            for (let i = 0; i < k; i++) colColours[i] = { r: 0, g: 0, b: 0, a: 255 };
            const colLight = new Array(k);
            for (let i = 0; i < k; i++) colLight[i] = { r: 255, g: 255, b: 255, a: 255 };
            return {
                Keys: k,
                SkinVersion: 2.7,
                CustomColours: {},
                ImageLookups: new Map(),
                WidthForNoteHeightScale: 0,
                ColumnLineWidth: clw,
                ColumnSpacing: cs,
                ColumnWidth: cw,
                ColumnColour: colColours,
                ExplosionWidth: new Array(k).fill(0),
                ComboBreakColour: { r: 255, g: 0, b: 0 },
                ColourHold: { r: 255, g: 191, b: 51, a: 255 },
                ColourLight: colLight,
                GlobalColourLight: null,
                HoldNoteLightWidth: new Array(k).fill(0),
                HitPosition: 402,
                LightPosition: 413,
                ComboPosition: 111,
                ScorePosition: 300,
                FontCombo: null,
                ComboOverlap: null,
                FontScore: null,
                ScoreOverlap: null,
                BarLineHeight: 1.2,
                ColourBarline: { r: 255, g: 255, b: 255, a: 255 },
                ShowJudgementLine: true,
                KeysUnderNotes: 0,
                LightFramePerSecond: 60,
                ComboBurstStyle: 1,
                NoteBodyStyle: null,
                NoteBodyStyles: new Array(k).fill(null),
                ColumnStart: 136,
                ColumnRight: 19,
                UpsideDown: false,
                SplitStages: false,
                StageSeparation: 40,
                FlipSettings: new Map(),
                // 标记为「按需生成的默认配置」，便于区分真实皮肤解析出的配置
                _isDefaultFallback: true,
            };
        }

        // 取某个键位的 mania 配置；若不存在（典型：只导入了谱面、用的是内置默认皮肤），
        // 按需生成一份**完整**的默认配置并登记后返回。
        // 各编辑入口一律用它兜底，绝不要再用 `{ Keys: keys }` 这种残缺对象写回配置表。
        function ensureManiaConfigForKeys(keyCount) {
            const keys = Math.max(1, keyCount | 0);
            const existing = maniaSkinConfigurations.get(keys);
            if (existing) return existing;
            const cfg = createDefaultManiaSkinConfiguration(keys);
            maniaSkinConfigurations.set(cfg.Keys, cfg);
            return cfg;
        }

        function createEditableDefaultSkinMetadata() {
            return {
                general: {
                    Name: '默认皮肤',
                    Author: 'osu! / ppy',
                    Version: 'latest',
                    AnimationFramerate: 60,
                    CursorRotate: 0,
                    CursorExpand: 1,
                    CursorCentre: 1,
                    ComboBurstRandom: 0,
                },
                colours: {},
                fonts: {},
                rawSections: {},
                rawIniText: ''
            };
        }

        function isEditableDefaultSkinWorkspaceActive() {
            return editableDefaultSkinWorkspaceActive && !currentSkinZip;
        }

        function activateEditableDefaultSkinWorkspace(keyCount = activeEditorKeyCount || 4) {
            if (currentSkinZip) {
                editableDefaultSkinWorkspaceActive = false;
                return null;
            }

            const keys = Math.max(1, keyCount | 0);
            const wasActive = editableDefaultSkinWorkspaceActive;
            editableDefaultSkinWorkspaceActive = true;

            if (!wasActive) {
                currentSkinFileName = '默认皮肤';
                currentSkinMetadata = createEditableDefaultSkinMetadata();
            }

            activeEditorKeyCount = keys;
            return ensureManiaConfigForKeys(keys);
        }

        function deactivateEditableDefaultSkinWorkspace() {
            editableDefaultSkinWorkspaceActive = false;
        }

        function isDummyBlankName(name) {
            if (!name) return true;
            const low = String(name).trim().toLowerCase().replace(/\.(png|jpg|jpeg)$/i, '');
            return low === 'blank' || low === '_blank' || low === 'none' || low === 'null' || low === 'empty' || low === 'transparent' || low === '0' || low === '';
        }

        function computeFallbackColumnIndex(totalKeys, columnIndex) {
            if (totalKeys <= 0) return '1';
            const i = ((columnIndex % totalKeys) + totalKeys) % totalKeys;
            // osu! stable 规范: 奇数键位中间列（如 7K 的第 4 列）采用专属特殊键 'S' (mania-noteS, mania-keyS)
            if (totalKeys % 2 === 1 && i === Math.floor(totalKeys / 2)) {
                return 'S';
            }
            const last = totalKeys - 1;
            const distanceToEdge = Math.min(i, last - i);
            return (distanceToEdge % 2 === 0) ? '1' : '2';
        }

        function imageLookupToIniPrefixSuffix(lookup) {
            switch (lookup) {
                case LML.NoteImage: return { prefix: 'NoteImage', suffix: '' };
                case LML.HoldNoteHeadImage: return { prefix: 'NoteImage', suffix: 'H' };
                case LML.HoldNoteBodyImage: return { prefix: 'NoteImage', suffix: 'L' };
                case LML.HoldNoteTailImage: return { prefix: 'NoteImage', suffix: 'T' };
                case LML.KeyImage: return { prefix: 'KeyImage', suffix: '' };
                case LML.KeyImageDown: return { prefix: 'KeyImage', suffix: 'D' };
                case LML.HoldNoteLightImage: return { prefix: 'LightingL', suffix: '', altKeys: ['LightingL'] };
                case LML.ExplosionImage: return { prefix: 'LightingN', suffix: '', altKeys: ['LightingN'] };
                case LML.HitTargetImage: return { prefix: 'StageHint', suffix: '', altKeys: ['StageHint', 'HitTarget', 'mania-stage-hint'] };
                case LML.BottomStageImage: return { prefix: 'StageBottom', suffix: '', altKeys: ['StageBottom', 'Stage_Bottom', 'mania-stage-bottom'] };
                case LML.LeftStageImage: return { prefix: 'StageLeft', suffix: '', altKeys: ['StageLeft', 'Stage_Left', 'mania-stage-left'] };
                case LML.RightStageImage: return { prefix: 'StageRight', suffix: '', altKeys: ['StageRight', 'Stage_Right', 'mania-stage-right'] };
                case LML.LightImage: return { prefix: 'StageLight', suffix: '', altKeys: ['StageLight', 'mania-stage-light'] };
                case LML.Hit300g: return { prefix: 'Hit300g', suffix: '', isGlobal: true, altKeys: ['Hit300g', 'Hit300k', 'Hit300'] };
                case LML.Hit300: return { prefix: 'Hit300', suffix: '', isGlobal: true, altKeys: ['Hit300'] };
                case LML.Hit200: return { prefix: 'Hit200', suffix: '', isGlobal: true, altKeys: ['Hit200'] };
                case LML.Hit100: return { prefix: 'Hit100', suffix: '', isGlobal: true, altKeys: ['Hit100'] };
                case LML.Hit50: return { prefix: 'Hit50', suffix: '', isGlobal: true, altKeys: ['Hit50'] };
                case LML.Hit0: return { prefix: 'Hit0', suffix: '', isGlobal: true, altKeys: ['Hit0'] };
                default: return null;
            }
        }

        function defaultFilenameForLookup(lookup, fallbackColumnIndex) {
            const fc = fallbackColumnIndex;
            switch (lookup) {
                case LML.NoteImage: return `mania-note${fc}`;
                case LML.HoldNoteHeadImage: return `mania-note${fc}h`;
                case LML.HoldNoteBodyImage: return `mania-note${fc}l`;
                case LML.HoldNoteTailImage: return `mania-note${fc}t`;
                case LML.KeyImage: return `mania-key${fc}`;
                case LML.KeyImageDown: return `mania-key${fc}d`;
                case LML.HoldNoteLightImage: return 'lightingL';
                case LML.ExplosionImage: return 'lightingN';
                case LML.HitTargetImage: return 'mania-stage-hint';
                // 未在 skin.ini 指定 StageBottom 时，stable 只读取皮肤根目录的 mania-stage-bottom。
                case LML.BottomStageImage: return 'mania-stage-bottom';
                case LML.LeftStageImage: return 'mania-stage-left';
                case LML.RightStageImage: return 'mania-stage-right';
                case LML.LightImage: return 'mania-stage-light';
                case LML.Hit300g: return 'mania-hit300g';
                case LML.Hit300: return 'mania-hit300';
                case LML.Hit200: return 'mania-hit200';
                case LML.Hit100: return 'mania-hit100';
                case LML.Hit50: return 'mania-hit50';
                case LML.Hit0: return 'mania-hit0';
                default: return null;
            }
        }

        function getManiaSkinConfig(keyCount, lookup, columnIndex) {
            const cfg = getManiaConfigForKeys(keyCount);
            if (!cfg) {
                if (lookup === LML.KeysUnderNotes) return { ok: true, value: 0 };
                if (lookup === LML.ColumnBackgroundColour) return { ok: true, value: { r: 0, g: 0, b: 0, a: 255 } };
                if (lookup === LML.NoteBodyStyle) {
                    const version = (typeof globalSkinVersion === 'number') ? globalSkinVersion : 2.7;
                    return { ok: true, value: version < 2.5 ? NOTE_BODY_STYLE.Stretch : NOTE_BODY_STYLE.RepeatFromTail };
                }
                return null;
            }

            // 自愈：历史路径 / 外部调用可能把不完整的配置写进 maniaSkinConfigurations，
            // 这里补齐下方 switch 会直接解引用的数组字段，避免 `undefined.length` / 迭代崩溃。
            const __k = Math.max(1, (cfg.Keys | 0) || keyCount || 4);
            if (!Array.isArray(cfg.ColumnWidth) || cfg.ColumnWidth.length === 0) cfg.ColumnWidth = new Array(__k).fill(30);
            const spacingCount = Math.max(0, __k - 1);
            if (!Array.isArray(cfg.ColumnSpacing) || cfg.ColumnSpacing.length !== spacingCount) {
                const oldSpacing = Array.isArray(cfg.ColumnSpacing) ? cfg.ColumnSpacing : [];
                cfg.ColumnSpacing = new Array(spacingCount).fill(0);
                for (let i = 0; i < Math.min(spacingCount, oldSpacing.length); i++) {
                    cfg.ColumnSpacing[i] = oldSpacing[i];
                }
            }
            if (!Array.isArray(cfg.ColumnLineWidth)) cfg.ColumnLineWidth = new Array(__k + 1).fill(2);
            if (!Array.isArray(cfg.ColumnColour) || cfg.ColumnColour.length === 0) {
                cfg.ColumnColour = new Array(__k).fill(null).map(() => ({ r: 0, g: 0, b: 0, a: 255 }));
            }
            if (!Array.isArray(cfg.ColourLight)) {
                cfg.ColourLight = new Array(__k).fill(null).map(() => ({ r: 255, g: 255, b: 255, a: 255 }));
            }

            switch (lookup) {
                case LML.ColumnBackgroundColour: {
                    if (columnIndex == null) return null;
                    const arr = cfg.ColumnColour;
                    if (!arr || arr.length === 0) return { ok: true, value: { r: 0, g: 0, b: 0, a: 255 } };
                    const i = Math.min(arr.length - 1, Math.max(0, columnIndex | 0));
                    return { ok: true, value: arr[i] || { r: 0, g: 0, b: 0, a: 255 } };
                }
                case LML.ColumnWidth: {
                    if (columnIndex == null) return null;
                    const i = Math.min(cfg.ColumnWidth.length - 1, Math.max(0, columnIndex | 0));
                    return { ok: true, value: cfg.ColumnWidth[i] };
                }
                case LML.ColumnSpacing: {
                    if (columnIndex == null) return null;
                    const arr = cfg.ColumnSpacing;
                    if (!arr || arr.length === 0) return { ok: true, value: 0 };
                    const idx = columnIndex | 0;
                    if (idx < 0 || idx >= arr.length) return { ok: true, value: 0 };
                    return { ok: true, value: arr[idx] };
                }
                case LML.ExplosionWidth: {
                    if (columnIndex == null) return null;
                    const arr = cfg.ExplosionWidth;
                    if (!arr || arr.length === 0) return null;
                    const i = Math.min(arr.length - 1, Math.max(0, columnIndex | 0));
                    return { ok: true, value: arr[i] };
                }
                case LML.ExplosionScale: {
                    // 严格对齐 osu!lazer LegacySkin.cs 的 ExplosionScale lookup：
                    // 它**不是** ini 参数，而是由 LightingNWidth (ExplosionWidth) 派生出来的缩放倍率。
                    //   version < 2.5            -> 1
                    //   ExplosionWidth[i] != 0   -> ExplosionWidth[i] / DEFAULT_COLUMN_SIZE(30)
                    //   否则                      -> ColumnWidth[i] / 30
                    const version = (cfg.SkinVersion != null) ? cfg.SkinVersion : globalSkinVersion;
                    if (version < 2.5) return { ok: true, value: 1.0 };
                    if (columnIndex == null) return { ok: true, value: 1.0 };
                    const i = Math.min(cfg.ColumnWidth.length - 1, Math.max(0, columnIndex | 0));
                    if (cfg.ExplosionWidth && cfg.ExplosionWidth[i] != null && cfg.ExplosionWidth[i] != 0) {
                        return { ok: true, value: cfg.ExplosionWidth[i] / 30.0 };
                    }
                    const cw = (cfg.ColumnWidth && cfg.ColumnWidth[i] > 0) ? cfg.ColumnWidth[i] : 30.0;
                    return { ok: true, value: cw / 30.0 };
                }
                case LML.ComboBreakColour: {
                    return { ok: true, value: cfg.ComboBreakColour || { r: 255, g: 0, b: 0 } };
                }
                case LML.ColourHold: {
                    return { ok: true, value: cfg.ColourHold || { r: 255, g: 191, b: 51, a: 255 } };
                }
                case LML.ColourBarline: {
                    return { ok: true, value: cfg.ColourBarline || { r: 255, g: 255, b: 255, a: 255 } };
                }
                case LML.ColourLight: {
                    if (columnIndex == null) return { ok: true, value: cfg.GlobalColourLight || { r: 255, g: 255, b: 255, a: 255 } };
                    const i = Math.min(cfg.Keys - 1, Math.max(0, columnIndex | 0));
                    const val = (cfg.ColourLight && cfg.ColourLight[i]) ? cfg.ColourLight[i] : (cfg.GlobalColourLight || { r: 255, g: 255, b: 255, a: 255 });
                    return { ok: true, value: val };
                }
                case LML.HoldNoteLightWidth: {
                    if (columnIndex == null) return null;
                    const arr = cfg.HoldNoteLightWidth;
                    if (!arr || arr.length === 0) return null;
                    const i = Math.min(arr.length - 1, Math.max(0, columnIndex | 0));
                    return { ok: true, value: arr[i] };
                }
                case LML.HoldNoteLightScale: {
                    // 严格对齐 osu!lazer LegacySkin.cs 的 HoldNoteLightScale lookup：
                    // 同样**不是** ini 参数，而是由 LightingLWidth (HoldNoteLightWidth) 派生。
                    const version = (cfg.SkinVersion != null) ? cfg.SkinVersion : globalSkinVersion;
                    if (version < 2.5) return { ok: true, value: 1.0 };
                    if (columnIndex == null) return { ok: true, value: 1.0 };
                    const i = Math.min(cfg.ColumnWidth.length - 1, Math.max(0, columnIndex | 0));
                    if (cfg.HoldNoteLightWidth && cfg.HoldNoteLightWidth[i] != null && cfg.HoldNoteLightWidth[i] != 0) {
                        return { ok: true, value: cfg.HoldNoteLightWidth[i] / 30.0 };
                    }
                    const cw = (cfg.ColumnWidth && cfg.ColumnWidth[i] > 0) ? cfg.ColumnWidth[i] : 30.0;
                    return { ok: true, value: cw / 30.0 };
                }
                case LML.MinimumColumnWidth: {
                    let min = cfg.ColumnWidth[0];
                    for (const w of cfg.ColumnWidth) if (w < min) min = w;
                    return { ok: true, value: min };
                }
                case LML.WidthForNoteHeightScale: {
                    let w = cfg.WidthForNoteHeightScale;
                    if (w <= 0) {
                        let min = cfg.ColumnWidth[0];
                        for (const ww of cfg.ColumnWidth) if (ww < min) min = ww;
                        w = min;
                    }
                    return { ok: true, value: w };
                }
                case LML.HitPosition: return { ok: true, value: cfg.HitPosition };
                case LML.ScorePosition: return { ok: true, value: cfg.ScorePosition };
                case LML.ComboPosition: return { ok: true, value: cfg.ComboPosition };
                case LML.ColumnStart: return { ok: true, value: cfg.ColumnStart };
                case LML.ColumnRight: return { ok: true, value: cfg.ColumnRight };
                case LML.SplitStages: return { ok: true, value: cfg.SplitStages };
                case LML.StageSeparation: return { ok: true, value: cfg.StageSeparation };
                case LML.UpsideDown: return { ok: true, value: cfg.UpsideDown };
                case LML.LightPosition: return { ok: true, value: cfg.LightPosition };
                case LML.BarLineHeight: return { ok: true, value: cfg.BarLineHeight };
                case LML.ShowJudgementLine: return { ok: true, value: cfg.ShowJudgementLine };
                case LML.KeysUnderNotes: {
                    const val = cfg.KeysUnderNotes;
                    return { ok: true, value: (val === 1 || val === '1' || val === true) ? 1 : 0 };
                }
                case LML.LightFramePerSecond: return { ok: true, value: cfg.LightFramePerSecond };
                case LML.ComboBurstStyle: {
                    const style = parseInt(cfg.ComboBurstStyle, 10);
                    return { ok: true, value: (style >= 0 && style <= 2) ? style : 1 };
                }
                case LML.NoteBodyStyle: {
                    if (columnIndex != null && Array.isArray(cfg.NoteBodyStyles) && cfg.NoteBodyStyles[columnIndex] != null) {
                        return { ok: true, value: cfg.NoteBodyStyles[columnIndex] };
                    }
                    if (cfg.NoteBodyStyle != null) {
                        return { ok: true, value: cfg.NoteBodyStyle };
                    }
                    const version = (cfg.SkinVersion != null) ? cfg.SkinVersion : globalSkinVersion;
                    return { ok: true, value: version < 2.5 ? NOTE_BODY_STYLE.Stretch : NOTE_BODY_STYLE.RepeatFromTail };
                }
                default:
                    return null;
            }
        }

        // ===== 逐轨贴图 ini 键查找顺序（唯一真源） =====
        // 下列 8 个 lookup 的 ini 键查找顺序，被三处共用：
        //   1) 画布渲染 renderer.js getManiaSkinImage / getManiaSkinAnimationFrames
        //   2) 面板缩略图/路径回显 ui.js resolveTextureParam
        //   3) 面板逐轨生效名 getManiaNoteTextureName
        // 任何一处单独改动都会让「画布显示」与「面板显示」识别出不同贴图，因此必须共用本函数。
        // 注：PER_TRACK_TEXTURE_LOOKUPS 是「可逐轨展开的面板分组」清单（6 个音符/按键贴图）；
        //     打击特效 LightingN / LightingL 也走本函数，但它们不属于那个分组清单。
        const PER_TRACK_TEXTURE_LOOKUPS = [
            LML.NoteImage, LML.HoldNoteHeadImage, LML.HoldNoteBodyImage,
            LML.HoldNoteTailImage, LML.KeyImage, LML.KeyImageDown,
        ];

        function buildPerTrackTextureSearchKeys(lookup, columnIndex) {
            const ci = (columnIndex == null) ? '' : String(columnIndex | 0);
            switch (lookup) {
                case LML.NoteImage:
                    return ['NoteImage' + ci, 'NoteImage'];
                case LML.HoldNoteHeadImage:
                    return ['NoteImage' + ci + 'H', 'HoldNoteHeadImage' + ci, 'HoldNoteHeadImage', 'NoteImageH', 'NoteImage' + ci, 'NoteImage'];
                case LML.HoldNoteBodyImage:
                    return ['NoteImage' + ci + 'L', 'HoldNoteBodyImage' + ci, 'HoldNoteBodyImage', 'NoteImageL', 'NoteImage'];
                case LML.HoldNoteTailImage:
                    return ['NoteImage' + ci + 'T', 'HoldNoteTailImage' + ci, 'HoldNoteTailImage', 'NoteImageT', 'NoteImage'];
                // 打击特效：单键爆炸 LightingN / 长条光效 LightingL。
                // 稳定版只按全局键读取这两张贴图，所有轨道共用同一张；不能识别 LightingN0 / Lighting0N 这类分轨键。
                // 两者是**相互独立**的两套贴图，查找顺序里绝不允许互相回退（LightingN 永不回退到 LightingL）。
                case LML.ExplosionImage:
                    return ['LightingN'];
                case LML.HoldNoteLightImage:
                    return ['LightingL'];
                case LML.KeyImageDown:
                    return ['KeyImage' + ci + 'D', 'KeyImage' + ci + 'Down', 'KeyImageDown' + ci, 'KeyImage' + ci, 'KeyImageD', 'KeyImageDown', 'KeyImage'];
                case LML.KeyImage:
                    return ['KeyImage' + ci, 'KeyImage'];
                default:
                    return null;
            }
        }

        // ===== 按键发光贴图 (StageLight / mania-stage-light) ini 键查找顺序（唯一真源） =====
        // 语义区分（务必牢记，两者绝不可互相回退）：
        //   StageLight / mania-stage-light  —— 按键发光。**只要按下按键**轨道上就常驻播放的发光动画，
        //                                      渲染位置由 LightPosition 决定，与是否打到 note 无关。
        //   LightingN / LightingL           —— 打击特效。**只有打到 note 那一刻**才迸发的爆炸/长条光效。
        // 查找顺序被四处共用，任何一处单独改动都会让「画布显示」与「面板识别」不一致：
        //   1) renderer.js getStageLightFrames（实际绘制）
        //   2) renderer.js getManiaSkinImage（静态贴图识别）
        //   3) renderer.js getManiaSkinAnimationFrames（动画帧识别）
        //   4) ui.js getTextureParamAliases / getTextureParamColumnKeys（面板回显）
        // 注：osu!lazer 的 LegacySkin 只认精确键 `StageLight`（无逐轨后缀），
        //     这里额外支持 `StageLight#` 作为向前兼容的超集，并保留 `mania-stage-light` 作为
        //     「作者把默认文件名写进 ini」的兜底，行为与旧实现完全一致。
        function buildStageLightSearchKeys(columnIndex) {
            const ci = (columnIndex == null) ? '' : String(columnIndex | 0);
            return ['StageLight' + ci, 'StageLight', 'mania-stage-light'];
        }

        // 在 mCfg.ImageLookups 中按给定顺序查找显式配置，返回 { value, matchedKey }；找不到返回 null
        function findExplicitImageLookupValue(mCfg, searchKeys) {
            if (!mCfg || !mCfg.ImageLookups || !searchKeys) return null;
            for (const sk of searchKeys) {
                if (mCfg.ImageLookups.has(sk)) return { value: mCfg.ImageLookups.get(sk), matchedKey: sk };
                const skLow = sk.toLowerCase();
                if (mCfg.ImageLookups.has(skLow)) return { value: mCfg.ImageLookups.get(skLow), matchedKey: sk };
            }
            return null;
        }

        // 获取某个逐轨贴图「当前实际生效」的贴图名。
        // out（可选）会带上 { explicit, explicitValue, matchedKey }，用于区分
        // 「ini 里显式写了」与「没写、只是按默认文件名回退」——面板据此决定提示文案。
// --- END skin/mania-config.js ---

// --- BEGIN skin/parameter-schema-mania.js ---
// ============================================================================
// parameter-schema-mania.js - Mania 布局、颜色与高级选项参数元数据
// ============================================================================

