// ============================================================================

        function drawStoryboardBackgroundComposite(ctx, timeMs, width, height) {
            const state = storyboardPlaybackState;
            if (!state || !state.storyboard || !state.storyboard.hasContent) return false;

            const isSbEnabled = (typeof enableStoryboard === 'undefined' || enableStoryboard);
            const isVidEnabled = (typeof enableVideo === 'undefined' || enableVideo);
            if (!isSbEnabled && !isVidEnabled) return false;

            const elementCount = state.elements ? state.elements.length : 0;
            const hasVideo = !!(isVidEnabled && state.storyboard.video && state.storyboard.video.path && !state.videoFailed);
            const shouldCache = hasVideo || (isSbEnabled && elementCount > 400);

            if (!shouldCache) {
                let videoDrawn = false;
                if (hasVideo) {
                    videoDrawn = drawStoryboardVideo(ctx, timeMs, width, height);
                }
                if (isSbEnabled && elementCount > 0) {
                    drawStoryboardFrame(ctx, timeMs, width, height, 3, 0);
                }
                return videoDrawn || (isSbEnabled && elementCount > 0);
            }

            if (!state.compositeCanvas) {
                state.compositeCanvas = document.createElement('canvas');
                state.compositeCtx = state.compositeCanvas.getContext('2d');
                state.compositeDirty = true;
                state.compositeLastDraw = 0;
                state.compositeHasContent = false;
            }

            const compositeCanvas = state.compositeCanvas;
            const compositeCtx = state.compositeCtx;
            if (compositeCanvas.width !== width || compositeCanvas.height !== height) {
                compositeCanvas.width = width;
                compositeCanvas.height = height;
                state.compositeDirty = true;
            }

            const now = performance.now();
            const targetFps = hasVideo ? 30 : 60;
            const interval = 1000 / targetFps;
            const force = !isPlaying || isSeeking || state.compositeDirty;
            if (force || now - state.compositeLastDraw >= interval) {
                compositeCtx.clearRect(0, 0, width, height);
                let videoDrawn = false;
                if (hasVideo) {
                    videoDrawn = drawStoryboardVideo(compositeCtx, timeMs, width, height);
                }
                if (isSbEnabled && elementCount > 0) {
                    drawStoryboardFrame(compositeCtx, timeMs, width, height, 3, 0);
                }
                state.compositeHasContent = videoDrawn || (isSbEnabled && elementCount > 0);
                state.compositeDirty = false;
                state.compositeLastDraw = now;
            }

            if (!state.compositeHasContent) return false;
            ctx.drawImage(compositeCanvas, 0, 0, width, height);
            return true;
        }

        function drawStoryboardForeground(ctx, timeMs, width, height) {
            // 在 osu!mania stable 模式下，所有的故事板层（包括 Foreground）均处于 Mania 轨道舞台与音符下方。
            // 背景合成已完整绘制全部故事板图层并应用统一背景暗化，此处保持无遮挡以防音符与轨道被前景层遮蔽。
            return false;
        }

        function drawStoryboardComposite(ctx, timeMs, width, height) {
            return drawStoryboardBackgroundComposite(ctx, timeMs, width, height);
        }
// --- END render/storyboard-composite.js ---

// --- BEGIN render/hold-note-geometry.js ---
// ============================================================================
// hold-note-geometry.js - osu!stable 长条几何与身体贴图绘制
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function getStableHoldHeadAnchorY(note, currentScrollPosition, currentTime, hitPos, speedFactor) {
            if (currentTime < note.startTime) {
                return hitPos - (note.scrollPositionStart - currentScrollPosition) * speedFactor;
            }
            return hitPos;
        }

        function getStableHoldTailAnchorY(note, currentScrollPosition, hitPos, speedFactor) {
            return hitPos - (note.scrollPositionEnd - currentScrollPosition) * speedFactor;
        }

        // 身体长度只等于头尾两个下端锚点之间的距离，不包含头部半高，也不受尾巴顶端影响。
        // 身体近端位于头部贴图中心，因此远端自然为“尾端锚点 - 头部半高”。
        function getStableHoldNoteGeometry(note, currentScrollPosition, currentTime, hitPos, speedFactor, headHeight, tailHeight) {
            const headAnchorY = getStableHoldHeadAnchorY(
                note, currentScrollPosition, currentTime, hitPos, speedFactor
            );
            const tailAnchorY = getStableHoldTailAnchorY(
                note, currentScrollPosition, hitPos, speedFactor
            );
            const headTopY = headAnchorY - headHeight;
            const headCenterY = headAnchorY - headHeight / 2;
            const tailTopY = tailAnchorY - tailHeight;
            const bodyBottomY = headCenterY;
            const bodyLength = Math.max(0, headAnchorY - tailAnchorY);
            const bodyTopY = bodyBottomY - bodyLength;

            return {
                headAnchorY,
                headTopY,
                headCenterY,
                tailAnchorY,
                tailTopY,
                bodyTopY,
                bodyBottomY,
                bodyLength,
                bodyHeight: Math.max(0, bodyBottomY - bodyTopY),
                headFrozen: currentTime >= note.startTime
            };
        }

        // NoteBodyStyle 只负责身体矩形内部的贴图取样方式，不改变身体矩形本身。
        function drawStableHoldBodyTexture(targetCtx, image, style, x, width, bodyTopY, bodyHeight) {
            if (!image || width <= 0 || bodyHeight <= 0.5) return;

            const nativeW = image.width || 1;
            const nativeH = image.height || 1;
            const scaledNativeH = Math.max(1, nativeH * (width / nativeW));
            const bodyBottomY = bodyTopY + bodyHeight;

            targetCtx.save();
            targetCtx.beginPath();
            targetCtx.rect(x, bodyTopY, width, bodyHeight);
            targetCtx.clip();

            if (style === NOTE_BODY_STYLE.Stretch) {
                targetCtx.drawImage(image, x, bodyTopY, width, bodyHeight);
            } else if (style === NOTE_BODY_STYLE.RepeatTopAndBottom) {
                for (let y = bodyTopY; y < bodyBottomY; y += scaledNativeH) {
                    targetCtx.drawImage(image, x, y, width, scaledNativeH);
                }
                for (let y = bodyBottomY; y > bodyTopY; y -= scaledNativeH) {
                    targetCtx.drawImage(image, x, y - scaledNativeH, width, scaledNativeH);
                }
            } else if (style === NOTE_BODY_STYLE.RepeatFromHead) {
                for (let y = bodyBottomY; y > bodyTopY; y -= scaledNativeH) {
                    targetCtx.drawImage(image, x, y - scaledNativeH, width, scaledNativeH);
                }
            } else {
                for (let y = bodyTopY; y < bodyBottomY; y += scaledNativeH) {
                    targetCtx.drawImage(image, x, y, width, scaledNativeH);
                }
            }

            targetCtx.restore();
        }
// --- END render/hold-note-geometry.js ---

// --- BEGIN render/frame-judgement.js ---
// ============================================================================
// frame-judgement.js - 帧内判定触发与无缝动画衔接
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function createJudgementTrigger(context) {
            const {
                isUpsideDown, scorePosFromSkin, scale48, startX, totalTrackWidth, keys
            } = context;

            return (now, specificLookup = null) => {
                const defaultScorePosRaw = isUpsideDown ? (480 - DEFAULT_SCORE_POSITION) : DEFAULT_SCORE_POSITION;
                let scorePosY = (scorePosFromSkin !== null)
                    ? scorePosFromSkin
                    : defaultScorePosRaw * scale48;
                let scorePosX = startX + totalTrackWidth / 2;

                let lookup = specificLookup || LML.Hit300g;
                let isMiss = (lookup === LML.Hit0);

                let hitFrames = getManiaSkinAnimationFrames(keys, lookup) || null;
                let hitImg = (hitFrames && hitFrames.length > 0)
                    ? hitFrames[0]
                    : (getManiaSkinImage(keys, lookup) || null);

                // 若 300g 无独立贴图，回退至 300
                if (!hitImg && lookup === LML.Hit300g) {
                    hitFrames = getManiaSkinAnimationFrames(keys, LML.Hit300);
                    hitImg = (hitFrames && hitFrames.length > 0) ? hitFrames[0] : getManiaSkinImage(keys, LML.Hit300);
                }

                // 对齐 osu!lazer LegacyManiaJudgementPiece: 随机生成 [-5.73°, +5.73°] 的旋转角度
                const targetRotation = (Math.random() - 0.5) * (11.46 * Math.PI / 180);

                // 动画时间重叠衔接优化：
                // 如果前一个动画正在播放，且正处于缩小或持续阶段，有新按键/音符判定要播放时，
                // 不直接从 0.8 突变打断，而是从当前的缩放大小无缝开始快速放大（把大小再顶回到 1.0），然后继续播放缩小的动画
                let startScale = 0.80;
                let startAlpha = 0.0;
                if (judgements.length > 0) {
                    const prev = judgements[0];
                    const prevElapsed = (prev.hitTime !== undefined) ? (now - prev.hitTime) : ((prev.elapsed !== undefined) ? prev.elapsed : 999);
                    if (prevElapsed < 2) {
                        // 同一瞬间触发的押键（双押/多押音符），继承相同的起始缩放与透明度
                        startScale = (prev.startScale != null) ? prev.startScale : 0.80;
                        startAlpha = (prev.startAlpha != null) ? prev.startAlpha : 0.0;
                    } else {
                        const prevHasSkin = (prev.frames && prev.frames.length > 0) || (prev.img && prev.img.width > 0);
                        const prevMaxLifetime = prevHasSkin ? 220 : (prev.isMiss ? 800 : 550);
                        if (prevElapsed >= 0 && prevElapsed <= prevMaxLifetime) {
                            startScale = getJudgementCurrentScale(prev, prevElapsed);
                            startAlpha = getJudgementCurrentAlpha(prev, prevElapsed);
                        }
                    }
                }

                judgements = [{
                    x: scorePosX,
                    y: scorePosY,
                    hitTime: now,
                    img: hitImg,
                    frames: hitFrames,
                    isMiss: isMiss,
                    lookup: lookup,
                    targetRotation: targetRotation,
                    startScale: startScale,
                    startAlpha: startAlpha
                }];
            };
        }
// --- END render/frame-judgement.js ---

// --- BEGIN render/frame-key-images.js ---
// ============================================================================
// frame-key-images.js - 帧内 KeyImage 与按下态绘制
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function createKeyImageRenderer(context) {
            const { keys, colWidths, colXCache, columnPressed, hitPos, canvas } = context;

            return () => {
                const keyAreaHeight = canvas.height - hitPos;

                for (let i = 0; i < keys; i++) {
                    const colW = colWidths[i] || colWidths[0];
                    const colX = colXCache[i];
                    const isPressed = columnPressed[i];

                    const keyImg = isPressed
                        ? getManiaSkinImage(keys, LML.KeyImageDown, i)
                        : getManiaSkinImage(keys, LML.KeyImage, i);

                    if (keyImg && keyImg.width > 0 && keyImg.height > 0) {
                        const rawColWRes = getManiaSkinConfig(keys, LML.ColumnWidth, i);
                        const rawColW = (rawColWRes && rawColWRes.value > 0) ? rawColWRes.value : 30;

                        const is2x = !!keyImg._is2x;
                        const scaleFactor = is2x ? 3.2 : 1.6;
                        const stableRefW = rawColW * scaleFactor;

                        const drawWidth = colW;
                        let drawHeight;
                        if (Math.abs(keyImg.width - stableRefW) < 1) {
                            drawHeight = drawWidth * keyImg.height / keyImg.width;
                        } else {
                            drawHeight = drawWidth * keyImg.height / stableRefW;
                        }
                        const drawX = colX;
                        const drawY = canvas.height - drawHeight;

                        ctx.drawImage(keyImg, drawX, drawY, drawWidth, drawHeight);
                    } else {
                        const pad = 8;
                        const dia = Math.max(16, Math.min(colW, keyAreaHeight) - pad * 2);
                        const drawX = colX + (colW - dia) / 2;
                        const drawY = canvas.height - dia - pad;
                        const cx = drawX + dia / 2;
                        const cy = drawY + dia / 2;
                        const r = dia / 2;

                        ctx.save();
                        if (isPressed) {
                            const gradFill = ctx.createRadialGradient(cx, cy, r * 0.2, cx, cy, r);
                            gradFill.addColorStop(0, 'rgba(235, 235, 235, 1)');
                            gradFill.addColorStop(1, 'rgba(180, 180, 180, 1)');
                            ctx.fillStyle = gradFill;
                            ctx.beginPath(); ctx.arc(cx, cy, r - 2, 0, Math.PI * 2); ctx.fill();
                            ctx.strokeStyle = '#ffffff';
                            ctx.lineWidth = 3;
                            ctx.beginPath(); ctx.arc(cx, cy, r - 2, 0, Math.PI * 2); ctx.stroke();
                        } else {
                            ctx.strokeStyle = '#ffffff';
                            ctx.lineWidth = 3;
                            ctx.beginPath(); ctx.arc(cx, cy, r - 2, 0, Math.PI * 2); ctx.stroke();
                            ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
                            ctx.beginPath(); ctx.arc(cx, cy, r - 4, 0, Math.PI * 2); ctx.fill();
                        }
                        ctx.restore();
                    }
                }
            };
        }
// --- END render/frame-key-images.js ---

// --- BEGIN render/frame-notes.js ---
// ============================================================================
// frame-notes.js - 帧内 Note 与长条头绘制
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function createNoteRenderer(context) {
            const {
                notesList, colWidths, colXCache, hitPos, currentScrollPosition,
                speedFactor, canvas, canvasEditMode, activeNoteElements, currentTime,
                resolveAnimatedNoteImage, keys, scale48, rectTop
            } = context;

            return () => {
                for (let i = 0; i < notesList.length; i++) {
                    let note = notesList[i];
                    let w = colWidths[note.column];
                    let colX = colXCache[note.column];

                    if (!note.isHold) {
                        if (note.hit) continue;
                        let bottomY = hitPos - (note.scrollPositionStart - currentScrollPosition) * speedFactor;
                        if (bottomY > canvas.height + 80 || bottomY < -80) continue;

                        let noteImg = resolveAnimatedNoteImage(LML.NoteImage, note.column, note.startTime);
                        const drawHeight = noteImg ? getManiaNoteDrawHeight(keys, note.column, noteImg, w, scale48) : Math.round(20 * scale48);

                        if (canvasEditMode && bottomY <= hitPos + 25) {
                            activeNoteElements.push({
                                id: `note_${note.column}`,
                                noteInstanceKey: `note_${note.column}_${note.startTime}`,
                                name: `第 ${note.column + 1} 轨单键`,
                                paramKey: `NoteImage${note.column}`,
                                fallbackParamKey: 'NoteImage',
                                category: 'Mania',
                                x: colX,
                                y: rectTop(bottomY - drawHeight, drawHeight),
                                w: w,
                                h: drawHeight,
                                isTexture: true,
                                textureName: getManiaNoteTextureName(keys, LML.NoteImage, note.column),
                                textureKey: LML.NoteImage,
                                colIndex: note.column,
                                dragAxis: null,
                                valFormatter: () => `第 ${note.column + 1} 轨音符`
                            });
                        }

                        if (noteImg) {
                            ctx.drawImage(noteImg, colX, bottomY - drawHeight, w, drawHeight);
                        } else {
                            const r = 4;
                            const nh = Math.round(20 * scale48 / 1.5);
                            ctx.fillStyle = note.column % 2 === 0 ? '#00e5ff' : '#ffffff';
                            roundRect(ctx, colX + 2, bottomY - nh, w - 4, nh, r);
                            ctx.fill();
                        }
                    } else {
                        if (currentTime >= note.endTime) continue;

                        const holdHeadImg = resolveAnimatedNoteImage(LML.HoldNoteHeadImage, note.column, note.startTime);
                        const headDrawHeight = holdHeadImg ? getManiaNoteDrawHeight(keys, note.column, holdHeadImg, w, scale48) : Math.round(22 * scale48 / 1.5);

                        const headAnchorY = getStableHoldHeadAnchorY(
                            note, currentScrollPosition, currentTime, hitPos, speedFactor
                        );
                        const headTopY = headAnchorY - headDrawHeight;

                        if (headAnchorY > canvas.height + 80 || headTopY < -80) continue;

                        if (canvasEditMode && headAnchorY <= hitPos + 25) {
                            activeNoteElements.push({
                                id: `hold_head_${note.column}`,
                                noteInstanceKey: `hold_head_${note.column}_${note.startTime}`,
                                name: `第 ${note.column + 1} 轨长条头`,
                                paramKey: `NoteImage${note.column}H`,
                                fallbackParamKey: 'HoldNoteHeadImage',
                                category: 'Mania',
                                x: colX,
                                y: rectTop(headTopY, headDrawHeight),
                                w: w,
                                h: headDrawHeight,
                                isTexture: true,
                                textureName: getManiaNoteTextureName(keys, LML.HoldNoteHeadImage, note.column),
                                textureKey: LML.HoldNoteHeadImage,
                                colIndex: note.column,
                                dragAxis: null,
                                valFormatter: () => `第 ${note.column + 1} 轨长条头`
                            });
                        }

                        if (holdHeadImg) {
                            ctx.drawImage(holdHeadImg, colX, headTopY, w, headDrawHeight);
                        } else {
                            const r = 4;
                            ctx.fillStyle = '#ffffff';
                            roundRect(ctx, colX + 2, headTopY, w - 4, headDrawHeight, r);
                            ctx.fill();
                            if (note.holdHeadFrozen) {
                                ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
                                ctx.fillRect(colX + 2, headAnchorY - 3, w - 4, 3);
                            }
                        }
                    }
                }
            };
        }
// --- END render/frame-notes.js ---

// --- BEGIN render/frame-stage-light.js ---
// ============================================================================
// frame-stage-light.js - 帧内 StageLight 按键光柱绘制
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function renderStageLightColumns(context) {
            const {
                ctx, keys, columnPressed, columnLastReleaseTime, currentTime,
                stageLightPreviewActive, colWidths, colXCache, stageLightPosY,
                stageLightFps, stageLightFadeDuration, scale768, rectTop
            } = context;
            const STAGE_LIGHT_FADE_DURATION = stageLightFadeDuration;
            const activeStageLightBoxes = [];
            for (let i = 0; i < keys; i++) {
                let animAlpha = 0;
                let animScaleY = 0;

                if (columnPressed[i] || stageLightPreviewActive) {
                    animAlpha = 1.0;
                    animScaleY = 1.0;
                } else if (columnLastReleaseTime[i] > -Infinity) {
                    const elapsed = currentTime - columnLastReleaseTime[i];
                    if (elapsed >= 0 && elapsed < STAGE_LIGHT_FADE_DURATION) {
                        const p = elapsed / STAGE_LIGHT_FADE_DURATION;
                        animAlpha = 1.0 - p;
                        animScaleY = 1.0 - p;
                    }
                }

                if (animAlpha <= 0 || animScaleY <= 0) continue;

                const frames = getStageLightFrames(keys, i);
                if (!frames || frames.length === 0) continue;

                const frameIdx = (frames.length > 1)
                    ? Math.floor(((currentTime || performance.now()) / 1000 * stageLightFps) % frames.length)
                    : 0;
                const img = frames[frameIdx];
                if (!img || img.width <= 0 || img.height <= 0) continue;
                // 若贴图为 1x1 占位透明图，则无需绘制
                if (img.width <= 1 || img.height <= 1) continue;

                const is2x = !!img._is2x;
                const nativeH = is2x ? img.height / 2 : img.height;
                const colW = colWidths[i] || colWidths[0];
                const colX = colXCache[i];

                // 轨道变宽时进行横向拉伸充满轨道 (drawW = colW)；
                // 垂直高度保持为 nativeH * scale768，不随轨道宽度等比暴涨；同时随释放动画按 animScaleY 向底端判定线收缩
                const drawW = colW;
                const drawH = nativeH * scale768 * animScaleY;
                const drawX = colX;
                const drawY = stageLightPosY - drawH;

                activeStageLightBoxes.push({
                    col: i,
                    x: drawX,
                    y: rectTop(drawY, drawH),
                    w: drawW,
                    h: drawH
                });

                const colLight = getManiaColourLight(keys, i);
                const isWhite = (colLight.r === 255 && colLight.g === 255 && colLight.b === 255);
                // 对齐 lazer LegacyColourCompatibility.DisallowZeroAlpha：
                //   `if (colour.A == 0) colour.A = 1;`
                // 即 alpha=0 会被强制改成「全不透明」，所以 skin.ini 写 `ColourLight1: 255,0,0,0`
                // 在游戏里是「不透明红光」而不是「看不见」。想彻底隐藏发光请用 StageLight: blank。
                const rawLightA = (colLight.a != null && !isNaN(colLight.a)) ? colLight.a : 255;
                const effectiveLightA = (rawLightA === 0) ? 255 : rawLightA;
                const skinAlpha = effectiveLightA / 255;
                const finalAlpha = skinAlpha * animAlpha;

                ctx.save();
                ctx.globalCompositeOperation = 'lighter';
                ctx.globalAlpha = finalAlpha;
                if (!isWhite) {
                    const tinted = getTintedLightCanvas(img, colLight);
                    ctx.drawImage(tinted, drawX, drawY, drawW, drawH);
                } else {
                    ctx.drawImage(img, drawX, drawY, drawW, drawH);
                }
                ctx.restore();
            }
            return activeStageLightBoxes;
        }
// --- END render/frame-stage-light.js ---

// --- BEGIN render/frame-lighting.js ---
// ============================================================================
// frame-lighting.js - 帧内 LightingN 与 LightingL 打击特效
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function renderLightingEffects(context) {
            const {
                ctx, isPreviewMode, notesList, currentTime, keys, colXCache, colWidths,
                scale768, scale48, canvasEditMode, selectedCanvasElement,
                activeExplosions, effectAnimClockMs, lightPosY, lightFps, rectTop
            } = context;
            const activeLightingBoxes = [];
            const pushLightingBox = (kind, col, drawW, drawH) => {
                const colX = colXCache[col];
                const colW = colWidths[col] || colWidths[0];
                const cx = colX + colW / 2;
                activeLightingBoxes.push({
                    kind: kind, col: col,
                    x: cx - drawW / 2,
                    y: rectTop(lightPosY - drawH / 2, drawH),
                    w: drawW, h: drawH
                });
            };

            // 渲染 LightingL: 当前正在按住的长条（对齐 osu!lazer LegacySkin / HoldNoteLightScale）
            if (!isPreviewMode) {
                for (let i = 0; i < notesList.length; i++) {
                    const note = notesList[i];
                    if (!note.isHold) continue;
                    if (currentTime >= note.startTime && currentTime <= note.endTime) {
                        const col = note.column;
                        const frames = getManiaSkinAnimationFrames(keys, LML.HoldNoteLightImage, col);
                        let drewLight = false;
                        if (frames && frames.length > 0) {
                            const frameIdx = Math.floor(((currentTime - note.startTime) / 1000) * lightFps) % frames.length;
                            const img = frames[frameIdx];
                            if (img && img.width > 0 && img.height > 0) {
                                const colX = colXCache[col];
                                const colW = colWidths[col] || colWidths[0];
                                // 对齐 osu!lazer: HoldNoteLightScale 缩放 (LightingLWidth / 30 或 ColumnWidth / 30)
                                const hlsRes = getManiaSkinConfig(keys, LML.HoldNoteLightScale, col);
                                const holdLightScale = (hlsRes && hlsRes.value > 0) ? hlsRes.value : 1.0;
                                const is2x = !!img._is2x;
                                const nativeW = is2x ? img.width / 2 : img.width;
                                const nativeH = is2x ? img.height / 2 : img.height;
                                const drawW = nativeW * scale768 * holdLightScale;
                                const drawH = nativeH * scale768 * holdLightScale;
                                const cx = colX + colW / 2;

                                ctx.save();
                                ctx.globalCompositeOperation = 'lighter';
                                ctx.globalAlpha = 0.9;
                                ctx.drawImage(img, cx - drawW / 2, lightPosY - drawH / 2, drawW, drawH);
                                ctx.restore();
                                if (canvasEditMode) pushLightingBox('LightingL', col, drawW, drawH);
                                drewLight = true;
                            }
                        }
                        // 皮肤里没有 LightingL 贴图时，仍按 30px 等效尺寸登记可点选区域，便于导入贴图
                        if (!drewLight && canvasEditMode) {
                            const fb = 30 * scale48;
                            pushLightingBox('LightingL', col, fb, fb);
                        }
                    }
                }
            }

            // 渲染 LightingN: 单键命中爆炸特效 (对齐 osu!lazer LegacyHitExplosion 与 ExplosionScale)
            // 用特效动画时钟而非 performance.now()：暂停时 elapsed 不再增长，
            // 爆炸特效会定格在暂停那一刻（否则 200ms 后就消失，根本来不及点选）。
            const now = effectAnimClockMs;

            for (let i = activeExplosions.length - 1; i >= 0; i--) {
                const exp = activeExplosions[i];
                const elapsed = now - exp.hitTime;
                if (elapsed < 0 || elapsed > exp.duration) {
                    activeExplosions.splice(i, 1);
                    continue;
                }

                const col = exp.column;
                const frames = getManiaSkinAnimationFrames(keys, LML.ExplosionImage, col);
                if (!frames || frames.length === 0) {
                    // 皮肤里没有 LightingN 贴图时，仍按 30px 等效尺寸登记可点选区域，便于导入贴图
                    if (canvasEditMode) {
                        const fb = 30 * scale48;
                        pushLightingBox('LightingN', col, fb, fb);
                    }
                    continue;
                }

                // 对齐 osu!lazer: FadeInFromZero(80) -> FadeOut(120), 寿命 200ms
                let alpha = 1.0;
                if (elapsed < 80) {
                    alpha = Math.min(1.0, elapsed / 80.0);
                } else {
                    alpha = Math.max(0.0, 1.0 - (elapsed - 80.0) / 120.0);
                }

                let img = null;
                if (frames.length === 1) {
                    img = frames[0];
                } else {
                    // 对齐 osu!lazer LegacyHitExplosion: frameLength = Math.Max(1000 / 60.0, 170.0 / frameCount)
                    const frameLength = Math.max(1000 / 60.0, 170.0 / frames.length);
                    const frameIdx = Math.floor(elapsed / frameLength);
                    if (frameIdx >= frames.length) {
                        img = frames[frames.length - 1];
                    } else {
                        img = frames[frameIdx];
                    }
                }
                if (img && img.width > 0 && img.height > 0) {
                    const colX = colXCache[col];
                    const colW = colWidths[col] || colWidths[0];
                    // 对齐 osu!lazer: ExplosionScale 缩放 (LightingNWidth / 30 或 ColumnWidth / 30)
                    const expScaleRes = getManiaSkinConfig(keys, LML.ExplosionScale, col);
                    const explosionScale = (expScaleRes && expScaleRes.value > 0) ? expScaleRes.value : 1.0;
                    const is2x = !!img._is2x;
                    const nativeW = is2x ? img.width / 2 : img.width;
                    const nativeH = is2x ? img.height / 2 : img.height;
                    const drawW = nativeW * scale768 * explosionScale;
                    const drawH = nativeH * scale768 * explosionScale;
                    const cx = colX + colW / 2;

                    ctx.save();
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.globalAlpha = alpha;
                    ctx.drawImage(img, cx - drawW / 2, lightPosY - drawH / 2, drawW, drawH);
                    ctx.restore();
                    if (canvasEditMode) pushLightingBox('LightingN', col, drawW, drawH);
                }
            }

            // 选中打击特效元素时，常驻渲染一帧该特效，方便实时观察宽度调整效果。
            // 仅当本帧该轨该特效尚未被激活渲染时才补充，避免重复绘制。
            if (canvasEditMode && selectedCanvasElement &&
                selectedCanvasElement.dragType === 'lighting_width' && selectedCanvasElement.colIndex != null) {
                const selCol = selectedCanvasElement.colIndex;
                const selKind = (selectedCanvasElement.textureParamKey === 'LightingL') ? 'LightingL' : 'LightingN';
                const alreadyActive = activeLightingBoxes.some(b => b.kind === selKind && b.col === selCol);
                if (!alreadyActive) {
                    const selLookup = (selKind === 'LightingL') ? LML.HoldNoteLightImage : LML.ExplosionImage;
                    const selScaleLookup = (selKind === 'LightingL') ? LML.HoldNoteLightScale : LML.ExplosionScale;
                    const selFrames = getManiaSkinAnimationFrames(keys, selLookup, selCol);
                    const selImg = (selFrames && selFrames.length > 0) ? selFrames[0] : getManiaSkinImage(keys, selLookup, selCol);
                    if (selImg && selImg.width > 0 && selImg.height > 0) {
                        const selScaleRes = getManiaSkinConfig(keys, selScaleLookup, selCol);
                        const selScale = (selScaleRes && selScaleRes.value > 0) ? selScaleRes.value : 1.0;
                        const is2x = !!selImg._is2x;
                        const nativeW = is2x ? selImg.width / 2 : selImg.width;
                        const nativeH = is2x ? selImg.height / 2 : selImg.height;
                        const drawW = nativeW * scale768 * selScale;
                        const drawH = nativeH * scale768 * selScale;
                        const colX = colXCache[selCol];
                        const colW = colWidths[selCol] || colWidths[0];
                        const cx = colX + colW / 2;
                        ctx.save();
                        ctx.globalCompositeOperation = 'lighter';
                        ctx.globalAlpha = 0.85;
                        ctx.drawImage(selImg, cx - drawW / 2, lightPosY - drawH / 2, drawW, drawH);
                        ctx.restore();
                        pushLightingBox(selKind, selCol, drawW, drawH);
                    } else {
                        const fb = 30 * scale48;
                        pushLightingBox(selKind, selCol, fb, fb);
                    }
                }
            }
            return activeLightingBoxes;
        }
// --- END render/frame-lighting.js ---

// --- BEGIN render/frame-playfield.js ---
// ============================================================================
// frame-playfield.js - Mania 轨道背景、分界线、小节线与判定线绘制
// 从 render/frame.js 按帧内职责拆分；共享数据通过 context 显式传入。
// ============================================================================

        function renderFramePlayfield(context) {
            const {
                ctx, keys, colWidths, colSpacings, colXCache, stageSegments,
                startX, totalTrackWidth, stageSplitAfter, canvas, isUpsideDown, hitPos,
                openUpsideDownMirror, currentTime, activeScrollState, speedFactor,
                scrollDistanceAtTime, currentTimingPoints, isPreviewMode, scale48,
                scale768, globalSkinVersion, getManiaConfigForKeys,
                getManiaSkinConfig, getManiaSkinImage, getVisibleBarlines
            } = context;
            // 1. 舞台背景渲染（轨道底色及透明度 Colour1~ColourN / ColourColumn1~ColourColumnN）：
            // osu! 官方经典规范中轨道默认背景色为 Color4.Black (0, 0, 0, 255 - 纯黑全不透明)；
            // 皮肤若配置了 Colour# (如 0,0,0,0 全透明，或 0,0,0,200 半透明)，则严格应用对应 RGBA 颜色；
            // 连续且相同颜色的轨道区间合并渲染，消除逐轨浮点抗锯齿拼接缝，同时兼容 ColumnSpacing 间距留空与不同轨独立颜色。
            let currentSegmentColor = null;
            let segStartX = 0;
            let segWidth = 0;

            for (let i = 0; i < keys; i++) {
                const bgRes = getManiaSkinConfig(keys, LML.ColumnBackgroundColour, i);
                const c = (bgRes && bgRes.value) ? bgRes.value : { r: 0, g: 0, b: 0, a: 255 };
                // 对齐 osu!stable / lazer 历史兼容特性 (LegacyColourCompatibility.ApplyWithDoubledAlpha):
                // 在 osu!stable 构造函数中设置颜色会导致 Alpha 被重复叠加两次：
                // 当 A > 0 时实际生效透明度为 (A / 255)^2；当 A == 0 时保持 0 全透明
                const rawAlpha = (c.a != null ? c.a : 255) / 255;
                const effectiveAlpha = rawAlpha > 0 ? (rawAlpha * rawAlpha) : 0;
                const colorStr = `rgba(${c.r}, ${c.g}, ${c.b}, ${effectiveAlpha})`;
                const colW = colWidths[i] || colWidths[0] || 0;
                const colX = colXCache[i];
                const prevSpacing = (i > 0) ? (colSpacings[i - 1] || 0) : 0;
                const prevStageGap = (i > 0 && (i - 1) === stageSplitAfter) ? stageSeparationPx : 0;

                if (currentSegmentColor === null) {
                    currentSegmentColor = colorStr;
                    segStartX = colX;
                    segWidth = colW;
                } else if (prevSpacing === 0 && prevStageGap === 0 && colorStr === currentSegmentColor) {
                    segWidth += colW;
                } else {
                    if (segWidth > 0 && currentSegmentColor !== 'rgba(0, 0, 0, 0)') {
                        ctx.fillStyle = currentSegmentColor;
                        ctx.fillRect(segStartX, 0, segWidth, canvas.height);
                    }
                    currentSegmentColor = colorStr;
                    segStartX = colX;
                    segWidth = colW;
                }
            }
            if (segWidth > 0 && currentSegmentColor !== null && currentSegmentColor !== 'rgba(0, 0, 0, 0)') {
                ctx.fillStyle = currentSegmentColor;
                ctx.fillRect(segStartX, 0, segWidth, canvas.height);
            }

            // 2. 舞台左右边界底图 StageLeft / StageRight
            // 对齐 osu!lazer 核心逻辑 (LegacyStageBackground):
            // 1. 水平宽度 (X): 保持基于 768p 原生分辨率标准 (Scale.X = 1，即 nativeW * scale768)，不随 480 虚拟网格横向放大
            // 2. 垂直高度 (Y): 严格纵向拉伸至覆盖整个舞台高度 (Scale.Y = DrawHeight / Texture.Height，即 canvas.height)
            // 3. SplitStages 开启时，每一组舞台各自绘制左右边界。
            const stageLeftImg = getManiaSkinImage(keys, LML.LeftStageImage);
            let stageLeftWidth = 0;
            if (stageLeftImg && stageLeftImg.width > 0 && stageLeftImg.height > 0) {
                const is2x = !!stageLeftImg._is2x;
                const nativeW = is2x ? stageLeftImg.width / 2 : stageLeftImg.width;
                stageLeftWidth = nativeW * scale768;
            }

            let stageRightWidth = 0;
            const stageRightImg = getManiaSkinImage(keys, LML.RightStageImage);
            if (stageRightImg && stageRightImg.width > 0 && stageRightImg.height > 0) {
                const is2x = !!stageRightImg._is2x;
                const nativeW = is2x ? stageRightImg.width / 2 : stageRightImg.width;
                stageRightWidth = nativeW * scale768;
            }

            // 舞台侧图属于演奏区前景，不能继承背景或故事板残留的透明度/混合模式。
            ctx.save();
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = 'source-over';
            ctx.filter = 'none';
            for (const segment of stageSegments) {
                if (stageLeftWidth > 0) {
                    ctx.drawImage(stageLeftImg, segment.x - stageLeftWidth, 0, stageLeftWidth, canvas.height);
                }
                if (stageRightWidth > 0) {
                    ctx.drawImage(stageRightImg, segment.x + segment.width, 0, stageRightWidth, canvas.height);
                }
            }
            ctx.restore();

            // ---- 2.4 渲染轨道分界线 ColumnLineWidth ----
            // 对齐 osu!lazer LegacyStageBackground：
            // - ColumnLineWidth 长度为 keys + 1，第 i 项是第 i 轨左线，第 i + 1 项是第 i 轨右线。
            // - 该参数在 LegacyManiaSkinDecoder 中不做 1.6 倍列宽换算，因此这里按 768p 尺度绘制。
            // - 线条横向额外乘 0.740，并只绘制在判定线以上的演奏区。
            // - 非最后一轨的右线仅在 skin Version >= 2.4 时显示；颜色读取 ColourColumnLine，缺省为白色。
            const lineCfg = getManiaConfigForKeys(keys);
            const rawLineWidths = (lineCfg && Array.isArray(lineCfg.ColumnLineWidth))
                ? lineCfg.ColumnLineWidth
                : new Array(keys + 1).fill(2);
            const lineVersion = Number((lineCfg && lineCfg.SkinVersion != null) ? lineCfg.SkinVersion : globalSkinVersion);
            const effectiveLineVersion = Number.isFinite(lineVersion) ? lineVersion : 2.7;
            const lineTop = isUpsideDown ? Math.max(0, canvas.height - hitPos) : 0;
            const lineHeight = Math.max(0, Math.min(canvas.height, hitPos));
            const lineWidthScale = 0.740 * scale768;

            const parseColumnLineColour = (value) => {
                if (!value) return { r: 255, g: 255, b: 255, a: 255 };
                if (typeof value === 'object') {
                    const n = (v, fallback) => {
                        const parsed = Number(v);
                        return Number.isFinite(parsed) ? Math.max(0, Math.min(255, parsed)) : fallback;
                    };
                    return {
                        r: n(value.r, 255),
                        g: n(value.g, 255),
                        b: n(value.b, 255),
                        a: n(value.a, 255)
                    };
                }

                const text = String(value).trim();
                const rgbaMatch = text.match(/^rgba?\(([^)]+)\)$/i);
                const parts = (rgbaMatch ? rgbaMatch[1] : text).split(',').map(part => parseFloat(part.trim()));
                if (parts.length < 3 || parts.slice(0, 3).some(part => !Number.isFinite(part))) {
                    return { r: 255, g: 255, b: 255, a: 255 };
                }

                const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
                const alpha = Number.isFinite(parts[3])
                    ? (parts[3] <= 1 ? parts[3] * 255 : parts[3])
                    : 255;
                return {
                    r: clamp(parts[0], 0, 255),
                    g: clamp(parts[1], 0, 255),
                    b: clamp(parts[2], 0, 255),
                    a: clamp(alpha, 0, 255)
                };
            };

            const customLineColour = lineCfg && lineCfg.CustomColours
                ? (lineCfg.CustomColours.columnline || lineCfg.CustomColours.ColumnLine)
                : null;
            const lineColour = parseColumnLineColour(lineCfg && lineCfg.ColumnLineColour
                ? lineCfg.ColumnLineColour
                : customLineColour);
            const lineRawAlpha = lineColour.a / 255;
            // LegacyColourCompatibility.ApplyWithDoubledAlpha：Alpha 会同时作用于 Drawable.Alpha 与 Colour.Alpha。
            const lineAlpha = lineRawAlpha > 0 ? lineRawAlpha * lineRawAlpha : 0;

            if (lineHeight > 0 && lineAlpha > 0) {
                ctx.save();
                ctx.fillStyle = `rgba(${lineColour.r}, ${lineColour.g}, ${lineColour.b}, ${lineAlpha})`;
                for (let i = 0; i < keys; i++) {
                    const colX = colXCache[i];
                    const colW = colWidths[i] || colWidths[0] || 0;
                    // LegacyManiaSkinConfiguration 初始化时整组填充 2；解析时只覆盖 ini 中实际提供的项。
                    const leftRaw = rawLineWidths[i] == null ? 2 : Number(rawLineWidths[i]);
                    const rightRaw = rawLineWidths[i + 1] == null ? 2 : Number(rawLineWidths[i + 1]);
                    const leftWidth = Number.isFinite(leftRaw) && leftRaw > 0 ? leftRaw * lineWidthScale : 0;
                    const rightWidth = Number.isFinite(rightRaw) && rightRaw > 0 ? rightRaw * lineWidthScale : 0;

                    if (leftWidth > 0) {
                        ctx.fillRect(colX, lineTop, leftWidth, lineHeight);
                    }

                    const showRightLine = rightWidth > 0 && (effectiveLineVersion >= 2.4 || i === keys - 1);
                    if (showRightLine) {
                        const rightLineX = colX + colW - rightWidth + ((i === keys - 1) ? -0.16 * scale768 : 0);
                        ctx.fillRect(rightLineX, lineTop, rightWidth, lineHeight);
                    }
                }
                ctx.restore();
            }

            // ---- 2.5 渲染小节线 (BarLine) ----
            // 从这里开始进入 Mania 演奏区：UpsideDown 时整体镜像绘制
            openUpsideDownMirror();
            const blhRes = getManiaSkinConfig(keys, LML.BarLineHeight);
            const barLineHeightRaw = (blhRes && blhRes.value != null && !isNaN(blhRes.value)) ? blhRes.value : 1.2;
            if (barLineHeightRaw > 0) {
                const cbRes = getManiaSkinConfig(keys, LML.ColourBarline);
                const cbCol = (cbRes && cbRes.value) ? cbRes.value : { r: 255, g: 255, b: 255, a: 255 };
                const baseAlpha = ((cbCol.a != null) ? cbCol.a : 255) / 255;

                if (baseAlpha > 0) {
                    const barLineH = Math.max(1, Math.round(barLineHeightRaw * scale48));
                    const currentMultiplier = Math.max(0.001, getManiaScrollMultiplierAt(currentTime, activeScrollState));
                    const effectiveSpeedFactor = speedFactor * currentMultiplier;
                    const visibleTimeAhead = (hitPos + 40) / effectiveSpeedFactor;
                    const minTime = currentTime - (25 / effectiveSpeedFactor);
                    const maxTime = currentTime + visibleTimeAhead;

                    const barlineYs = getVisibleBarlines(
                        currentTimingPoints,
                        currentTime,
                        minTime,
                        maxTime,
                        isPreviewMode,
                        (time) => hitPos - scrollDistanceAtTime(time),
                        hitPos,
                        false // 演奏区已整体镜像，这里统一按下落坐标系计算
                    );

                    if (barlineYs && barlineYs.length > 0) {
                        ctx.save();
                        for (let i = 0; i < barlineYs.length; i++) {
                            const by = barlineYs[i];
                            let alpha = baseAlpha;
                            if (by > hitPos) {
                                const fadeOutDist = 20;
                                const dist = by - hitPos;
                                alpha = Math.max(0, baseAlpha * (1 - dist / fadeOutDist));
                            }
                            if (alpha <= 0) continue;

                            ctx.fillStyle = `rgba(${cbCol.r}, ${cbCol.g}, ${cbCol.b}, ${alpha})`;
                            for (const segment of stageSegments) {
                                ctx.fillRect(segment.x, Math.round(by - barLineH / 2), segment.width, barLineH);
                            }
                        }
                        ctx.restore();
                    }
                }
            }

            // 3. 判定线与打击点贴图 StageHint (HitTarget)
            const sjRes = getManiaSkinConfig(keys, LML.ShowJudgementLine);
            const showLine = sjRes ? sjRes.value : true;

            // 3a. 渲染打击点贴图 StageHint（按轨道或跨整轨渲染，即使 JudgementLine 为 0 亦独立渲染）
            const stageHintGlobal = getManiaSkinImage(keys, LML.HitTargetImage);

            let hasPerColHint = false;
            for (let i = 0; i < keys; i++) {
                const colHt = getManiaSkinImage(keys, LML.HitTargetImage, i);
                if (colHt !== stageHintGlobal) {
                    hasPerColHint = true;
                    break;
                }
            }

            if (hasPerColHint) {
                for (let i = 0; i < keys; i++) {
                    const colX = colXCache[i];
                    const w = colWidths[i] || colWidths[0];
                    const htImg = getManiaSkinImage(keys, LML.HitTargetImage, i);
                    if (htImg && htImg.width > 0 && htImg.height > 0) {
                        const is2x = !!htImg._is2x;
                        const nativeH = is2x ? htImg.height / 2 : htImg.height;
                        const drawH = nativeH * scale48;
                        ctx.save();
                        ctx.beginPath();
                        ctx.rect(colX, hitPos - drawH / 2, w, drawH);
                        ctx.clip();
                        ctx.drawImage(htImg, colX, hitPos - drawH / 2, w, drawH);
                        ctx.restore();
                    }
                }
            } else if (stageHintGlobal && stageHintGlobal.width > 0 && stageHintGlobal.height > 0) {
                const is2x = !!stageHintGlobal._is2x;
                const nativeH = is2x ? stageHintGlobal.height / 2 : stageHintGlobal.height;
                const drawH = nativeH * scale48;
                // 对齐 osu! stable 与 lazer 规范 (参考实测图1): mania-stage-hint 贯穿整轨连续显示，即使有轨道间距也保持连续不断开
                // SplitStages 开启时按左右舞台分别连续绘制，舞台之间的 StageSeparation 保持留空。
                for (const segment of stageSegments) {
                    ctx.drawImage(stageHintGlobal, segment.x, hitPos - drawH / 2, segment.width, drawH);
                }
            }

            // 3b. 若 ShowJudgementLine 为 true (配置 1 或默认)，渲染白色判定横线。
            // KeyImage 在后续帧步骤里画在判定线之上，用普通 source-over 叠上去：
            // 不透明像素盖住判定线，alpha=0 的透明区域仍能看到下面的判定线。
            if (showLine) {
                ctx.fillStyle = '#ffffff';
                for (const segment of stageSegments) {
                    ctx.fillRect(segment.x, hitPos - 1, segment.width, 2);
                }
            }

            // 3c. 渲染轨道按键光效 StageLight (mania-stage-light)
            // 依据 skin.ini 中的 LightPosition (默认 413 或 HitPosition) 与 ColourLight 配置
            // 对齐 osu!lazer LegacyColumnBackground: 按下时 FadeIn & Scale(1, 1)，松开时 250ms 内 FadeTo(0) & Scale(1, 0)
            const stageLightLpRes = getManiaSkinConfig(keys, LML.LightPosition);
            const stageLightPosRaw = (stageLightLpRes && stageLightLpRes.value != null && !isNaN(stageLightLpRes.value)) ? stageLightLpRes.value : (hitPos / scale48);
            const stageLightPosY = stageLightPosRaw * scale48;
            const stageLightFpsRes = getManiaSkinConfig(keys, LML.LightFramePerSecond);
            const stageLightFps = (stageLightFpsRes && stageLightFpsRes.value > 0) ? stageLightFpsRes.value : 60;
            const STAGE_LIGHT_FADE_DURATION = STAGE_LIGHT_FADE_DURATION_MS; // osu!lazer LegacyColumnBackground 经典松开动画时长 (ms)
            // 参数面板「预览发光」按钮：在 testLightUntil 到期前把所有轨道视为「按下」。
            // 发光只在按住期间可见，没有这个开关就没法在编辑器里直接看到 ColourLight 的改色效果。
            const stageLightPreviewActive = (performance.now() < testLightUntil);

            // 本帧「真实渲染出来」的按键发光 (StageLight) 矩形（真实屏幕坐标）。
            // 画布交互层据此判断可见光柱的范围：只有按下按键 / 开启预览时才有可见光柱，
            // 才能通过点击光柱本体选中「按键发光位置」。常驻的细手柄由画布交互层单独维护。

            return {
                showLine, stageLightLpRes, stageLightPosY, stageLightFps,
                stageLightFadeDuration: STAGE_LIGHT_FADE_DURATION,
                stageLightPreviewActive
            };
        }
// --- END render/frame-playfield.js ---

// --- BEGIN render/frame.js ---
// ============================================================================
// frame.js - 主 Canvas 帧绘制：背景、轨道、音符、长条与特效
// 依赖：render/textures.js、render/combo.js、core/state.js
// ============================================================================

        // 后台节流或页面卡顿恢复后，不能把已经错过的整段时间集中补播。
        const PLAYBACK_EVENT_MAX_LATENESS_MS = 100;

        function isPlaybackEventFresh(eventTime, currentTime) {
            const lateness = Number(currentTime) - Number(eventTime);
            return Number.isFinite(lateness) &&
                lateness >= 0 &&
                lateness <= PLAYBACK_EVENT_MAX_LATENESS_MS;
        }

        // osu!stable 长条时间锚点：
        // - 头部贴图下端在 startTime 对应位置；按住后固定在判定线。
        // - 尾部贴图下端在 endTime 对应位置。
        function getStableHoldHeadAnchorY(note, currentScrollPosition, currentTime, hitPos, speedFactor) {
            if (currentTime < note.startTime) {
                return hitPos - (note.scrollPositionStart - currentScrollPosition) * speedFactor;
            }
            return hitPos;
        }

        function getStableHoldTailAnchorY(note, currentScrollPosition, hitPos, speedFactor) {
            return hitPos - (note.scrollPositionEnd - currentScrollPosition) * speedFactor;
        }

        // 身体长度只等于头尾两个下端锚点之间的距离，不包含头部半高，也不受尾巴顶端影响。
        // 身体近端位于头部贴图中心，因此远端自然为“尾端锚点 - 头部半高”。
        function getStableHoldNoteGeometry(note, currentScrollPosition, currentTime, hitPos, speedFactor, headHeight, tailHeight) {
            const headAnchorY = getStableHoldHeadAnchorY(
                note, currentScrollPosition, currentTime, hitPos, speedFactor
            );
            const tailAnchorY = getStableHoldTailAnchorY(
                note, currentScrollPosition, hitPos, speedFactor
            );
            const headTopY = headAnchorY - headHeight;
            const headCenterY = headAnchorY - headHeight / 2;
            const tailTopY = tailAnchorY - tailHeight;
            const bodyBottomY = headCenterY;
            const bodyLength = Math.max(0, headAnchorY - tailAnchorY);
            const bodyTopY = bodyBottomY - bodyLength;

            return {
                headAnchorY,
                headTopY,
                headCenterY,
                tailAnchorY,
                tailTopY,
                bodyTopY,
                bodyBottomY,
                bodyLength,
                bodyHeight: Math.max(0, bodyBottomY - bodyTopY),
                headFrozen: currentTime >= note.startTime
            };
        }

        // NoteBodyStyle 只负责身体矩形内部的贴图取样方式，不改变身体矩形本身。
        function drawStableHoldBodyTexture(targetCtx, image, style, x, width, bodyTopY, bodyHeight) {
            if (!image || width <= 0 || bodyHeight <= 0.5) return;

            const nativeW = image.width || 1;
            const nativeH = image.height || 1;
            const scaledNativeH = Math.max(1, nativeH * (width / nativeW));
            const bodyBottomY = bodyTopY + bodyHeight;

            targetCtx.save();
            targetCtx.beginPath();
            targetCtx.rect(x, bodyTopY, width, bodyHeight);
            targetCtx.clip();

            if (style === NOTE_BODY_STYLE.Stretch) {
                targetCtx.drawImage(image, x, bodyTopY, width, bodyHeight);
            } else if (style === NOTE_BODY_STYLE.RepeatTopAndBottom) {
                for (let y = bodyTopY; y < bodyBottomY; y += scaledNativeH) {
                    targetCtx.drawImage(image, x, y, width, scaledNativeH);
                }
                for (let y = bodyBottomY; y > bodyTopY; y -= scaledNativeH) {
                    targetCtx.drawImage(image, x, y - scaledNativeH, width, scaledNativeH);
                }
            } else if (style === NOTE_BODY_STYLE.RepeatFromHead) {
                for (let y = bodyBottomY; y > bodyTopY; y -= scaledNativeH) {
                    targetCtx.drawImage(image, x, y - scaledNativeH, width, scaledNativeH);
                }
            } else {
                for (let y = bodyTopY; y < bodyBottomY; y += scaledNativeH) {
                    targetCtx.drawImage(image, x, y, width, scaledNativeH);
                }
            }

            targetCtx.restore();
        }

        function drawFrame() {
            // 纯皮肤预览（无谱面）时若渲染了多帧贴图，需要在函数末尾保持 rAF 循环，动画才会真正播放。
            let skinFrameAnimationActive = false;
            let comboburstAnimationActive = false;
            try {
                // 特效动画时钟：播放时前进、暂停时冻结（见 config.js updateEffectAnimClock）
                updateEffectAnimClock();
                if (canvas && canvas.clientWidth > 0 && canvas.clientHeight > 0) {
                    if (canvas.width !== canvas.clientWidth || canvas.height !== canvas.clientHeight) {
                        canvas.width = canvas.clientWidth;
                        canvas.height = canvas.clientHeight;
                    }
                }
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = '#000';
                ctx.fillRect(0, 0, canvas.width, canvas.height);

                let currentTime = 0;
                if (currentBeatmap) {
                    const playbackTime = (isSeeking && ui.progressRange)
                        ? parseFloat(ui.progressRange.value)
                        : getPlaybackTimeSeconds();
                    currentTime = playbackTime * 1000;
                    syncStoryboardVideoToTime(currentTime, isPlaying);
                    if (!isSeeking && isPlaying && ui.progressRange) {
                        ui.progressRange.value = playbackTime;
                        const totalDuration = (audio.duration && isFinite(audio.duration) && audio.duration > 0)
                            ? audio.duration
                            : parseFloat(ui.progressRange.max) || 0;
                        updateTimeLabels(playbackTime, totalDuration);
                        updateProgressFill(playbackTime, totalDuration);
                    }
                }

                // ---- 背景渲染、淡入淡出过渡动画与背景暗化 ----
                let hasStoryboardBackground = false;
                if (hasCanvasBg && canvasBgImage && canvasBgImage.complete) {
                    const elapsed = performance.now() - bgFadeStartTime;
                    const fadeProgress = Math.min(1.0, Math.max(0, elapsed / BG_FADE_DURATION));
                    const isFading = (fadeProgress < 1.0);

                    // 1. 若处于切换过渡中且有上一张背景，先以 (1 - fadeProgress) 淡出上一张背景图
                    if (isFading && prevCanvasBgImage && prevCanvasBgImage.complete) {
                        ctx.save();
                        ctx.globalAlpha = 1.0 - fadeProgress;
                        drawCoverImage(ctx, prevCanvasBgImage, canvas.width, canvas.height);
                        ctx.restore();
                    }

                    // 2. 绘制当前新背景图 (若处于淡入中，透明度为 fadeProgress)
                    const currentAlpha = isFading ? fadeProgress : 1.0;
                    ctx.save();
                    ctx.globalAlpha = currentAlpha;
                    drawCoverImage(ctx, canvasBgImage, canvas.width, canvas.height);
                    ctx.restore();

                    // 如果暂停状态下背景淡入淡出过渡尚未完成，继续请求动画帧驱动过渡
                    if (!isPlaying && isFading) {
                        cancelAnimationFrame(animationId);
                        animationId = requestAnimationFrame(drawFrame);
                    } else if (!isFading) {
                        prevCanvasBgImage = null;
                    }
                }

                hasStoryboardBackground = drawStoryboardComposite(
                    ctx,
                    currentTime,
                    canvas.width,
                    canvas.height
                );

                // 背景暗化统一作用于静态图、视频和故事板背景。
                const dimFactor = Math.min(1.0, Math.max(0, bgDim / 100));
                const hasBackgroundContent = hasCanvasBg || hasStoryboardBackground ||
                    !!(storyboardPlaybackState && storyboardPlaybackState.elements.length > 0);
                if (hasBackgroundContent && dimFactor > 0) {
                    ctx.fillStyle = `rgba(0, 0, 0, ${dimFactor})`;
                    ctx.fillRect(0, 0, canvas.width, canvas.height);
                }

                // 启动流程中先只展示谱面背景；皮肤来源确定前不绘制舞台与音符。
                if (typeof shouldDeferSkinRendering === 'function' && shouldDeferSkinRendering()) {
                    return;
                }

                let keys;
                let notesList = activeNotes;
                isPreviewMode = false;

                if (currentBeatmap) {
                    keys = Math.round(currentBeatmap.difficulty.circleSize);
                } else if (skinImageStore.size > 0 || skinFallbackImageStore.size > 0 || maniaSkinConfigurations.size > 0) {
                    isPreviewMode = true;
                    if (activeEditorKeyCount) {
                        keys = activeEditorKeyCount;
                    } else if (maniaSkinConfigurations.has(4)) {
                        keys = 4;
                    } else if (maniaSkinConfigurations.size > 0) {
                        keys = maniaSkinConfigurations.keys().next().value || 4;
                    } else {
                        keys = 4;
                    }
                } else {
                    // 未导入谱面且未导入自定义皮肤，保持纯净背景，不渲染默认预览舞台
                    return;
                }

                // skin.ini 坐标体系基于 480 虚拟网格 (HitPosition, ColumnWidth 等)，而贴图资源原生基于 768p (1x) / 1536p (2x) 分辨率
                const scale48 = canvas.height / 480;
                const scale768 = canvas.height / 768;

                // LegacyNotePiece 序列帧使用 [General] AnimationFramerate，并以所属 HitObject 的
                // AnimationStartTime (StartTime - 10000ms) 为相位原点。
                // 纯皮肤预览同样走这条时间轴；虚拟时钟只负责在无谱面时持续前进。
                const skinAnimationFps = getSkinAnimationFramerate();
                const skinAnimationClockMs = currentBeatmap ? currentTime : effectAnimClockMs;
                const noteFrameCache = new Map();
                const resolveNoteFrames = (lookup, col) => {
                    const cacheKey = `${lookup}|${col}`;
                    if (noteFrameCache.has(cacheKey)) return noteFrameCache.get(cacheKey);
                    const frames = getManiaSkinAnimationFrames(keys, lookup, col) || null;
                    noteFrameCache.set(cacheKey, frames);
                    return frames;
                };
                const resolveAnimatedNoteImage = (lookup, col, animationStartTimeMs = null) => {
                    const frames = resolveNoteFrames(lookup, col);
                    if (frames && frames.length > 1) skinFrameAnimationActive = true;
                    const animationClockMs = Number.isFinite(animationStartTimeMs)
                        ? getLegacyNoteAnimationClockMs(skinAnimationClockMs, animationStartTimeMs)
                        : skinAnimationClockMs;
                    return selectSkinAnimationFrame(frames, animationClockMs, skinAnimationFps)
                        || getManiaSkinImage(keys, lookup, col);
                };

                const udRes = getManiaSkinConfig(keys, LML.UpsideDown);
                const isUpsideDown = (udRes && (udRes.value === true || udRes.value === 1 || udRes.value === '1'));

                let colWidths = [];
                for (let i = 0; i < keys; i++) {
                    const res = getManiaSkinConfig(keys, LML.ColumnWidth, i);
                    const rawW = (res && res.value > 0) ? res.value : 30;
                    colWidths.push(rawW * scale48);
                }

                let colSpacings = [];
                for (let i = 0; i < keys; i++) {
                    const res = getManiaSkinConfig(keys, LML.ColumnSpacing, i);
                    const rawS = (res && res.value > 0) ? res.value : 0;
                    colSpacings.push(rawS * scale48);
                }

                const colStartRes = getManiaSkinConfig(keys, LML.ColumnStart);
                const columnStartRaw = (colStartRes && colStartRes.value != null) ? colStartRes.value : 136;
                const startX = columnStartRaw * scale48;

                const splitStagesRes = getManiaSkinConfig(keys, LML.SplitStages);
                const splitStages = isManiaSplitStagesEnabled(
                    { SplitStages: splitStagesRes && splitStagesRes.value },
                    keys
                );
                const stageSplitAfter = splitStages ? getManiaStageSplitAfter(keys) : -1;
                const stageSeparationRes = getManiaSkinConfig(keys, LML.StageSeparation);
                const stageSeparationRaw = (stageSeparationRes && stageSeparationRes.value != null && !isNaN(stageSeparationRes.value))
                    ? Math.max(0, parseFloat(stageSeparationRes.value))
                    : 40;
                const stageSeparationPx = (stageSplitAfter >= 0) ? stageSeparationRaw * scale48 : 0;

                const totalTrackWidth = colWidths.reduce((a, b) => a + b, 0)
                    + colSpacings.slice(0, keys - 1).reduce((a, b) => a + b, 0)
                    + stageSeparationPx;
                const trailingSpacing = colSpacings[keys - 1] || 0;

                const hpRes = getManiaSkinConfig(keys, LML.HitPosition);
                const hitPos = ((hpRes && hpRes.value) ? hpRes.value : DEFAULT_HIT_POSITION) * scale48;

                // ---- UpsideDown (上下颠倒 / 上升模式) 坐标体系说明 ----
                // 整个 Mania 演奏区（小节线 / 判定线 / 按键 / 音符 / 长条 / 特效 / 舞台底图）
                // 在开启 UpsideDown 时沿画布垂直中线整体镜像：音符自下而上运动，按键与判定线移到上方。
                // 实现方式：演奏区内部仍然全部按「下落坐标系」计算 Y（沿用原有代码，无需逐个翻转），
                // 只需在演奏区绘制前后各加一次 canvas 镜像变换（见下方 openUpsideDownMirror / closeUpsideDownMirror），
                // 这样贴图内容与位置会一起被镜像，无需为每张贴图单独写翻转逻辑。
                // 例外：交互元素外接矩形（activeNoteElements / canvasInteractiveElements）必须记录真实屏幕坐标，
                // 因此用 rectTop() 把下落坐标系中的矩形顶端换算成镜像后的真实顶端。
                // （镜像后判定线位于 canvas.height - hitPos，按键位于其上方，音符自下而上运动。）
                const rectTop = (y, h) => (isUpsideDown ? (canvas.height - y - h) : y);
                const openUpsideDownMirror = () => {
                    if (!isUpsideDown) return;
                    ctx.save();
                    ctx.translate(0, canvas.height);
                    ctx.scale(1, -1);
                };
                const closeUpsideDownMirror = () => {
                    if (!isUpsideDown) return;
                    ctx.restore();
                };

                let scorePosFromSkin = null;
                const spRes = getManiaSkinConfig(keys, LML.ScorePosition);
                if (spRes && spRes.value != null) {
                    scorePosFromSkin = (isUpsideDown ? (480 - spRes.value) : spRes.value) * scale48;
                }

                let noteBodyStyleCfg = NOTE_BODY_STYLE.RepeatFromTail;
                const nbsRes = getManiaSkinConfig(keys, LML.NoteBodyStyle);
                if (nbsRes && nbsRes.value !== null && nbsRes.value !== undefined) noteBodyStyleCfg = nbsRes.value;

                // 对齐 osu!stable / lazer 机制的流速计算：
                // 1. scrollSpeed 在 [1, 40] 范围内，可见时间窗口 scrollTime = MAX_TIME_RANGE / scrollSpeed (MAX_TIME_RANGE = 11485)
                // 2. 基础像素速度 = (DEFAULT_HIT_POSITION / scrollTime) * scale48 (DEFAULT_HIT_POSITION = 402)
                // 3. 该机制使音符实际下落流速严格恒定，独立于 skin.ini 自定义的 HitPosition
                const speedFactor = getManiaSpeedFactor(scrollSpeed, scale48);
                const activeScrollState = isPreviewMode ? null : currentManiaScrollState;
                const currentScrollPosition = getManiaScrollPositionAt(currentTime, activeScrollState);
                const scrollDistanceAtTime = (time) => {
                    return (getManiaScrollPositionAt(time, activeScrollState) - currentScrollPosition) * speedFactor;
                };

                if (isPreviewMode) {
                    notesList = [];
                    for (let c = 0; c < keys; c++) {
                        const isHoldCol = (c === 1 || (keys > 4 && c === keys - 2));
                        // 预览音符间距同样基于 480 虚拟网格，需乘 scale48 才能在不同画布尺寸下保持
                        // 与真实演奏一致的相对布局（否则全屏时音符会全部挤在命中线附近）。
                        const noteDist = (120 + (c % 4) * 80) * scale48;
                        const startTime = (noteDist / speedFactor);
                        if (isHoldCol) {
                            const endTime = ((noteDist + 160 * scale48) / speedFactor);
                            notesList.push({
                                column: c,
                                isHold: true,
                                startTime: startTime,
                                endTime: endTime,
                                scrollPositionStart: startTime,
                                scrollPositionEnd: endTime,
                                hit: false,
                                holdHeadFrozen: false
                            });
                        } else {
                            notesList.push({
                                column: c,
                                isHold: false,
                                startTime: startTime,
                                endTime: startTime,
                                scrollPositionStart: startTime,
                                scrollPositionEnd: startTime,
                                hit: false
                            });
                        }
                    }
                }

                let columnPressed = Array(keys).fill(false);
                let columnLastReleaseTime = Array(keys).fill(-Infinity);
                const KEY_PRESS_DURATION = 90; // 单键音符贴图触碰判定线后的按键高亮时长(ms)

                for (let i = 0; i < notesList.length; i++) {
                    let note = notesList[i];
                    const col = note.column;
                    if (col < 0 || col >= keys) continue;
                    const noteEndTime = note.isHold ? note.endTime : (note.startTime + KEY_PRESS_DURATION);
                    if (currentTime >= note.startTime && currentTime <= noteEndTime) {
                        columnPressed[col] = true;
                    } else if (currentTime > noteEndTime) {
                        if (noteEndTime > columnLastReleaseTime[col]) {
                            columnLastReleaseTime[col] = noteEndTime;
                        }
                    }
                }

                let currentX = startX;
                const colXCache = [];
                for (let i = 0; i < keys; i++) {
                    colXCache.push(currentX);
                    const w = colWidths[i] || colWidths[0];
                    currentX += w;
                    if (i < keys - 1) {
                        currentX += (colSpacings[i] || 0);
                        if (i === stageSplitAfter) currentX += stageSeparationPx;
                    }
                }

                const stageSegments = [];
                if (stageSplitAfter >= 0) {
                    const firstStageEndX = colXCache[stageSplitAfter] + (colWidths[stageSplitAfter] || colWidths[0]);
                    const secondStageStartX = colXCache[stageSplitAfter + 1];
                    stageSegments.push({ x: startX, width: firstStageEndX - startX });
                    stageSegments.push({ x: secondStageStartX, width: startX + totalTrackWidth - secondStageStartX });
                } else {
                    stageSegments.push({ x: startX, width: totalTrackWidth });
                }

                const {
                    showLine, stageLightLpRes, stageLightPosY, stageLightFps,
                    stageLightFadeDuration: STAGE_LIGHT_FADE_DURATION,
                    stageLightPreviewActive
                } = renderFramePlayfield({
                    ctx, keys, colWidths, colSpacings, colXCache, stageSegments,
                    startX, totalTrackWidth, stageSplitAfter, canvas, isUpsideDown, hitPos,
                    openUpsideDownMirror, currentTime, activeScrollState, speedFactor,
                    scrollDistanceAtTime, currentTimingPoints, isPreviewMode, scale48,
                    scale768, globalSkinVersion, getManiaConfigForKeys,
                    getManiaSkinConfig, getManiaSkinImage, getVisibleBarlines
                });
                const activeStageLightBoxes = renderStageLightColumns({
                    ctx, keys, columnPressed, columnLastReleaseTime, currentTime,
                    stageLightPreviewActive, colWidths, colXCache, stageLightPosY,
                    stageLightFps, stageLightFadeDuration: STAGE_LIGHT_FADE_DURATION,
                    scale768, rectTop
                });
                // ---- 计算连击数与长按状态 ----
                let currentCombo = 0;
                let isHoldingLN = false;
                if (!isPreviewMode) {
                    for (let i = 0; i < notesList.length; i++) {
                        const n = notesList[i];
                        if (n.isHold) {
                            if (currentTime >= n.startTime) {
                                currentCombo++;
                                if (currentTime < n.endTime) isHoldingLN = true;
                            }
                            // 对齐 std 模式 Slider 的 Tick 连击逻辑：长按过程中每经过一个 Tick，Combo 持续递增
                            if (n.ticks && n.ticks.length > 0) {
                                for (let k = 0; k < n.ticks.length; k++) {
                                    if (currentTime >= n.ticks[k]) {
                                        currentCombo++;
                                    } else {
                                        break;
                                    }
                                }
                            }
                            if (currentTime >= n.endTime) {
                                currentCombo++;
                            }
                        } else {
                            if (currentTime >= n.startTime) currentCombo++;
                        }
                    }
                } else {
                    currentCombo = 100;
                    isHoldingLN = false;
                    for (let i = 0; i < notesList.length; i++) {
                        const n = notesList[i];
                        if (n.isHold && currentTime >= n.startTime && currentTime < n.endTime) {
                            isHoldingLN = true;
                        }
                    }
                }

                if (performance.now() < testHoldingUntil) {
                    isHoldingLN = true;
                }
                if (performance.now() < testComboBreakUntil) {
                    currentCombo = 0;
                }
                if (isPreviewJudgementActive) {
                    if (isPlaying) {
                        if (playbackBreakResumeTime > 0 && performance.now() < playbackBreakResumeTime) {
                            currentCombo = 0;
                        }
                    } else if (isPreviewMode) {
                        if (previewBreakResumeTime > 0 && performance.now() < previewBreakResumeTime) {
                            currentCombo = 0;
                        } else {
                            currentCombo = previewSimCombo;
                        }
                    }
                }

                // ---- 4. 更新判定与音符命中状态 ----
                const triggerJudgement = createJudgementTrigger({
                    isUpsideDown, scorePosFromSkin, scale48, startX, totalTrackWidth, keys
                });
                // 若在纯皮肤预览模式（未加载谱面播放）且启用了判定演示，执行动态仿真步进
                if (isPreviewMode && isPreviewJudgementActive) {
                    const now = performance.now();
                    if (now - lastPreviewTickTime >= 420) {
                        lastPreviewTickTime = now;
                        if (previewBreakResumeTime > 0 && now >= previewBreakResumeTime) {
                            // 动画播放完之后还按原来的连击数继续播放
                            previewSimCombo = (previewSavedCombo > 0) ? previewSavedCombo : 100;
                            previewBreakResumeTime = 0;
                        }

                        const nextLookup = JUDGEMENT_PREVIEW_PATTERN[judgementPreviewIndex % JUDGEMENT_PREVIEW_PATTERN.length];
                        judgementPreviewIndex++;

                        // 随机触发一列打击特效
                        const randCol = Math.floor(Math.random() * keys);
                        // hitTime 用特效动画时钟：暂停时不再流逝，特效保持可见、便于点选
                        activeExplosions.push({ column: randCol, hitTime: effectAnimClockMs, duration: 200 });

                        if (nextLookup === LML.Hit0) {
                            // Miss 判定：触发断连并播放断连动画
                            triggerJudgement(now, LML.Hit0);
                            previewSavedCombo = previewSimCombo;
                            comboAnimState.breakStartTime = now;
                            comboAnimState.breakCount = (previewSimCombo > 0) ? previewSimCombo : 100;
                            comboAnimState.lastCombo = 0;
                            previewBreakResumeTime = now + 380;
                            previewSimCombo = 0;
                            currentCombo = 0;
                        } else {
                            if (previewBreakResumeTime === 0) {
                                previewSimCombo++;
                                comboAnimState.incStartTime = now;
                            }
                            triggerJudgement(now, nextLookup);
                            currentCombo = previewSimCombo;
                        }
                    }
                }

                if (!isPreviewMode) {
                    if (typeof scheduleManiaHitsounds === 'function') {
                        scheduleManiaHitsounds(currentTime);
                    }
                    const now = performance.now();
                    for (let i = 0; i < notesList.length; i++) {
                        let note = notesList[i];
                        if (!note.hit && currentTime >= note.startTime) {
                            note.hit = true;
                            // 隐藏期间错过的 note 仍保持已处理状态，但不补播瞬时反馈。
                            if (!isPlaybackEventFresh(note.startTime, currentTime)) continue;
                            // 单键音符触碰判定线时显示判定；长条音符按下时仅触发打击特效，松开(endTime)时才触发判定提示
                            if (!note.isHold) {
                                if (isPreviewJudgementActive) {
                                    const nextLookup = JUDGEMENT_PREVIEW_PATTERN[judgementPreviewIndex % JUDGEMENT_PREVIEW_PATTERN.length];
                                    judgementPreviewIndex++;
                                    triggerJudgement(now, nextLookup);
                                    if (nextLookup === LML.Hit0) {
                                        // Miss 判定：触发断连爆破动画
                                        if (currentCombo > 0) {
                                            playbackSavedCombo = currentCombo;
                                        }
                                        comboAnimState.breakStartTime = now;
                                        comboAnimState.breakCount = (currentCombo > 0) ? currentCombo : ((playbackSavedCombo > 0) ? playbackSavedCombo : 100);
                                        comboAnimState.lastCombo = 0;
                                        playbackBreakResumeTime = now + 380;
                                        currentCombo = 0;
                                    }
                                } else {
                                    triggerJudgement(now, LML.Hit300g);
                                }
                            }
                            activeExplosions.push({ column: note.column, hitTime: effectAnimClockMs, duration: 200 });
                        }
                    }
                }

                // ---- 5. 录制长条身体与长条尾巴的绘制批次（与 Note 共用层级） ----
                const activeNoteElements = [];
                const renderHoldNotes = () => {
                    for (let i = 0; i < notesList.length; i++) {
                        let note = notesList[i];
                        if (!note.isHold) continue;
                        if (currentTime >= note.endTime) {
                            if (!note.tailHit) {
                                note.tailHit = true;
                                if (!isPlaybackEventFresh(note.endTime, currentTime)) continue;
                                const now = performance.now();
                                activeExplosions.push({ column: note.column, hitTime: effectAnimClockMs, duration: 200 });
                                if (!isPreviewMode) {
                                    if (isPreviewJudgementActive) {
                                        const nextLookup = JUDGEMENT_PREVIEW_PATTERN[judgementPreviewIndex % JUDGEMENT_PREVIEW_PATTERN.length];
                                        judgementPreviewIndex++;
                                        triggerJudgement(now, nextLookup);
                                        if (nextLookup === LML.Hit0) {
                                            if (currentCombo > 0) {
                                                playbackSavedCombo = currentCombo;
                                            }
                                            comboAnimState.breakStartTime = now;
                                            comboAnimState.breakCount = (currentCombo > 0) ? currentCombo : ((playbackSavedCombo > 0) ? playbackSavedCombo : 100);
                                            comboAnimState.lastCombo = 0;
                                            playbackBreakResumeTime = now + 380;
                                            currentCombo = 0;
                                        }
                                    } else {
                                        triggerJudgement(now, LML.Hit300g);
                                    }
                                }
                            }
                            continue;
                        }

                        let w = colWidths[note.column];
                        let colX = colXCache[note.column];

                        const holdHeadImg = resolveAnimatedNoteImage(LML.HoldNoteHeadImage, note.column, note.startTime);
                        const holdTailImg = resolveAnimatedNoteImage(LML.HoldNoteTailImage, note.column, note.endTime);
                        const holdBodyImg = resolveAnimatedNoteImage(LML.HoldNoteBodyImage, note.column);

                        const headDrawHeight = holdHeadImg ? getManiaNoteDrawHeight(keys, note.column, holdHeadImg, w, scale48) : Math.round(20 * scale48);
                        const tailDrawHeight = holdTailImg ? getManiaNoteDrawHeight(keys, note.column, holdTailImg, w, scale48) : Math.round(20 * scale48);

                        const holdGeometry = getStableHoldNoteGeometry(
                            note, currentScrollPosition, currentTime, hitPos, speedFactor,
                            headDrawHeight, tailDrawHeight
                        );
                        note.holdHeadFrozen = holdGeometry.headFrozen;

                        const {
                            headAnchorY,
                            headTopY,
                            headCenterY,
                            tailAnchorY: tailBottomY,
                            tailTopY,
                            bodyTopY: bodyTop,
                            bodyBottomY: bodyBottom,
                            bodyHeight
                        } = holdGeometry;

                        const wholeTop = Math.min(headTopY, tailTopY, bodyTop);
                        const wholeBottom = Math.max(headAnchorY, tailBottomY, bodyBottom);
                        if (wholeBottom < -100 || wholeTop > canvas.height + 100) continue;

                        // 5a. 身体 (近端位于头部中心，长度只由头尾下端锚点决定)
                        if (bodyHeight > 0.5) {
                            if (canvasEditMode && bodyHeight > 4 && bodyTop < canvas.height && bodyBottom > 0 && bodyTop <= hitPos + 25) {
                                activeNoteElements.push({
                                    id: `hold_body_${note.column}`,
                                    noteInstanceKey: `hold_body_${note.column}_${note.startTime}`,
                                    name: `第 ${note.column + 1} 轨长条身`,
                                    paramKey: `NoteImage${note.column}L`,
                                    fallbackParamKey: 'HoldNoteBodyImage',
                                    category: 'Mania',
                                    x: colX,
                                    y: rectTop(bodyTop, bodyHeight),
                                    w: w,
                                    h: bodyHeight,
                                    isTexture: true,
                                    textureName: getManiaNoteTextureName(keys, LML.HoldNoteBodyImage, note.column),
                                    textureKey: LML.HoldNoteBodyImage,
                                    colIndex: note.column,
                                    dragAxis: null,
                                    valFormatter: () => `第 ${note.column + 1} 轨长条身`
                                });
                            }

                            if (holdBodyImg) {
                                const nbsRes = getManiaSkinConfig(keys, LML.NoteBodyStyle, note.column);
                                const style = (nbsRes && nbsRes.value != null) ? nbsRes.value : NOTE_BODY_STYLE.RepeatFromTail;
                                drawStableHoldBodyTexture(ctx, holdBodyImg, style, colX, w, bodyTop, bodyHeight);
                            } else {
                                const inset = 5;
                                const bx = colX + inset;
                                const bw = w - inset * 2;
                                const grad = ctx.createLinearGradient(bx, bodyTop, bx, bodyBottom);
                                const baseColor = note.column % 2 === 0 ? '0, 229, 255' : '255, 255, 255';
                                grad.addColorStop(0, `rgba(${baseColor}, 0.55)`);
                                grad.addColorStop(1, `rgba(${baseColor}, 0.75)`);
                                ctx.fillStyle = grad;
                                roundRect(ctx, bx, bodyTop, bw, bodyHeight, 4);
                                ctx.fill();

                                ctx.save();
                                ctx.globalAlpha = 0.35;
                                ctx.fillStyle = `rgba(255,255,255,0.85)`;
                                ctx.fillRect(bx + bw * 0.35, bodyTop + 2, bw * 0.3, bodyHeight);
                                ctx.restore();
                            }
                        }

                        // 5b. 尾巴 (到达头部中点即停止渲染)
                        if (tailBottomY > -tailDrawHeight * 2 && tailTopY < canvas.height + tailDrawHeight * 2) {
                            if (canvasEditMode && tailBottomY <= hitPos + 25) {
                                activeNoteElements.push({
                                    id: `hold_tail_${note.column}`,
                                    noteInstanceKey: `hold_tail_${note.column}_${note.startTime}`,
                                    name: `第 ${note.column + 1} 轨长条尾`,
                                    paramKey: `NoteImage${note.column}T`,
                                    fallbackParamKey: 'HoldNoteTailImage',
                                    category: 'Mania',
                                    x: colX,
                                    y: rectTop(tailTopY, tailDrawHeight),
                                    w: w,
                                    h: tailDrawHeight,
                                    isTexture: true,
                                    textureName: getManiaNoteTextureName(keys, LML.HoldNoteTailImage, note.column),
                                    textureKey: LML.HoldNoteTailImage,
                                    colIndex: note.column,
                                    dragAxis: null,
                                    valFormatter: () => `第 ${note.column + 1} 轨长条尾`
                                });
                            }

                            ctx.save();
                            ctx.beginPath();
                            ctx.rect(0, 0, canvas.width, Math.max(0, headCenterY));
                            ctx.clip();

                            if (holdTailImg) {
                                ctx.save();
                                ctx.translate(colX, tailBottomY);
                                ctx.scale(1, -1);
                                ctx.drawImage(holdTailImg, 0, 0, w, tailDrawHeight);
                                ctx.restore();
                            } else {
                                ctx.fillStyle = note.column % 2 === 0 ? '#00b8d4' : '#cccccc';
                                const rh = tailDrawHeight;
                                roundRect(ctx, colX + 4, tailTopY, w - 8, rh, 4);
                                ctx.fill();
                            }
                            ctx.restore();
                        }
                    }
                };

                // ---- 6 & 7. 渲染按键 KeyImage 与 Note ----
                // 依据 skin.ini 中的 KeysUnderNotes 参数决定图层层叠顺序：
                // 如果为 1：note 渲染在 keyimage 上 (先 keyimage，后 note)
                // 如果为 0 (或未配置默认 0)：note 渲染在 keyimage 下 (先 note，后 keyimage)
                const kunRes = getManiaSkinConfig(keys, LML.KeysUnderNotes);
                const keysUnderNotes = (kunRes && (kunRes.value === 1 || kunRes.value === '1' || kunRes.value === true)) ? 1 : 0;

                const renderKeyImages = createKeyImageRenderer({
                    keys, colWidths, colXCache, columnPressed, hitPos, canvas
                });
                const renderNotes = createNoteRenderer({
                    notesList, colWidths, colXCache, hitPos, currentScrollPosition,
                    speedFactor, canvas, canvasEditMode, activeNoteElements, currentTime,
                    resolveAnimatedNoteImage, keys, scale48, rectTop
                });
                // 根据 keysUnderNotes 决定渲染层级：
                // 1: Note 渲染在 KeyImage 上
                // 0 (默认): Note 渲染在 KeyImage 下
                if (keysUnderNotes === 1) {
                    renderKeyImages();
                    renderHoldNotes();
                    renderNotes();
                } else {
                    renderHoldNotes();
                    renderNotes();
                    renderKeyImages();
                }

                // ---- 8. 渲染舞台底图 StageBottom（最上层覆盖渲染，置于音符与按键之上） ----
                const stageBottomImg = getManiaSkinImage(keys, LML.BottomStageImage);
                if (stageBottomImg && stageBottomImg.width > 0 && stageBottomImg.height > 0) {
                    // 保持贴图原生纵横比，通过分辨率系数 scale48 进行等比缩放，水平居中对齐轨道，底部对齐画布底部
                    const is2x = !!stageBottomImg._is2x;
                    const nativeW = is2x ? stageBottomImg.width / 2 : stageBottomImg.width;
                    const nativeH = is2x ? stageBottomImg.height / 2 : stageBottomImg.height;
                    const sbW = nativeW * scale48;
                    const sbH = nativeH * scale48;
                    const sbY = canvas.height - sbH;

                    const hasColumnSpacing = colSpacings.slice(0, keys - 1).some(s => s > 0);
                    for (const segment of stageSegments) {
                        const segmentStartCol = colXCache.findIndex(colX => Math.abs(colX - segment.x) < 0.001);
                        const sbX = segment.x + (segment.width - sbW) / 2;
                        if (hasColumnSpacing || stageSegments.length > 1) {
                            for (let i = Math.max(0, segmentStartCol); i < keys; i++) {
                                const colX = colXCache[i];
                                const w = colWidths[i] || colWidths[0];
                                if (colX >= segment.x + segment.width - 0.001) break;
                                ctx.save();
                                ctx.beginPath();
                                ctx.rect(colX, sbY, w, sbH);
                                ctx.clip();
                                ctx.drawImage(stageBottomImg, sbX, sbY, sbW, sbH);
                                ctx.restore();
                            }
                        } else {
                            ctx.drawImage(stageBottomImg, sbX, sbY, sbW, sbH);
                        }
                    }
                }

                // ---- 8.5 渲染打击特效 LightingN (单键命中爆发) 与 LightingL (长条按住持续光效) ----
                const fpsRes = getManiaSkinConfig(keys, LML.LightFramePerSecond);
                const lightFps = (fpsRes && fpsRes.value > 0) ? fpsRes.value : 60;
                // 对齐 osu!lazer 核心逻辑 (LegacyHitExplosion / LegacySkin):
                // 1. 特效垂直中心对齐判定线 (HitPosition)，水平中心对齐当前轨道中心
                // 2. 基础尺寸基于贴图原生尺寸 (nativeW, nativeH)，随窗口 768p 分辨率等比缩放 (* scale768)
                // 3. 特效缩放倍率由 LightingNWidth / LightingLWidth 换算（数值 / 30），未配置时自动按 ColumnWidth / 30 缩放
                const lightPosY = hitPos;

                // 本帧「真实渲染出来」的打击特效矩形（画布坐标）。
                // 画布交互层据此判断某一轨的打击特效此刻是否可见：只有可见（正在爆发 / 正在按住长条）
                // 时，该轨元素才可被点选——与音符等元素一致，不再依赖常驻占位框。
                const activeLightingBoxes = renderLightingEffects({
                    ctx, isPreviewMode, notesList, currentTime, keys, colXCache, colWidths,
                    scale768, scale48, canvasEditMode, selectedCanvasElement,
                    activeExplosions, effectAnimClockMs, lightPosY, lightFps, rectTop
                });
                // ---- Mania 演奏区绘制结束：退出 UpsideDown 镜像，HUD (连击/判定/血条/右上角) 恢复常规坐标系 ----
                closeUpsideDownMirror();

                syncComboburstPlayback(currentCombo, keys);
                comboburstAnimationActive = drawComboburstEffects({
                    ctx, canvas, stageSegments, scale768
                });

                // 连击数状态更新与动画触发（对齐 osu!lazer: 增长纵向拉伸弹跳 + 断连红色爆破扩散）
                if (currentCombo > comboAnimState.lastCombo) {
                    comboAnimState.incStartTime = performance.now();
                } else if (currentCombo < comboAnimState.lastCombo && comboAnimState.lastCombo > 0) {
                    comboAnimState.breakStartTime = performance.now();
                    comboAnimState.breakCount = comboAnimState.lastCombo;
                }
                comboAnimState.lastCombo = currentCombo;

                const cpRes = getManiaSkinConfig(keys, LML.ComboPosition);
                let comboPosY;
                if (cpRes && cpRes.value != null && !isNaN(cpRes.value)) {
                    comboPosY = (isUpsideDown ? (480 - cpRes.value) : cpRes.value) * scale48;
                } else {
                    comboPosY = (isUpsideDown ? (480 - DEFAULT_COMBO_POSITION) : DEFAULT_COMBO_POSITION) * scale48;
                }
                let comboPosX = startX + totalTrackWidth / 2;
                drawCombo(currentCombo, comboPosX, comboPosY, keys, scale768, isHoldingLN, startX, totalTrackWidth);

                const defaultScorePosRaw = isUpsideDown ? (480 - DEFAULT_SCORE_POSITION) : DEFAULT_SCORE_POSITION;
                let scorePosY = (scorePosFromSkin !== null)
                    ? scorePosFromSkin
                    : defaultScorePosRaw * scale48;
                let scorePosX = startX + totalTrackWidth / 2;

                // 血条先绘制，保证与判定提示重叠时位于其下层。
                // 对齐 osu!lazer / stable 规范：位于轨道右侧，逆时针旋转 90 度，底部对齐，满血常驻展示。
                drawHealthDisplay(startX, totalTrackWidth, trailingSpacing, scale768);

                // 判定提示后绘制，与血条重叠时优先显示在上层。
                if (isPlaying || (isPreviewJudgementActive && judgements.length > 0)) {
                    drawJudgements(scale768, scorePosX, scorePosY);
                } else {
                    if (judgements.length > 0) {
                        // 暂停定格展示：同样传入当前帧的轨道区中心与 ScorePosition，
                        // 保证拖动轨道 / 修改判定位置时判定提示立即自动居中。
                        drawJudgements(scale768, scorePosX, scorePosY);
                    } else {
                        drawStaticJudgementPreview(keys, scorePosX, scorePosY, scale768);
                    }
                }

                // 渲染右上角分数、准度与歌曲进度饼图（对齐 osu!lazer LegacySkin 规范）
                const hudInteractiveElements = drawTopRightHUD(keys, scale768);


                // 更新可交互画布元素外接矩形与选中框渲染 (支持画布直接框选、拖拽与贴图替换)
                updateCanvasInteractiveElements({
                    keys, startX, totalTrackWidth, trailingSpacing,
                    colWidths, colSpacings, colXCache, hitPos, scorePosFromSkin,
                    comboPosX, comboPosY, scale48, scale768, stageLightLpRes, hpRes,
                    activeNoteElements, hudInteractiveElements, isUpsideDown,
                    activeLightingBoxes, activeStageLightBoxes
                });

                if (debugMode) {
                    drawDebugWindow({
                        keys, scale48, colWidths, colSpacings, startX, totalTrackWidth,
                        hitPos, scorePosFromSkin, comboPosY, noteBodyStyleCfg, showLine,
                        columnStartRaw, columnPressed, colXCache, keysUnderNotes,
                    });
                }

            } catch (err) {
                console.error("[drawFrame] 渲染异常（已捕获并跳过）：", err);
                try {
                    for (let i = 0; i < 64; i++) {
                        let threw = false;
                        try { ctx.restore(); } catch (_) { threw = true; }
                        if (threw) break;
                    }
                    ctx.save();
                    ctx.fillStyle = 'rgba(224, 84, 139, 0.85)';
                    ctx.font = 'bold 14px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('Render Error: ' + (err.message || err), canvas.width / 2, 30);
                    ctx.restore();
                } catch (_) { }
            } finally {
                // 注意：暂停时特效时钟冻结，爆炸不会变化 —— 此时不应再靠它维持 rAF 循环，
                // 否则会空转（预览模式没有音频，仍需靠它驱动，故用 isPlaying || isPreviewMode 门控）。
                const hasRunningAnims = ((isPlaying || isPreviewMode) && activeExplosions.length > 0) || (isPlaying && judgements.length > 0) ||
                    (isPreviewMode && skinFrameAnimationActive) ||
                    (performance.now() - comboAnimState.breakStartTime < 400) ||
                    (performance.now() - comboAnimState.incStartTime < 300) ||
                    isComboHoldColourTransitionActive() ||
                    (performance.now() < testComboBreakUntil) ||
                    (performance.now() - bgFadeStartTime < BG_FADE_DURATION) ||
                    (performance.now() < testHoldingUntil) ||
                    comboburstAnimationActive ||
                    (isPreviewMode && isPreviewJudgementActive) ||
                    (selectedCanvasElement && (performance.now() - selectionAnimStartTime < 240));
                if ((isPlaying || hasRunningAnims) && (currentBeatmap || isPreviewMode)) {
                    cancelAnimationFrame(animationId);
                    animationId = requestAnimationFrame(drawFrame);
                }
            }
        }
// --- END render/frame.js ---

// --- BEGIN render/judgements.js ---
// ============================================================================
// judgements.js - 判定提示静态预览与动画绘制
// 依赖：render/textures.js
// ============================================================================

        // 绘制静止/预览状态下的判定结果提示（Hit300g/300g），确保在未播放、暂停或未触发音符时画布始终能清晰看到判定位置
        function drawStaticJudgementPreview(keys, scorePosX, scorePosY, scale768) {
            let hitFrames = getManiaSkinAnimationFrames(keys, LML.Hit300g)
                || getManiaSkinAnimationFrames(keys, LML.Hit300)
                || null;
            let hitImg = (hitFrames && hitFrames.length > 0)
                ? hitFrames[0]
                : (getManiaSkinImage(keys, LML.Hit300g) || getManiaSkinImage(keys, LML.Hit300) || null);

            if (hitImg && hitImg.width > 0 && hitImg.height > 0) {
                const is2x = hitImg._is2x || false;
                const nativeW = is2x ? hitImg.width / 2 : hitImg.width;
                const nativeH = is2x ? hitImg.height / 2 : hitImg.height;
                const scale = scale768 * 0.70;
                let jWidth = nativeW * scale;
                let jHeight = nativeH * scale;
                ctx.save();
                ctx.globalAlpha = 0.95;
                ctx.drawImage(hitImg, scorePosX - jWidth / 2, scorePosY - jHeight / 2, jWidth, jHeight);
                ctx.restore();
            } else {
                ctx.save();
                ctx.globalAlpha = 0.95;
                ctx.font = `bold ${Math.round(25 * scale768)}px sans-serif`;
                ctx.fillStyle = '#66ccff';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.shadowColor = 'rgba(0, 0, 0, 0.6)';
                ctx.shadowBlur = 4;
                ctx.fillText('300g', scorePosX, scorePosY);
                ctx.restore();
            }
        }

        // 计算当前判定动画在指定时刻的实时缩放大小（用于动画平滑重叠衔接）
        function getJudgementCurrentScale(j, nowOrElapsed) {
            if (!j) return 0.80;
            const elapsed = (typeof nowOrElapsed === 'number' && nowOrElapsed <= 1000)
                ? nowOrElapsed
                : (j.hitTime !== undefined ? ((nowOrElapsed || performance.now()) - j.hitTime) : (j.elapsed || 0));
            if (elapsed < 0 || elapsed > 220) return 0.80;

            if (j.isMiss) {
                if (elapsed < 100) {
                    const t = elapsed / 100;
                    const easeOut = 1 - Math.pow(1 - t, 2);
                    return 1.2 - 0.2 * easeOut;
                }
                return 1.0;
            }

            const baseStart = (j.startScale != null) ? j.startScale : 0.80;
            if (elapsed < 40) {
                // 快速放大阶段: 从 baseStart 放大至 1.0
                return baseStart + (1.0 - baseStart) * (elapsed / 40);
            } else if (elapsed < 80) {
                // 慢慢缩小阶段 1: 0.85 -> 0.70
                return 0.85 - 0.15 * ((elapsed - 40) / 40);
            } else if (elapsed <= 180) {
                // 稳定展示阶段: 0.70
                return 0.70;
            } else {
                // 慢慢缩小阶段 2: 0.70 -> 0.40
                const t = (elapsed - 180) / 40;
                return Math.max(0.40, 0.70 - 0.30 * (t * t));
            }
        }

        // 计算当前判定动画在指定时刻的实时透明度（避免重叠连击时透明度突变为 0 产生闪烁）
        function getJudgementCurrentAlpha(j, nowOrElapsed) {
            if (!j) return 0.0;
            const elapsed = (typeof nowOrElapsed === 'number' && nowOrElapsed <= 1000)
                ? nowOrElapsed
                : (j.hitTime !== undefined ? ((nowOrElapsed || performance.now()) - j.hitTime) : (j.elapsed || 0));
            if (elapsed < 0 || elapsed > 220) return 0.0;

            const baseAlpha = (j.startAlpha != null) ? j.startAlpha : 0.0;
            if (elapsed < 20) {
                const t = elapsed / 20;
                const easeOut = 1 - Math.pow(1 - t, 2);
                return baseAlpha + (1.0 - baseAlpha) * easeOut;
            } else if (elapsed <= 180) {
                return 1.0;
            } else {
                const t = (elapsed - 180) / 40;
                return Math.max(0.0, 1.0 - (t * t));
            }
        }

        // osu!lazer 官方打击判定效果引擎
        // 1. 皮肤贴图判定: 对齐 LegacyManiaJudgementPiece (原版尺寸 * scale768，220ms 寿命)
        //    - 透明度: 0~20ms FadeInFromZero(20, Easing.Out) -> 160ms 保持 -> 180~220ms FadeOutFromOne(40, Easing.In)
        //    - 命中缩放: 0~40ms 快速放大 (startScale->1.0) -> 40~80ms (0.85->0.70) -> 80~180ms 保持 0.70 -> 180~220ms (0.70->0.40, Easing.In)
        //    - Miss 缩放与旋转: 0~100ms ScaleTo(1.2->1.0, Easing.Out)，同时角度从 0 缓动旋转到 targetRotation [-5.73°, +5.73°]
        //    - 连击衔接: 慢缩小阶段遇新音符触发时，从当前缩小尺寸无缝顶回 1.0，继续播放缩小过程
        //    - 多帧序列帧动画: 对齐 IFramedAnimation.GotoFrame(0) + 20 FPS (50ms/帧)
        // 2. 默认矢量文字判定: 对齐 DefaultManiaJudgementPiece
        function drawJudgements(scale768, anchorX, anchorY) {
            const now = performance.now();
            // 判定提示需要跟随轨道布局实时居中：
            // 触发瞬间缓存的 j.x / j.y 只在「轨道区中心」这一刻成立，
            // 暂停状态下拖动轨道（改列宽/间距/ColumnStart）时布局会变，
            // 若继续沿用缓存坐标，判定贴图就会停留在旧位置、不跟随轨道区居中。
            // 因此这里优先采用调用方传入的当前帧坐标（轨道区中心 + ScorePosition 实时值）。
            const liveX = (typeof anchorX === 'number' && isFinite(anchorX)) ? anchorX : null;
            const liveY = (typeof anchorY === 'number' && isFinite(anchorY)) ? anchorY : null;
            for (let i = judgements.length - 1; i >= 0; i--) {
                const j = judgements[i];
                const jx = (liveX !== null) ? liveX : j.x;
                const jy = (liveY !== null) ? liveY : j.y;
                const elapsed = isPlaying
                    ? (now - j.hitTime)
                    : ((j.elapsed !== undefined) ? j.elapsed : (now - j.hitTime));
                j.elapsed = elapsed;
                if (elapsed < 0) continue;

                // 判断是否包含皮肤贴图或帧动画
                const hasSkinPiece = (j.frames && j.frames.length > 0) || (j.img && j.img.width > 0 && j.img.height > 0);
                const maxLifetime = hasSkinPiece ? 220 : (j.isMiss ? 800 : 550);

                // 播放中或静态预览判定演示中超时则移除；若谱面暂停则定格保持显示，方便用户直接观察或点击选中
                if ((isPlaying || (!currentBeatmap && isPreviewJudgementActive)) && elapsed > maxLifetime) {
                    judgements.splice(i, 1);
                    continue;
                }

                if (hasSkinPiece) {
                    // ---- 1. 对齐 LegacyManiaJudgementPiece ----
                    // 1.1 透明度 (FadeInFromZero(20, Out) -> Delay(160) -> FadeOutFromOne(40, In))
                    let alpha = 1.0;
                    const startAlpha = (j.startAlpha != null) ? j.startAlpha : 0.0;
                    if (elapsed < 20) {
                        const t = elapsed / 20;
                        const easeOut = 1 - Math.pow(1 - t, 2); // Easing.Out (Quad)
                        alpha = startAlpha + (1.0 - startAlpha) * easeOut;
                    } else if (elapsed > 180) {
                        const t = (elapsed - 180) / 40;
                        alpha = Math.max(0, 1 - (t * t)); // Easing.In (Quad)
                    }

                    // 1.2 缩放与旋转曲线
                    let currentScale = 1.0;
                    let currentRotation = 0;
                    if (j.isMiss) {
                        // Miss: ScaleTo(1.2->1.0, 100, Easing.Out), RotateTo(0->targetRotation, 100, Easing.Out)
                        if (elapsed < 100) {
                            const t = elapsed / 100;
                            const easeOut = 1 - Math.pow(1 - t, 2);
                            currentScale = 1.2 - 0.2 * easeOut;
                            currentRotation = (j.targetRotation || 0) * easeOut;
                        } else {
                            currentScale = 1.0;
                            currentRotation = j.targetRotation || 0;
                        }
                    } else {
                        // Hit:
                        // 快速放大阶段 (0~40ms): 从当前 startScale 平滑顶回到 1.0
                        // 慢慢缩小阶段 (40ms~220ms): 40~80ms (0.85->0.70) -> 80~180ms 稳定保持 (0.70) -> 180~220ms (0.70->0.40)
                        const startScale = (j.startScale != null) ? j.startScale : 0.80;
                        if (elapsed < 40) {
                            currentScale = startScale + (1.0 - startScale) * (elapsed / 40);
                        } else if (elapsed < 80) {
                            currentScale = 0.85 - 0.15 * ((elapsed - 40) / 40);
                        } else if (elapsed <= 180) {
                            currentScale = 0.70;
                        } else {
                            const t = (elapsed - 180) / 40;
                            currentScale = 0.70 - 0.30 * (t * t); // Easing.In (Quad)
                        }
                        currentRotation = 0;
                    }

                    // 1.3 序列帧解析 (20 FPS / 50ms 步进，从第 0 帧开始)
                    let currentImg = j.img;
                    if (j.frames && j.frames.length > 0) {
                        const frameIndex = Math.min(j.frames.length - 1, Math.floor(elapsed / 50));
                        currentImg = j.frames[frameIndex] || j.img;
                    }

                    if (currentImg && currentImg.width > 0 && currentImg.height > 0) {
                        const is2x = currentImg._is2x || false;
                        const nativeW = is2x ? currentImg.width / 2 : currentImg.width;
                        const nativeH = is2x ? currentImg.height / 2 : currentImg.height;
                        const jWidth = nativeW * scale768 * currentScale;
                        const jHeight = nativeH * scale768 * currentScale;

                        ctx.save();
                        ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
                        ctx.translate(jx, jy);
                        if (currentRotation !== 0) {
                            ctx.rotate(currentRotation);
                        }
                        ctx.drawImage(currentImg, -jWidth / 2, -jHeight / 2, jWidth, jHeight);
                        ctx.restore();
                    }
                } else {
                    // ---- 2. 对齐 DefaultManiaJudgementPiece (无贴图默认矢量字) ----
                    ctx.save();
                    if (j.isMiss) {
                        // Miss: ScaleTo(1.6->1.0, 100, In), MoveToOffset(100, 800, InQuint), RotateTo(40, 800, InQuint), FadeOut(800)
                        const tTotal = Math.min(1, elapsed / 800);
                        const inQuint = Math.pow(tTotal, 5);
                        const alpha = Math.max(0, 1 - tTotal);
                        const currentScale = elapsed < 100 ? (1.6 - 0.6 * Math.pow(elapsed / 100, 2)) : 1.0;
                        const offsetY = 100 * scale768 * inQuint;
                        const rotation = (40 * Math.PI / 180) * inQuint;

                        ctx.globalAlpha = alpha;
                        ctx.translate(jx, jy + offsetY);
                        ctx.rotate(rotation);
                        ctx.scale(currentScale, currentScale);
                        ctx.font = `bold ${Math.round(25 * scale768)}px sans-serif`;
                        ctx.fillStyle = '#ff4444';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText('MISS', 0, 0);
                    } else {
                        // Hit: ScaleTo(0.8->1.0, 250, OutElastic) -> Delay(50) -> ScaleTo(1.0->0.75, 250) + FadeOut(200, from 350ms)
                        let currentScale = 1.0;
                        if (elapsed < 250) {
                            const t = elapsed / 250;
                            const easeElastic = Math.pow(2, -10 * t) * Math.sin((t - 0.075) * (2 * Math.PI) / 0.3) + 1;
                            currentScale = 0.8 + 0.2 * easeElastic;
                        } else if (elapsed < 300) {
                            currentScale = 1.0;
                        } else {
                            currentScale = 1.0 - 0.25 * ((elapsed - 300) / 250);
                        }

                        let alpha = 1.0;
                        if (elapsed > 350) {
                            alpha = Math.max(0, 1 - ((elapsed - 350) / 200));
                        }

                        let label = '300g';
                        let fillStyle = '#66ccff';
                        if (j.lookup === LML.Hit300) { label = '300'; fillStyle = '#ffd700'; }
                        else if (j.lookup === LML.Hit200) { label = '200'; fillStyle = '#55ff55'; }
                        else if (j.lookup === LML.Hit100) { label = '100'; fillStyle = '#4488ff'; }
                        else if (j.lookup === LML.Hit50) { label = '50'; fillStyle = '#bbbbbb'; }

                        ctx.globalAlpha = alpha;
                        ctx.translate(jx, jy);
                        ctx.scale(currentScale, currentScale);
                        ctx.font = `bold ${Math.round(25 * scale768)}px sans-serif`;
                        ctx.fillStyle = fillStyle;
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(label, 0, 0);
                    }
                    ctx.restore();
                }
            }
        }
// --- END render/judgements.js ---

// --- BEGIN render/hud.js ---
// ============================================================================
// hud.js - 分数、准度、连击 HUD 与血条绘制
// 依赖：render/fonts.js、render/textures.js
// ============================================================================


        function drawTopRightHUD(keys, scale768) {
            const hudInteractiveElements = [];
            const maniaCfg = getManiaConfigForKeys(keys);
            const scoreFontPrefix = (maniaCfg && maniaCfg.FontScore) ? maniaCfg.FontScore : (skinFontsConfig.scorePrefix || 'score');

            // 1. 获取基准数字参考贴图（优先 '5'，回退 '0'，对齐 lazer FixedWidthReferenceCharacter）
            const refImg = getSkinFontImage('score', '5', keys) || getSkinFontImage('score', '0', keys);
            let refNativeW = 30;
            let refNativeH = 46;
            if (refImg && refImg.height > 0) {
                const is2x = refImg._is2x || false;
                refNativeW = is2x ? (refImg.width / 2) : refImg.width;
                refNativeH = is2x ? (refImg.height / 2) : refImg.height;
            }

            const rawOverlap = getSkinFontOverlap('score', keys);

            // ---- A. 分数 (Score: "01234567") ----
            const scoreText = "01234567";
            const scoreScale = 0.96 * scale768;
            const scoreSlotW = refNativeW * scoreScale;
            const scoreSlotH = refNativeH * scoreScale;
            const scoreOverlap = rawOverlap * scoreScale;
            const scoreAdvance = scoreSlotW - scoreOverlap;
            const scoreTotalW = (scoreText.length - 1) * scoreAdvance + scoreSlotW;

            const scoreMarginRight = 10 * scale768;
            const scoreMarginTop = 10 * scale768;
            const scoreRightX = canvas.width - scoreMarginRight;
            const scoreLeftX = scoreRightX - scoreTotalW;
            const scoreTopY = scoreMarginTop;

            ctx.save();
            for (let i = 0; i < scoreText.length; i++) {
                const ch = scoreText[i];
                const img = getSkinFontImage('score', ch, keys);
                const slotX = scoreLeftX + i * scoreAdvance;

                let charW = scoreSlotW;
                let charH = scoreSlotH;
                let drawX = slotX;

                if (img) {
                    const is2x = img._is2x || false;
                    const charNativeW = is2x ? (img.width / 2) : img.width;
                    const charNativeH = is2x ? (img.height / 2) : img.height;
                    charW = charNativeW * scoreScale;
                    charH = charNativeH * scoreScale;
                    // FixedWidth 模式下数字在槽内居中
                    drawX = slotX + (scoreSlotW - charW) / 2;
                    ctx.drawImage(img, drawX, scoreTopY, charW, charH);
                } else {
                    ctx.font = `bold ${Math.round(scoreSlotH * 0.8)}px sans-serif`;
                    ctx.fillStyle = '#ffffff';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'top';
                    ctx.fillText(ch, slotX + scoreSlotW / 2, scoreTopY);
                }

                hudInteractiveElements.push({
                    id: `hud_score_digit_${i}`,
                    name: `右上角分数数字 ${ch}`,
                    paramKey: 'ScorePrefix',
                    category: 'Fonts',
                    x: Math.min(drawX, slotX),
                    y: scoreTopY,
                    w: Math.max(charW, scoreSlotW),
                    h: Math.max(charH, scoreSlotH),
                    isTexture: true,
                    textureName: `${scoreFontPrefix}-${ch}`,
                    textureKey: `${scoreFontPrefix}-${ch}`,
                    dragAxis: null,
                    valFormatter: () => `${scoreFontPrefix}-${ch}`
                });
            }
            ctx.restore();

            // ---- B. 准度 (Accuracy: "98.00%") ----
            // 检查当前皮肤的百分号 (%)：
            // 1. 若皮肤提供 1x1 占位图，代表作者刻意隐藏百分号，准度展示为纯数字 "98.00"
            // 2. 若存在正常贴图或超宽平移垫片，则保留 "%" 字符并按垫片宽度向左推移准度
            const percentImg = getSkinFontImage('score', '%', keys);
            const isPercentHidden = !!(percentImg && percentImg._isBlankPlaceholder);
            const accText = isPercentHidden ? "98.00" : "98.00%";

            const accScale = 0.576 * scale768; // 0.6 * 0.96
            const accDigitSlotW = refNativeW * accScale;
            const accOverlap = rawOverlap * accScale;
            // 对齐游戏内规范：准度右侧与分数右侧严格右对齐
            const accRightX = scoreRightX;
            // 对齐游戏内垂直间隙（分数底部到准度/饼图顶部约 12px）
            const accMarginTop = 6.5 * scale768;
            const accTopY = scoreTopY + scoreSlotH + accMarginTop;
            const accH = refNativeH * accScale;

            // 预先度量准度文本各字符宽度（'.' 与 '%' 排除在 fixedWidth 之外，使用原生宽度）
            const accGlyphs = [];
            let accTotalW = 0;
            for (let i = 0; i < accText.length; i++) {
                const ch = accText[i];
                const img = (ch === '%' && percentImg) ? percentImg : getSkinFontImage('score', ch, keys);
                const isExcluded = (ch === '.' || ch === '%' || ch === ',');

                let nativeW = refNativeW;
                let nativeH = refNativeH;
                if (img) {
                    if (img._isBlankPlaceholder) {
                        nativeW = 0;
                        nativeH = 0;
                    } else {
                        const is2x = img._is2x || false;
                        nativeW = is2x ? (img.width / 2) : img.width;
                        nativeH = is2x ? (img.height / 2) : img.height;
                    }
                }

                const charW = nativeW * accScale;
                const charH = (ch === '%') ? Math.min(nativeH, refNativeH * 1.5) * accScale : nativeH * accScale;
                const slotW = isExcluded ? charW : accDigitSlotW;

                accGlyphs.push({ ch, img, charW, charH, slotW, isExcluded });
                accTotalW += (i < accText.length - 1) ? (slotW - accOverlap) : slotW;
            }

            const accLeftX = accRightX - accTotalW;

            ctx.save();
            let curAccX = accLeftX;
            let firstCharDrawX = accLeftX;
            for (let i = 0; i < accGlyphs.length; i++) {
                const glyph = accGlyphs[i];
                const drawX = glyph.isExcluded ? curAccX : curAccX + (glyph.slotW - glyph.charW) / 2;
                if (i === 0) firstCharDrawX = drawX;

                if (glyph.img && !glyph.img._isBlankPlaceholder) {
                    // 透明垫片本身不会产生可见像素；可见字形则正常绘制。这样既能保留
                    // 超宽透明 score-percent 的位移技巧，也允许在右侧恢复显示百分号。
                    ctx.drawImage(glyph.img, drawX, accTopY, glyph.charW, glyph.charH);
                } else if (!glyph.img && glyph.ch !== '%') {
                    ctx.font = `bold ${Math.round(accH * 0.8)}px sans-serif`;
                    ctx.fillStyle = '#ffffff';
                    ctx.textAlign = 'left';
                    ctx.textBaseline = 'top';
                    ctx.fillText(glyph.ch, curAccX, accTopY);
                }

                if (!glyph.img || !glyph.img._isBlankPlaceholder) {
                    const charNameMap = { '.': 'dot', '%': 'percent', ',': 'comma' };
                    const glyphKey = charNameMap[glyph.ch] || glyph.ch;
                    const glyphLabel = glyph.ch === '.' ? '小数点' : (glyph.ch === '%' ? '百分号' : `数字 ${glyph.ch}`);
                    const elemW = Math.max(glyph.charW, glyph.slotW, 10 * scale768);
                    const elemH = Math.max(glyph.charH, accH, 12 * scale768);

                    hudInteractiveElements.push({
                        id: `hud_acc_glyph_${i}`,
                        name: `右上角准度${glyphLabel}`,
                        paramKey: 'ScorePrefix',
                        category: 'Fonts',
                        x: Math.min(drawX, curAccX),
                        y: accTopY,
                        w: elemW,
                        h: elemH,
                        isTexture: true,
                        textureName: `${scoreFontPrefix}-${glyphKey}`,
                        textureKey: `${scoreFontPrefix}-${glyphKey}`,
                        dragAxis: null,
                        valFormatter: () => `${scoreFontPrefix}-${glyphKey}`
                    });
                }

                curAccX += (glyph.slotW - accOverlap);
            }
            ctx.restore();

            // ---- C. 歌曲进度饼图 (Song Progress Pie: 纯代码几何图形对齐 lazer / stable 规范) ----
            let songProgressVal = 0.12; // 默认空闲预览对齐游戏内开局轻量进度（约 12%）
            if (audio && !isNaN(audio.duration) && audio.duration > 0 && !audio.paused) {
                const playbackTime = getPlaybackTimeSeconds();
                songProgressVal = Math.max(0, Math.min(1, playbackTime / audio.duration));
            } else if (ui.progressRange && !isNaN(ui.progressRange.max) && Number(ui.progressRange.max) > 0 && Number(ui.progressRange.value) > 0) {
                songProgressVal = Math.max(0, Math.min(1, Number(ui.progressRange.value) / Number(ui.progressRange.max)));
            }

            const pieDiameter = 33 * scale768;
            const pieRadius = pieDiameter / 2;
            // 间距计算对齐游戏真实测量：饼图右边缘距准度首个字符实际绘制左边缘为 13.5 * scale768（在 1080p 下精确对应 19px）
            const pieGap = 13.5 * scale768;
            const pieCenterX = firstCharDrawX - pieGap - pieRadius;
            const pieCenterY = accTopY + accH / 2;

            ctx.save();
            // 1. 内部动态半透明白色扇形 (0.92 尺寸比例，从 12 点钟 -PI/2 顺时针扫射，alpha: 0.6)
            if (songProgressVal > 0) {
                const innerRadius = (33 * 0.92 * scale768) / 2;
                ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
                ctx.beginPath();
                ctx.moveTo(pieCenterX, pieCenterY);
                ctx.arc(pieCenterX, pieCenterY, innerRadius, -Math.PI / 2, -Math.PI / 2 + songProgressVal * Math.PI * 2, false);
                ctx.closePath();
                ctx.fill();
            }

            // 2. 外部白色圆环边框 (直径 33px，线宽 2px，带抗锯齿辉光)
            ctx.save();
            ctx.shadowColor = 'rgba(255, 255, 255, 0.4)';
            ctx.shadowBlur = 3 * scale768;
            const borderWidth = 2 * scale768;
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = borderWidth;
            ctx.beginPath();
            ctx.arc(pieCenterX, pieCenterY, (pieDiameter - borderWidth) / 2, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();

            // 3. 中心小白圆点 (直径 4px，半径 2px)
            const dotRadius = 2 * scale768;
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(pieCenterX, pieCenterY, dotRadius, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();

            hudInteractiveElements.push({
                id: 'hud_progress_pie',
                name: '调整acc水平位置',
                paramKey: 'ScorePercentWidth',
                category: 'Mania',
                x: pieCenterX - pieRadius - 5,
                y: pieCenterY - pieRadius - 5,
                w: pieDiameter + 10,
                h: pieDiameter + 10,
                isTexture: false,
                dragAxis: 'x',
                dragType: 'score_percent_width',
                valFormatter: () => `${getScorePercentPaddingWidth(keys)}px`
            });

            return hudInteractiveElements;
        }

        // 6. 自动加载默认皮肤设定：若皮肤不包含有效血条贴图（缺失或仅为 1x1 占位图），在开启设定时自动回退并渲染默认皮肤血条
        // =========================================================================
        function drawHealthDisplay(startX, totalTrackWidth, trailingSpacing, scale768) {
            // 检查当前导入的皮肤中是否存在血条相关贴图
            // osu! 规范：只要皮肤包含了 scorebar-colour 或 scorebar-bg（无论是否有帧动画，也无论是否是 1x1 透明隐形占位图），
            // 均视为皮肤作者显式自定义了血条（1x1 常见于各类 mania 皮肤以彻底隐去血条），此时绝对禁止回退到默认皮肤！
            let userColourFrames = getSkinAnimationFramesFromStore(skinImageStore, 'scorebar-colour');
            let userColourImg = (userColourFrames && userColourFrames.length > 0) ? userColourFrames[0] : getSkinAnimationFromStore(skinImageStore, 'scorebar-colour');
            let userBgImg = getSkinAnimationFromStore(skinImageStore, 'scorebar-bg');
            let userMarkerImg = getSkinAnimationFromStore(skinImageStore, 'scorebar-marker');

            const hasCustomHealth = !!(userColourImg || (userColourFrames && userColourFrames.length > 0) || userBgImg);

            let bgImg = null;
            let colourImg = null;
            let markerImg = null;

            if (hasCustomHealth) {
                if (userColourFrames && userColourFrames.length > 0) {
                    const fps = 60;
                    const frameIdx = Math.floor((performance.now() / 1000 * fps) % userColourFrames.length);
                    colourImg = userColourFrames[frameIdx] || userColourFrames[0];
                } else {
                    colourImg = userColourImg;
                }
                bgImg = userBgImg;
                markerImg = userMarkerImg;
            } else {
                // 仅当用户皮肤完全没有提供任何血条贴图时，才回退到官方默认皮肤
                const defFrames = getSkinAnimationFramesFromStore(defaultSkinImageStore, 'scorebar-colour');
                if (defFrames && defFrames.length > 0) {
                    const fps = 60;
                    const frameIdx = Math.floor((performance.now() / 1000 * fps) % defFrames.length);
                    colourImg = defFrames[frameIdx] || defFrames[0];
                } else {
                    colourImg = getSkinAnimationFromStore(defaultSkinImageStore, 'scorebar-colour');
                }
                bgImg = getSkinAnimationFromStore(defaultSkinImageStore, 'scorebar-bg');
                markerImg = getSkinAnimationFromStore(defaultSkinImageStore, 'scorebar-marker');
            }

            if (!bgImg && !colourImg) return;

            const bgW = (bgImg && bgImg.width > 0) ? (bgImg._is2x ? bgImg.width / 2 : bgImg.width) : 0;
            const bgH = (bgImg && bgImg.height > 0) ? (bgImg._is2x ? bgImg.height / 2 : bgImg.height) : 0;
            const hasRealBg = (bgImg && bgW > 1 && bgH > 1);

            const isNewStyle = !!markerImg;

            // osu!lazer 槽位硬编码偏移规范（仅在存在实体背景时应用，无背景或 1x1 占位图时偏移归零）：
            // LegacyNewStyleFill: Vector2(7.5f, 7.8f) * 1.6f
            // LegacyOldStyleFill: Vector2(3.0f, 10.0f) * 1.6f
            const fillOffsetX = hasRealBg ? (isNewStyle ? 7.5 : 3.0) * 1.6 : 0;
            const fillOffsetY = hasRealBg ? (isNewStyle ? 7.8 : 10.0) * 1.6 : 0;

            const clrW = (colourImg && colourImg.width > 0) ? (colourImg._is2x ? colourImg.width / 2 : colourImg.width) : 0;
            const clrH = (colourImg && colourImg.height > 0) ? (colourImg._is2x ? colourImg.height / 2 : colourImg.height) : 0;

            // 对齐 mania HUD / Judgement 标准缩放倍率 scale768 * 0.70
            const healthScale = scale768 * 0.70;

            const healthBarX = startX + totalTrackWidth + (trailingSpacing || 0);
            const bottomY = canvas.height;

            ctx.save();
            ctx.translate(healthBarX, bottomY);
            ctx.rotate(-Math.PI / 2);
            ctx.scale(healthScale, healthScale);

            // 1. 渲染背景 scorebar-bg（仅存在实体背景槽时绘制）
            if (hasRealBg) {
                ctx.drawImage(bgImg, 0, 0, bgW, bgH);
            }

            // 2. 渲染颜色条 scorebar-colour（满血常驻展示；1x1 占位图则直接跳过渲染）
            if (colourImg && clrW > 1 && clrH > 1) {
                ctx.drawImage(colourImg, fillOffsetX, fillOffsetY, clrW, clrH);
            }

            ctx.restore();
        }
// --- END render/hud.js ---

// --- BEGIN render/diagnostics.js ---
// ============================================================================
// diagnostics.js - 调试面板、播放状态同步、选择高亮与画布尺寸同步
// 依赖：core/state.js、skin/mania-config.js
// ============================================================================

        function drawDebugWindow(d) {
            const cfg = getManiaConfigForKeys(d.keys);
            const lines = [];
            lines.push('===== skin.ini Debug (按 D 关闭) =====');
            lines.push(`Keys: ${d.keys}`);
            lines.push(`scale48: ${d.scale48.toFixed(4)}  (canvas ${canvas.width}x${canvas.height})`);
            lines.push('');
            lines.push('--- 坐标 / 位置 (raw → scaled) ---');
            lines.push(`ColumnStart: ${d.columnStartRaw} → ${d.startX.toFixed(1)}px`);
            lines.push(`HitPosition: ${(d.hitPos / d.scale48).toFixed(1)} → ${d.hitPos.toFixed(1)}px`);
            lines.push(`ScorePosition: ${d.scorePosFromSkin !== null ? (d.scorePosFromSkin / d.scale48).toFixed(1) + ' → ' + d.scorePosFromSkin.toFixed(1) + 'px' : '(默认)'}`);
            lines.push(`ComboPosition: ${(d.comboPosY / d.scale48).toFixed(1)} → ${d.comboPosY.toFixed(1)}px`);
            lines.push(`JudgementLine: ${d.showLine ? '1 (显示)' : '0 (隐藏)'}`);
            const noteBodyStyleLabel = d.noteBodyStyleCfg === NOTE_BODY_STYLE.Stretch ? 'Stretch'
                : (d.noteBodyStyleCfg === NOTE_BODY_STYLE.RepeatFromTail ? 'RepeatFromTail'
                    : (d.noteBodyStyleCfg === NOTE_BODY_STYLE.RepeatFromHead ? 'RepeatFromHead' : 'RepeatTopAndBottom'));
            lines.push(`NoteBodyStyle: ${d.noteBodyStyleCfg} (${noteBodyStyleLabel})`);
            lines.push('');
            lines.push('--- 列宽 (raw → scaled) ---');
            for (let i = 0; i < d.keys; i++) {
                const raw = (d.colWidths[i] / d.scale48).toFixed(1);
                lines.push(`  col[${i}]: width=${raw} → ${d.colWidths[i].toFixed(1)}px  x=${d.colXCache[i].toFixed(1)}`);
            }
            lines.push(`  totalTrackWidth: ${d.totalTrackWidth.toFixed(1)}px`);
            lines.push('');
            lines.push('--- 列间距 (raw → scaled) ---');
            for (let i = 0; i < d.keys - 1; i++) {
                const raw = (d.colSpacings[i] / d.scale48).toFixed(1);
                lines.push(`  gap[${i}↔${i + 1}]: ${raw} → ${d.colSpacings[i].toFixed(1)}px`);
            }
            lines.push('');
            lines.push('--- 按键状态 ---');
            let pressedStr = '';
            for (let i = 0; i < d.keys; i++) pressedStr += d.columnPressed[i] ? '■ ' : '□ ';
            lines.push(`  ${pressedStr}`);
            lines.push('');
            lines.push('--- 图片资源 ---');
            const lookups = [
                ['KeyImage', LML.KeyImage],
                ['KeyImageDown', LML.KeyImageDown],
                ['NoteImage', LML.NoteImage],
                ['NoteImageH', LML.HoldNoteHeadImage],
                ['NoteImageL', LML.HoldNoteBodyImage],
                ['NoteImageT', LML.HoldNoteTailImage],
                ['StageHint', LML.HitTargetImage],
                ['StageLeft', LML.LeftStageImage],
                ['StageRight', LML.RightStageImage],
                ['StageBottom', LML.BottomStageImage],
                ['StageLight', LML.LightImage],
                ['LightingN', LML.ExplosionImage],
                ['LightingL', LML.HoldNoteLightImage],
                ['Hit300g', LML.Hit300g],
            ];
            if (cfg) {
                lines.push(`  raw ColumnSpacing: [${cfg.ColumnSpacing.join(', ')}]`);
                lines.push(`  raw ColumnLineWidth: [${cfg.ColumnLineWidth.join(', ')}]`);
                lines.push(`  raw HitPosition: ${cfg.HitPosition}`);
                lines.push(`  raw ColumnStart: ${cfg.ColumnStart}`);
                lines.push(`  raw ScorePosition: ${cfg.ScorePosition}`);
                lines.push(`  raw ComboPosition: ${cfg.ComboPosition}`);
                lines.push(`  raw LightPosition: ${cfg.LightPosition}`);
                const clInfo = cfg.ColourLight ? cfg.ColourLight.slice(0, d.keys).map((c, i) => `c${i}:[${c.r},${c.g},${c.b}]`).join(' ') : 'none';
                lines.push(`  raw ColourLight: ${clInfo}`);
                lines.push(`  raw NoteBodyStyle: ${cfg.NoteBodyStyle}`);
                lines.push(`  raw ShowJudgementLine: ${cfg.ShowJudgementLine}`);
                lines.push(`  raw LightingNWidth: [${cfg.ExplosionWidth ? cfg.ExplosionWidth.join(', ') : ''}]`);
                lines.push(`  raw LightingLWidth: [${cfg.HoldNoteLightWidth ? cfg.HoldNoteLightWidth.join(', ') : ''}]`);
                lines.push(`  LightingN Scale col0: ${(getManiaSkinConfig(d.keys, LML.ExplosionScale, 0)?.value?.toFixed(2) || '1.00')}`);
                lines.push(`  LightingL Scale col0: ${(getManiaSkinConfig(d.keys, LML.HoldNoteLightScale, 0)?.value?.toFixed(2) || '1.00')}`);
                lines.push(`  raw KeysUnderNotes: ${cfg.KeysUnderNotes} (生效值: ${d.keysUnderNotes !== undefined ? d.keysUnderNotes : (cfg.KeysUnderNotes ? 1 : 0)})`);
                lines.push(`  -- all configs in map: [${[...maniaSkinConfigurations.keys()].join(', ')}]`);
            } else {
                lines.push('  config: NOT FOUND (using defaults)');
            }
            for (const [name, lookup] of lookups) {
                let img0 = getManiaSkinImage(d.keys, lookup, 0);
                let info;
                if (img0) {
                    info = `${img0.width}x${img0.height}${img0._is2x ? ' (@2x)' : ''}`;
                } else {
                    info = 'null';
                }
                let iniVal = '(默认文件名)';
                if (cfg) {
                    const info2 = imageLookupToIniPrefixSuffix(lookup);
                    if (info2 && !info2.fallbackOnly) {
                        const ci = '0';
                        const iniKey = info2.prefix + ci + info2.suffix;
                        if (cfg.ImageLookups.has(iniKey)) iniVal = cfg.ImageLookups.get(iniKey);
                        else if (cfg.ImageLookups.has(iniKey.toLowerCase())) iniVal = cfg.ImageLookups.get(iniKey.toLowerCase());
                    } else if (info2 && info2.fallbackOnly) {
                        iniVal = '(全局fallback)';
                    }
                }
                lines.push(`  ${name}[0]: ${info}  ini: "${iniVal}"`);
            }

            lines.push('');
            lines.push('--- 字体 / 数字贴图规范 (Fonts) ---');
            const explicitComboFont = getExplicitComboFontPrefix(d.keys);
            const activeComboPfx = explicitComboFont || skinFontsConfig.scorePrefix || 'score';
            const activeComboOverlap = (cfg && cfg.ComboOverlap != null) ? cfg.ComboOverlap : skinFontsConfig.comboOverlap;
            lines.push(`  ScorePrefix: "${skinFontsConfig.scorePrefix}" (overlap: ${skinFontsConfig.scoreOverlap})`);
            lines.push(`  ComboPrefix: "${skinFontsConfig.comboPrefix || '(inherit score)'}" (overlap: ${skinFontsConfig.comboOverlap})`);
            lines.push(`  HitCirclePrefix: "${skinFontsConfig.hitCirclePrefix}" (overlap: ${skinFontsConfig.hitCircleOverlap})`);
            lines.push(`  Mania Active FontCombo: "${activeComboPfx}" ${explicitComboFont ? '(ini 指定)' : '(未指定, 沿用 score 字体)'} (overlap: ${activeComboOverlap})`);
            let combo0Sample = getSkinFontImage('combo', '0', d.keys);
            let score0Sample = getSkinFontImage('score', '0', d.keys);
            lines.push(`  combo-0: ${combo0Sample ? `${combo0Sample.width}x${combo0Sample.height}${combo0Sample._is2x ? ' (@2x)' : ''}` : 'null'}`);
            lines.push(`  score-0: ${score0Sample ? `${score0Sample.width}x${score0Sample.height}${score0Sample._is2x ? ' (@2x)' : ''}` : 'null'}`);

            ctx.save();
            ctx.globalAlpha = 0.85;
            const panelW = 480;
            const panelH = lines.length * 16 + 16;
            const panelX = canvas.width - panelW - 10;
            const panelY = 10;
            ctx.fillStyle = '#1a1a2e';
            roundRect(ctx, panelX, panelY, panelW, panelH, 8);
            ctx.fill();
            ctx.strokeStyle = 'rgba(100, 200, 255, 0.5)';
            ctx.lineWidth = 1;
            roundRect(ctx, panelX, panelY, panelW, panelH, 8);
            ctx.stroke();
            ctx.globalAlpha = 1;
            ctx.font = '12px Consolas, monospace';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'top';
            for (let i = 0; i < lines.length; i++) {
                const line = lines[i];
                const y = panelY + 8 + i * 16;
                if (line.startsWith('=====') || line.startsWith('---')) {
                    ctx.fillStyle = '#66ccff';
                } else if (line.includes('null')) {
                    ctx.fillStyle = '#ff6b6b';
                } else {
                    ctx.fillStyle = '#e0e0e0';
                }
                ctx.fillText(line, panelX + 10, y);
            }
            ctx.restore();
        }


        function syncNotesStateWithTime(currentTimeMs) {
            judgements = [];
            activeExplosions = [];
            playbackBreakResumeTime = 0;
            judgementPreviewIndex = 0;
            comboAnimState.lastCombo = 0;
            comboAnimState.incStartTime = -1000;
            comboAnimState.breakStartTime = -1000;
            comboAnimState.breakCount = 0;
            resetComboHoldColourTint();
            for (let i = 0; i < activeNotes.length; i++) {
                let note = activeNotes[i];
                if (note.isHold) {
                    note.hit = (currentTimeMs >= note.startTime);
                    note.holdHeadFrozen = (currentTimeMs >= note.startTime);
                    note.tailHit = (currentTimeMs >= note.endTime);
                } else {
                    note.hit = (currentTimeMs >= note.startTime);
                }
            }
            if (typeof reconcileManiaHitsoundCues === 'function') {
                reconcileManiaHitsoundCues(currentTimeMs);
            }
        }

        // 说明：打击特效 (LightingN / LightingL) 过去会绘制一层「常驻虚线占位框」用于点选。
        // 现已按需求移除：改为「特效真正出现在画布上时才可点选」，与音符等元素的行为一致。
        // 选中后的可视化反馈统一交给 drawCanvasSelectionHighlight（白色圆角高亮外框）。

        function drawCanvasSelectionHighlight(ctx, elem, scale48) {
            if (!elem) return;

            const now = performance.now();
            const elapsed = now - selectionAnimStartTime;
            const ANIM_DURATION = 220; // 展开动画时长 220ms
            const progress = Math.min(1.0, Math.max(0.04, elapsed / ANIM_DURATION));
            // 三次方缓出 (Ease-Out Cubic)
            const ease = 1 - Math.pow(1 - progress, 3);

            // 比元素本体稍大一些：四周留 6px 留白 padding
            const pad = 6;
            const targetW = elem.w + pad * 2;
            const targetH = elem.h + pad * 2;
            const cx = elem.x + elem.w / 2;
            const cy = elem.y + elem.h / 2;

            // 从元素中心平滑展开
            const curW = Math.max(1, targetW * ease);
            const curH = Math.max(1, targetH * ease);
            const curX = cx - curW / 2;
            const curY = cy - curH / 2;

            ctx.save();

            // 透明的圆角矩形高亮外框 (白色样式)
            const cornerRadius = Math.min(8, Math.min(curW, curH) / 2);
            ctx.beginPath();
            roundRect(ctx, curX, curY, curW, curH, cornerRadius);

            // 透明底色填充 (纯白微透明)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
            ctx.fill();

            // 高亮边框描边 (纯白带微发光)
            ctx.strokeStyle = `rgba(255, 255, 255, ${0.45 + 0.5 * ease})`;
            ctx.lineWidth = 1.8;
            ctx.shadowColor = 'rgba(255, 255, 255, 0.5)';
            ctx.shadowBlur = 8;
            ctx.stroke();

            // 针对单轨元素渲染精致的右边缘拉伸控制条手柄
            if (elem.id.startsWith('track_col_') && progress >= 0.7) {
                const rightX = curX + curW;
                const handleH = Math.min(80, curH * 0.25);
                const handleY = (canvas.height - handleH) / 2;
                const isDraggingWidth = (isDraggingCanvasElement && canvasDragState &&
                    canvasDragState.element && canvasDragState.element.id === elem.id &&
                    canvasDragState.dragType === 'column_width');

                ctx.save();
                ctx.fillStyle = isDraggingWidth ? '#ffffff' : 'rgba(255, 255, 255, 0.95)';
                ctx.shadowColor = isDraggingWidth ? 'rgba(255, 102, 170, 0.9)' : 'rgba(255, 255, 255, 0.75)';
                ctx.shadowBlur = isDraggingWidth ? 12 : 8;
                ctx.beginPath();
                if (ctx.roundRect) {
                    ctx.roundRect(rightX - 2.5, handleY, 5, handleH, 2.5);
                } else {
                    ctx.rect(rightX - 2.5, handleY, 5, handleH);
                }
                ctx.fill();
                ctx.restore();
            }

            // KeyImage 上边框拉伸手柄：向上拖补底部透明像素，向下拖裁短 PNG，从而改变有效高度。
            if (elem.id.startsWith('key_') && elem.keyImageHeightAdjustable && progress >= 0.7) {
                const edgeY = Math.max(2, Math.min(canvas.height - 2,
                    elem.keyImageResizeEdgeY != null ? elem.keyImageResizeEdgeY : elem.y));
                const handleW = Math.max(28, Math.min(68, curW * 0.72));
                const handleH = 5;
                const handleX = elem.x + (elem.w - handleW) / 2;
                const isDraggingHeight = (isDraggingCanvasElement && canvasDragState &&
                    canvasDragState.element && canvasDragState.element.id === elem.id &&
                    canvasDragState.dragType === 'key_image_height');

                ctx.save();
                ctx.fillStyle = isDraggingHeight ? '#ffffff' : 'rgba(255, 255, 255, 0.95)';
                ctx.shadowColor = isDraggingHeight ? 'rgba(255, 102, 170, 0.95)' : 'rgba(255, 255, 255, 0.75)';
                ctx.shadowBlur = isDraggingHeight ? 12 : 8;
                ctx.beginPath();
                if (ctx.roundRect) {
                    ctx.roundRect(handleX, edgeY - handleH / 2, handleW, handleH, handleH / 2);
                } else {
                    ctx.rect(handleX, edgeY - handleH / 2, handleW, handleH);
                }
                ctx.fill();
                ctx.restore();
            }

            // 贯穿全屏的水平参考虚线（针对判定线、连击数、判定评价、光效等 Y 轴位置元素：选中期间持续常驻显示，拖动与步进实时联动）
            // 轨道选取的垂直参考虚线已按要求彻底删除
            if (elem.dragAxis === 'y' && !elem.id.startsWith('track_col_')) {
                ctx.setLineDash([6, 4]);
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
                ctx.lineWidth = 1.2;
                ctx.beginPath();
                const midY = elem.y + elem.h / 2;
                ctx.moveTo(0, midY);
                ctx.lineTo(canvas.width, midY);
                ctx.stroke();
                ctx.setLineDash([]);
            }

            ctx.restore();

            // 若动画未播放完毕，驱动下一帧渲染以保证流畅 60fps 展开
            if (progress < 1.0) {
                cancelAnimationFrame(animationId);
                animationId = requestAnimationFrame(drawFrame);
            }
        }

        // 3. 将画布选中元素的坐标同步到紧贴矩形框的操作工具栏
        function syncCanvasSize() {
            if (!canvas) return;
            const parent = canvas.parentElement;
            const w = Math.round(canvas.clientWidth || (parent ? parent.clientWidth : 0));
            const h = Math.round(canvas.clientHeight || (parent ? parent.clientHeight : 0));
            if (w > 0 && h > 0 && (canvas.width !== w || canvas.height !== h)) {
                canvas.width = w;
                canvas.height = h;
                if (typeof drawFrame === 'function') {
                    drawFrame();
                }
            }
        }
