        function renderSkinEditorParams() {
            const container = document.getElementById('paramListContainer');
            if (!container) return;
            container.innerHTML = '';
            if (typeof isSkinEditingWorkspaceReady === 'function' && !isSkinEditingWorkspaceReady()) {
                if (typeof syncSkinEditingAvailabilityUI === 'function') syncSkinEditingAvailabilityUI();
                return;
            }
            if (activeEditorTab === 'hitsounds' && typeof renderHitsoundEditor === 'function') {
                renderHitsoundEditor(container);
                return;
            }

            const keys = activeEditorKeyCount;
            const cfg = maniaSkinConfigurations.get(keys) || maniaSkinConfigurations.get(4) || {};
            const q = paramSearchQuery.trim().toLowerCase();

            // 若在 Mania 标签页但未读取到任何 Mania 键位配置
            if (activeEditorTab === 'mania' && maniaSkinConfigurations.size === 0) {
                container.innerHTML = `
                    <div style="text-align:center; padding: 48px 20px; color: rgba(255,255,255,0.65); font-size: 0.88rem;">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="36" height="36" style="margin-bottom: 12px; opacity: 0.45;">
                            <circle cx="12" cy="12" r="10"></circle>
                            <line x1="12" y1="8" x2="12" y2="12"></line>
                            <line x1="12" y1="16" x2="12.01" y2="16"></line>
                        </svg>
                        <div style="font-weight: 600; color: #ffffff; margin-bottom: 6px;">未读取到任何 [Mania] 键位配置</div>
                        <div style="font-size: 0.78rem; color: rgba(255,255,255,0.45); max-width: 320px; margin: 0 auto; line-height: 1.5;">
                            当前导入的皮肤 skin.ini 中不包含 [Mania] 键位区块。请导入包含 Mania 键位配置的皮肤以进行可视化调整。
                        </div>
                    </div>
                `;
                return;
            }

            // 过滤参数
            const filtered = SKIN_INI_PARAM_SCHEMA.filter(p => {
                if (p.tab !== activeEditorTab) return false;
                if (!q) return true;
                return p.key.toLowerCase().includes(q) ||
                    p.zhName.toLowerCase().includes(q) ||
                    p.enName.toLowerCase().includes(q) ||
                    p.desc.toLowerCase().includes(q) ||
                    p.comment.toLowerCase().includes(q);
            });

            const isFontsTab = (activeEditorTab === 'fonts');
            const fontGlyphParams = isFontsTab && typeof buildFontGlyphTextureParams === 'function'
                ? buildFontGlyphTextureParams(keys)
                : [];
            const hudGlyphMatchesQuery = isFontsTab && (!q ||
                fontGlyphParams.some((p) =>
                    p.zhName.toLowerCase().includes(q) ||
                    p.default.toLowerCase().includes(q) ||
                    p._fontGlyph.char.includes(q)
                ) ||
                '右上角数字贴图0123456789. %scoredotpercentfonts'.includes(q));

            if (filtered.length === 0 && !hudGlyphMatchesQuery) {
                container.innerHTML = `<div style="text-align:center; padding: 40px; color: rgba(255,255,255,0.45); font-size: 0.9rem;">未找到与 "${q}" 匹配的参数</div>`;
                return;
            }

            // 若在 Fonts 标签页，在参数列表顶部追加渲染 "数字贴图"(分数) 与 "连击数字贴图"
            if (isFontsTab && hudGlyphMatchesQuery) {
                const makeGlyphView = (p) => {
                    const char = p._fontGlyph.char;
                    const scoreTargetIds = {
                        '0': 'hud_score_digit_0',
                        '1': 'hud_score_digit_1',
                        '2': 'hud_score_digit_2',
                        '3': 'hud_score_digit_3',
                        '4': 'hud_score_digit_4',
                        '5': 'hud_score_digit_5',
                        '6': 'hud_score_digit_6',
                        '7': 'hud_score_digit_7',
                        '8': 'hud_acc_glyph_1',
                        '9': 'hud_acc_glyph_0',
                        '.': 'hud_acc_glyph_2',
                        '%': 'hud_acc_glyph_5'
                    };
                    return {
                        char,
                        label: p.zhName,
                        tex: p.default,
                        param: p,
                        targetId: p._fontGlyph.group === 'combo'
                            ? 'combo'
                            : scoreTargetIds[char]
                    };
                };
                const scoreGlyphs = fontGlyphParams
                    .filter((p) => p._fontGlyph.group === 'score')
                    .map(makeGlyphView);
                container.appendChild(buildFontGlyphBlock({
                    title: '数字贴图',
                    glyphs: scoreGlyphs,
                    fontType: 'score',
                    uploadParamKey: 'ScorePrefix',
                    cardIdPrefix: 'glyph-card',
                    keys, q,
                    locate: (g) => canvasInteractiveElements.find(i => i.id === g.targetId) ||
                                   canvasInteractiveElements.find(i => i.textureName === g.tex)
                }));

                const comboGlyphs = fontGlyphParams
                    .filter((p) => p._fontGlyph.group === 'combo')
                    .map(makeGlyphView);
                container.appendChild(buildFontGlyphBlock({
                    title: '连击数字贴图',
                    glyphs: comboGlyphs,
                    fontType: 'combo',
                    uploadParamKey: 'ComboPrefix',
                    cardIdPrefix: 'combo-glyph-card',
                    blockClass: 'combo-font-glyphs-block',
                    keys, q,
                    locate: () => canvasInteractiveElements.find(i => i.id === 'combo')
                }));
            }

            // 逐轨道贴图参数展开为「每轨一张卡片」(NoteImage0..N / KeyImage0..N 等)，
            // 使每一项都拥有与其他贴图参数完全一致的上传按钮，而不是「一个总体 + 若干简化行」
            const expandedItems = [];
            for (const item of filtered) {
                const perTrack = expandPerTrackTextureParams(item, keys);
                if (perTrack && perTrack.length > 0) expandedItems.push(...perTrack);
                else expandedItems.push(item);
            }

            // 按 Category 分组
            const groups = new Map();
            for (const item of expandedItems) {
                if (!groups.has(item.category)) groups.set(item.category, []);
                groups.get(item.category).push(item);
            }

            for (const [catName, items] of groups.entries()) {
                const isFontsAdvanced = (activeEditorTab === 'fonts' && catName === '字体排版');

                const block = document.createElement('div');
                block.className = 'param-category-block';

                // 每个分类都可折叠：折叠状态按「标签页::分类名」记忆；
                // 搜索时强制展开，保证搜到的参数不会被折叠挡住。
                const collapseKey = activeEditorTab + '::' + catName;
                const isCollapsed = !isFontsAdvanced && !q && collapsedParamCategories.has(collapseKey);
                block.dataset.categoryKey = collapseKey;
                if (isCollapsed) block.classList.add('collapsed');

                if (isFontsAdvanced) {
                    block.classList.add('fonts-advanced-category-block');
                    const isSearching = !!q;
                    const isExpanded = isSearching || isFontsAdvancedExpanded;
                    if (isExpanded) {
                        block.classList.add('expanded');
                    }

                    const toggleBar = document.createElement('div');
                    toggleBar.className = 'advanced-settings-toggle-bar';

                    const toggleBtn = document.createElement('button');
                    toggleBtn.type = 'button';
                    toggleBtn.className = `advanced-toggle-btn ${isExpanded ? 'active' : ''}`;
                    toggleBtn.innerHTML = `
                        <div class="advanced-toggle-left">
                            <svg class="advanced-toggle-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                                <polyline points="9 18 15 12 9 6"></polyline>
                            </svg>
                            <span class="advanced-toggle-label">${isExpanded ? '收起高级设置 (字体排版与前缀)' : '展开高级设置 (字体排版与前缀)'}</span>
                            <span class="count-badge">${items.length}</span>
                        </div>
                        <span class="advanced-toggle-hint">${isExpanded ? '点击收起' : '点击展开高级参数'}</span>
                    `;

                    toggleBtn.onclick = () => {
                        isFontsAdvancedExpanded = !isFontsAdvancedExpanded;
                        const nowExpanded = isFontsAdvancedExpanded;
                        block.classList.toggle('expanded', nowExpanded);
                        toggleBtn.classList.toggle('active', nowExpanded);
                        toggleBtn.querySelector('.advanced-toggle-label').textContent = nowExpanded ? '收起高级设置 (字体排版与前缀)' : '展开高级设置 (字体排版与前缀)';
                        toggleBtn.querySelector('.advanced-toggle-hint').textContent = nowExpanded ? '点击收起' : '点击展开高级参数';
                    };

                    toggleBar.appendChild(toggleBtn);
                    container.appendChild(toggleBar);
                }

                const contentParent = isFontsAdvanced ? document.createElement('div') : block;
                if (isFontsAdvanced) {
                    contentParent.className = 'fonts-advanced-inner';
                }

                if (!isFontsAdvanced) {
                    // 分类标题本身即折叠按钮（保留 .param-category-title 类与内部 span 结构，
                    // 外观沿用原分类标题样式，只额外加一个箭头指示器）
                    const title = document.createElement('button');
                    title.type = 'button';
                    title.className = 'param-category-title param-category-toggle';
                    title.title = '点击折叠 / 展开该分类';
                    title.innerHTML = `
                        <svg class="cat-toggle-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                        <span>${catName}</span><span class="count-badge">${items.length}</span>
                    `;
                    title.onclick = () => {
                        const nowCollapsed = !block.classList.contains('collapsed');
                        block.classList.toggle('collapsed', nowCollapsed);
                        if (nowCollapsed) collapsedParamCategories.add(collapseKey);
                        else collapsedParamCategories.delete(collapseKey);
                    };
                    block.appendChild(title);
                }

                const grid = document.createElement('div');
                grid.className = 'param-cards-grid';

                // 同一贴图类型 (NoteImage / 长条头身尾 / KeyImage / KeyImageD) 的所有轨道
                // 合并为同一个分组框渲染单元；其余参数仍保持各自独立卡片。
                const renderUnits = [];
                for (const item of items) {
                    if (item._trackGroupKey) {
                        const last = renderUnits[renderUnits.length - 1];
                        if (last && last.kind === 'trackGroup' && last.groupKey === item._trackGroupKey) {
                            last.items.push(item);
                        } else {
                            renderUnits.push({
                                kind: 'trackGroup',
                                groupKey: item._trackGroupKey,
                                groupName: item._trackGroupZhName || item._trackGroupName || item._trackGroupKey,
                                groupEnName: item._trackGroupEnName,
                                desc: item._trackGroupDesc,
                                items: [item],
                            });
                        }
                    } else {
                        renderUnits.push({ kind: 'card', p: item });
                    }
                }

                for (const unit of renderUnits) {
                    if (unit.kind === 'trackGroup') {
                        grid.appendChild(buildPerTrackTextureGroup(unit, keys));
                        continue;
                    }
                    const p = unit.p;
                    const card = document.createElement('div');
                    card.className = 'param-card';
                    card.id = `param-card-${p.key}`;

                    // 当前数值获取
                    let val = p.default;
                    if (p.key === 'ScorePercentWidth') {
                        val = getScorePercentPaddingWidth(keys);
                    } else if (p.key === 'ScorePercentVisible') {
                        val = getScorePercentVisibility(keys);
                    } else if (p.key === 'ComboBurstRandom') {
                        val = !!(currentSkinMetadata.general &&
                            (currentSkinMetadata.general.ComboBurstRandom === 1 ||
                             currentSkinMetadata.general.ComboBurstRandom === '1' ||
                             currentSkinMetadata.general.ComboBurstRandom === true));
                    } else if (p.tab === 'mania' || p.tab === 'textures') {
                        if (cfg[p.key] !== undefined && cfg[p.key] !== null) val = cfg[p.key];
                    } else if (p.tab === 'fonts') {
                        if (p.key === 'ScorePrefix') {
                            val = (cfg && cfg.FontScore) || skinFontsConfig.scorePrefix || 'score';
                        }
                        else if (p.key === 'ScoreOverlap') val = getSkinFontOverlap('score', keys);
                        else if (p.key === 'ComboPrefix') {
                            // 显示「实际生效」的连击字体前缀：ini 显式指定了 [Mania] FontCombo / [Fonts] ComboPrefix 才有值，
                            // 都没有时留空 (占位符会说明实际沿用 score 字体贴图)，避免面板与画布不一致
                            val = getExplicitComboFontPrefix(keys) || '';
                        }
                        else if (p.key === 'ComboOverlap') val = getSkinFontOverlap('combo', keys);
                        else if (p.key === 'HitCirclePrefix') val = skinFontsConfig.hitCirclePrefix || 'default';
                        else if (p.key === 'HitCircleOverlap') {
                            val = skinFontsConfig.hitCircleOverlap != null
                                ? skinFontsConfig.hitCircleOverlap
                                : -2;
                        }
                    } else if (p.tab === 'general') {
                        if (currentSkinMetadata.general && currentSkinMetadata.general[p.key] !== undefined) {
                            val = currentSkinMetadata.general[p.key];
                        }
                    } else if (p.tab === 'colours') {
                        if (currentSkinMetadata.colours && currentSkinMetadata.colours[p.key] !== undefined) {
                            val = currentSkinMetadata.colours[p.key];
                        }
                    }

                    // Card 头部
                    const header = document.createElement('div');
                    header.className = 'param-card-header';
                    header.innerHTML = `
                        <div class="param-names">
                            <span class="param-zh-name">${p.zhName}</span>
                            ${p.desc ? `
                                <span class="param-info-trigger" tabindex="0">
                                    <span class="param-info-icon">ⓘ</span>
                                    <div class="param-desc-tooltip">${p.desc}</div>
                                </span>
                            ` : ''}
                            <span class="param-en-name">${p.enName}</span>
                        </div>
                    `;

                    // 右侧快捷定位与重置操作按钮
                    const actionsArea = document.createElement('div');
                    actionsArea.style.display = 'flex';
                    actionsArea.style.gap = '4px';

                    if (p.elementId) {
                        const locateBtn = document.createElement('button');
                        locateBtn.type = 'button';
                        locateBtn.className = 'param-action-btn locate';
                        locateBtn.title = '在画布上框选此元素';
                        locateBtn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="13" height="13"><circle cx="12" cy="12" r="3"></circle><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"></path></svg>`;
                        locateBtn.onclick = () => {
                            const target = canvasInteractiveElements.find(i => i.id === p.elementId) ||
                                canvasInteractiveElements.find(i => i.paramKey === p.key);
                            if (target) {
                                selectedCanvasElement = target;
                                selectionAnimStartTime = performance.now();
                                syncCanvasSelectedCard(target);
                                drawFrame();
                            }
                        };
                        actionsArea.appendChild(locateBtn);
                    }

                    if (actionsArea.children.length > 0) {
                        header.appendChild(actionsArea);
                    }

                    if (p.notice) {
                        const notice = document.createElement('span');
                        notice.className = 'param-inline-notice';
                        notice.textContent = p.notice;
                        const names = header.querySelector('.param-names');
                        if (names) names.appendChild(notice);
                    }
                    card.appendChild(header);

                    // 输入控制行
                    const controlRow = document.createElement('div');
                    controlRow.className = 'param-control-row';

                    if (p.type === 'number') {
                        const numVal = (typeof val === 'number') ? val : (parseFloat(val) || p.default);
                        const combo = document.createElement('div');
                        combo.className = 'slider-input-combo';

                        const range = document.createElement('input');
                        range.type = 'range';
                        range.min = p.min;
                        range.max = p.max;
                        range.step = p.step;
                        range.value = numVal;

                        const updateRangeFill = (v) => {
                            const min = (p.min != null) ? p.min : 0;
                            const max = (p.max != null) ? p.max : 100;
                            const vf = (v != null && !isNaN(parseFloat(v))) ? parseFloat(v) : min;
                            const pct = max > min ? Math.min(100, Math.max(0, ((vf - min) / (max - min)) * 100)) : 0;
                            range.style.setProperty('--slider-pct', `${pct}%`);
                        };
                        updateRangeFill(numVal);

                        const num = document.createElement('input');
                        num.type = 'number';
                        num.min = p.min;
                        num.max = p.max;
                        num.step = p.step;
                        num.value = numVal;

                        range.oninput = (e) => {
                            updateRangeFill(e.target.value);
                            num.value = e.target.value;
                            onParamChange(p.key, parseFloat(e.target.value));
                        };
                        num.onchange = (e) => {
                            range.value = e.target.value;
                            updateRangeFill(e.target.value);
                            onParamChange(p.key, parseFloat(e.target.value));
                        };

                        combo.appendChild(range);
                        combo.appendChild(num);
                        controlRow.appendChild(combo);
                    } else if (p.type === 'boolean') {
                        const isChecked = !!(val === true || val === 1 || val === '1' || val === 'true');
                        const toggleBox = document.createElement('div');
                        toggleBox.style.display = 'flex';
                        toggleBox.style.alignItems = 'center';
                        toggleBox.style.gap = '8px';

                        const toggleLabel = document.createElement('label');
                        toggleLabel.className = 'ios-switch';
                        toggleLabel.innerHTML = `
                            <input type="checkbox" ${isChecked ? 'checked' : ''}>
                            <span class="slider"></span>
                        `;
                        const statusSpan = document.createElement('span');
                        statusSpan.style.fontSize = '0.8rem';
                        statusSpan.style.color = isChecked ? '#ffffff' : 'rgba(255,255,255,0.45)';
                        statusSpan.textContent = isChecked ? '开启' : '关闭';

                        const chk = toggleLabel.querySelector('input');
                        chk.onchange = (e) => {
                            statusSpan.textContent = e.target.checked ? '开启' : '关闭';
                            statusSpan.style.color = e.target.checked ? '#ffffff' : 'rgba(255,255,255,0.45)';
                            onParamChange(
                                p.key,
                                e.target.checked,
                                null,
                                p.key === 'ComboBurstRandom' ? { force: true } : {}
                            );
                        };

                        toggleBox.appendChild(toggleLabel);
                        toggleBox.appendChild(statusSpan);
                        controlRow.appendChild(toggleBox);
                    } else if (p.type === 'select') {
                        const select = document.createElement('select');
                        select.className = 'param-select';
                        for (const opt of p.options) {
                            const option = document.createElement('option');
                            option.value = opt.value;
                            option.textContent = opt.label;
                            if (String(opt.value) === String(val)) option.selected = true;
                            select.appendChild(option);
                        }
                        select.onchange = (e) => onParamChange(
                            p.key,
                            e.target.value,
                            null,
                            p.key === 'ComboBurstStyle' ? { force: true } : {}
                        );
                        controlRow.appendChild(select);
                    } else if (p.type === 'color') {
                        const combo = document.createElement('div');
                        combo.className = 'color-picker-combo';

                        let rgbStr = (typeof val === 'object' && val) ? `${val.r || 255},${val.g || 0},${val.b || 0}` : String(val);
                        const parts = rgbStr.split(',').map(s => parseInt(s.trim(), 10) || 0);
                        const hex = `#${((1 << 24) + (parts[0] << 16) + (parts[1] << 8) + parts[2]).toString(16).slice(1)}`;

                        const picker = document.createElement('input');
                        picker.type = 'color';
                        picker.value = hex;

                        const text = document.createElement('input');
                        text.type = 'text';
                        text.className = 'color-text';
                        text.value = rgbStr;

                        picker.oninput = (e) => {
                            const h = e.target.value;
                            const r = parseInt(h.slice(1, 3), 16);
                            const g = parseInt(h.slice(3, 5), 16);
                            const b = parseInt(h.slice(5, 7), 16);
                            text.value = `${r},${g},${b}`;
                            onParamChange(p.key, text.value);
                            if (p.key === 'ComboBreakColour') {
                                triggerComboBreakPreview();
                            }
                        };
                        text.onchange = (e) => {
                            onParamChange(p.key, e.target.value);
                            if (p.key === 'ComboBreakColour') {
                                triggerComboBreakPreview();
                            }
                        };

                        combo.appendChild(picker);
                        combo.appendChild(text);

                        if (p.key === 'ComboBreakColour') {
                            const previewBreakBtn = document.createElement('button');
                            previewBreakBtn.type = 'button';
                            previewBreakBtn.className = 'col-colour-preview-btn';
                            previewBreakBtn.innerHTML = `
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12">
                                    <polygon points="5 3 19 12 5 21 5 3"></polygon>
                                </svg>
                                <span>预览断连</span>
                            `;
                            previewBreakBtn.onclick = () => {
                                triggerComboBreakPreview();
                            };
                            combo.appendChild(previewBreakBtn);
                        }

                        controlRow.appendChild(combo);
                    } else if (p.type === 'column_colour') {
                        // 轨道底色 (Colour1..N)：与按键动画颜色 ColourLight1..N 同构，共用同一个管理器
                        controlRow.appendChild(buildPerTrackColourManager(cfg, keys, {
                            arrKey: 'ColumnColour',
                            iniPrefix: 'Colour',
                            defaultColour: { r: 0, g: 0, b: 0, a: 255 },
                            unifiedTitle: '全轨统一底色与透明度',
                            what: '底色'
                        }));
                    } else if (p.type === 'light_colour') {
                        // 按键动画颜色 (ColourLight1..N)：对应 lazer LegacyColumnBackground 的
                        // ColumnLightColour lookup，未指定时引擎回退纯白。
                        controlRow.appendChild(buildPerTrackColourManager(cfg, keys, {
                            arrKey: 'ColourLight',
                            iniPrefix: 'ColourLight',
                            defaultColour: { r: 255, g: 255, b: 255, a: 255 },
                            unifiedTitle: '全轨统一按键动画颜色与透明度',
                            what: '动画颜色',
                            withPreview: true,
                            alphaZeroForcedOpaque: true
                        }));
                    } else if (p.type === 'colour_hold') {
                        const curHold = cfg.ColourHold || { r: 255, g: 191, b: 51, a: 255 };
                        const curHex = `#${((1 << 24) + (curHold.r << 16) + (curHold.g << 8) + curHold.b).toString(16).slice(1)}`;

                        const mainControls = document.createElement('div');
                        mainControls.className = 'colour-hold-controls';

                        const picker = document.createElement('input');
                        picker.type = 'color';
                        picker.className = 'col-colour-picker';
                        picker.value = curHex;

                        const alphaSlider = document.createElement('input');
                        alphaSlider.type = 'range';
                        alphaSlider.min = 0;
                        alphaSlider.max = 255;
                        alphaSlider.step = 1;
                        alphaSlider.value = (curHold.a != null) ? curHold.a : 255;
                        alphaSlider.className = 'col-colour-slider';
                        const holdInitPct = Math.max(0, Math.min(100, Math.round(alphaSlider.value / 255 * 100))) + '%';
                        alphaSlider.style.setProperty('--slider-pct', holdInitPct);

                        const alphaLabel = document.createElement('span');
                        alphaLabel.className = 'col-colour-val';
                        const updateHoldLabel = (a) => {
                            const pct = Math.max(0, Math.min(100, Math.round(a / 255 * 100)));
                            alphaLabel.textContent = `A: ${a} (${pct}%)`;
                            alphaSlider.style.setProperty('--slider-pct', `${pct}%`);
                        };
                        updateHoldLabel(parseInt(alphaSlider.value, 10));

                        const previewHoldBtn = document.createElement('button');
                        previewHoldBtn.type = 'button';
                        previewHoldBtn.className = 'col-colour-preview-btn';
                        previewHoldBtn.innerHTML = `
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12">
                                <polygon points="5 3 19 12 5 21 5 3"></polygon>
                            </svg>
                            <span>预览变色</span>
                        `;

                        const updateColourHold = () => {
                            recordSkinUndoBeforeChange('调整按住hold时连击字体颜色');
                            const hex = picker.value;
                            const r = parseInt(hex.slice(1, 3), 16);
                            const g = parseInt(hex.slice(3, 5), 16);
                            const b = parseInt(hex.slice(5, 7), 16);
                            const a = parseInt(alphaSlider.value, 10);
                            updateHoldLabel(a);
                            cfg.ColourHold = { r, g, b, a };
                            testHoldingUntil = performance.now() + 2500;
                            drawFrame();
                        };

                        previewHoldBtn.onclick = () => {
                            testHoldingUntil = performance.now() + 2500;
                            drawFrame();
                        };

                        picker.oninput = updateColourHold;
                        alphaSlider.oninput = updateColourHold;

                        mainControls.appendChild(picker);
                        mainControls.appendChild(alphaSlider);
                        mainControls.appendChild(alphaLabel);
                        mainControls.appendChild(previewHoldBtn);

                        controlRow.appendChild(mainControls);
                    } else if (p.type === 'colour_barline') {
                        const curBarline = cfg.ColourBarline || { r: 255, g: 255, b: 255, a: 255 };
                        const curHex = `#${((1 << 24) + (curBarline.r << 16) + (curBarline.g << 8) + curBarline.b).toString(16).slice(1)}`;

                        const mainControls = document.createElement('div');
                        mainControls.className = 'colour-barline-controls';

                        const picker = document.createElement('input');
                        picker.type = 'color';
                        picker.className = 'col-colour-picker';
                        picker.value = curHex;
                        picker.title = '选择小节线颜色';

                        const alphaSlider = document.createElement('input');
                        alphaSlider.type = 'range';
                        alphaSlider.min = 0;
                        alphaSlider.max = 255;
                        alphaSlider.step = 1;
                        alphaSlider.value = (curBarline.a != null) ? curBarline.a : 255;
                        alphaSlider.className = 'col-colour-slider';
                        alphaSlider.title = '调整小节线透明度';
                        const pctInit = ((alphaSlider.value / 255) * 100).toFixed(1) + '%';
                        alphaSlider.style.setProperty('--slider-pct', pctInit);

                        const alphaLabel = document.createElement('span');
                        alphaLabel.className = 'col-colour-val';
                        const updateBarlineLabel = (a) => {
                            const pct = Math.round(a / 255 * 100);
                            alphaLabel.textContent = `A: ${a} (${pct}%)`;
                        };
                        updateBarlineLabel(parseInt(alphaSlider.value, 10));

                        const textInput = document.createElement('input');
                        textInput.type = 'text';
                        textInput.className = 'color-text';
                        textInput.value = `${curBarline.r},${curBarline.g},${curBarline.b},${curBarline.a != null ? curBarline.a : 255}`;
                        textInput.title = '直接输入 RGBA 格式数值 (r,g,b,a)';

                        const updateColourBarline = (recordUndo = true) => {
                            if (recordUndo) recordSkinUndoBeforeChange('调整小节线颜色');
                            const hex = picker.value;
                            const r = parseInt(hex.slice(1, 3), 16);
                            const g = parseInt(hex.slice(3, 5), 16);
                            const b = parseInt(hex.slice(5, 7), 16);
                            const a = parseInt(alphaSlider.value, 10);
                            const pct = ((a / 255) * 100).toFixed(1) + '%';
                            alphaSlider.style.setProperty('--slider-pct', pct);
                            updateBarlineLabel(a);
                            textInput.value = `${r},${g},${b},${a}`;
                            cfg.ColourBarline = { r, g, b, a };
                            drawFrame();
                        };

                        picker.oninput = () => updateColourBarline(false);
                        picker.onchange = () => updateColourBarline(true);
                        alphaSlider.oninput = () => updateColourBarline(false);
                        alphaSlider.onchange = () => updateColourBarline(true);

                        textInput.onchange = (e) => {
                            const parts = e.target.value.split(',').map(s => parseInt(s.trim(), 10));
                            if (parts.length >= 3 && !parts.slice(0, 3).some(isNaN)) {
                                recordSkinUndoBeforeChange('调整小节线颜色');
                                const r = Math.max(0, Math.min(255, parts[0]));
                                const g = Math.max(0, Math.min(255, parts[1]));
                                const b = Math.max(0, Math.min(255, parts[2]));
                                const a = (parts.length >= 4 && !isNaN(parts[3])) ? Math.max(0, Math.min(255, parts[3])) : 255;
                                cfg.ColourBarline = { r, g, b, a };
                                picker.value = `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
                                alphaSlider.value = a;
                                const pct = ((a / 255) * 100).toFixed(1) + '%';
                                alphaSlider.style.setProperty('--slider-pct', pct);
                                updateBarlineLabel(a);
                                textInput.value = `${r},${g},${b},${a}`;
                                drawFrame();
                            }
                        };

                        mainControls.appendChild(picker);
                        mainControls.appendChild(alphaSlider);
                        mainControls.appendChild(alphaLabel);
                        mainControls.appendChild(textInput);

                        controlRow.appendChild(mainControls);
                    } else if (p.type === 'array_number') {
                        let arrVal = Array.isArray(val) ? [...val] : String(val).split(',').map(s => parseFloat(s.trim()) || 0);
                        let arrStr = arrVal.map(Math.round).join(',');
                        const input = document.createElement('input');
                        input.type = 'text';
                        input.className = 'param-text-input';
                        input.value = arrStr;
                        input.placeholder = (p.key === 'ColumnLineWidth')
                            ? '以逗号隔开的数组 (如 2,2,2,2,2)'
                            : '以逗号隔开的数组 (如 30,30,30,30)';
                        controlRow.appendChild(input);

                        // 渲染各轨独立快速微调输入框 chips (支持各轨道宽度与间距直接修改)
                        const chipsGrid = document.createElement('div');
                        chipsGrid.className = 'array-chips-grid';

                        const numChips = (p.key === 'ColumnSpacing')
                            ? Math.max(0, keys - 1)
                            : ((p.key === 'ColumnLineWidth') ? keys + 1 : keys);
                        for (let c = 0; c < numChips; c++) {
                            const chip = document.createElement('div');
                            chip.className = 'array-chip';
                            const label = document.createElement('span');
                            label.className = 'chip-label';
                            if (p.key === 'ColumnSpacing') {
                                label.textContent = `轨${c + 1}-${c + 2}距`;
                            } else if (p.key === 'ColumnLineWidth') {
                                if (c === 0) label.textContent = '左边界';
                                else if (c === keys) label.textContent = '右边界';
                                else label.textContent = `轨${c}-${c + 1}线`;
                            } else {
                                label.textContent = `第${c + 1}轨宽`;
                            }

                            const chipInput = document.createElement('input');
                            chipInput.type = 'number';
                            chipInput.className = 'array-chip-input';
                            chipInput.min = p.min != null ? p.min : 0;
                            chipInput.max = p.max != null ? p.max : 300;
                            chipInput.value = (arrVal[c] != null) ? Math.round(arrVal[c]) : (p.default || 0);

                            chipInput.oninput = () => {
                                const num = parseFloat(chipInput.value) || 0;
                                arrVal[c] = num;
                                input.value = arrVal.map(Math.round).join(',');
                                // 传入改动下标：超限时只收敛当前这一项，并即时回写实际生效值
                                const applied = onParamChange(p.key, arrVal, c);
                                if (Array.isArray(applied)) {
                                    arrVal = applied.slice();
                                    input.value = applied.map(Math.round).join(',');
                                    if (Math.round(applied[c]) !== Math.round(num)) {
                                        chipInput.value = Math.round(applied[c]);
                                    }
                                }
                            };

                            chip.appendChild(label);
                            chip.appendChild(chipInput);
                            chipsGrid.appendChild(chip);
                        }
                        controlRow.appendChild(chipsGrid);

                        input.onchange = (e) => {
                            const typed = String(e.target.value).split(',').map(s => parseFloat(s.trim()) || 0);
                            // 整组替换：若轨道区总宽度超限则本次修改不予采纳，并回写实际生效值
                            const applied = onParamChange(p.key, e.target.value);
                            const parts = Array.isArray(applied) ? applied : typed;
                            arrVal = parts.slice();
                            const allInputs = chipsGrid.querySelectorAll('.array-chip-input');
                            allInputs.forEach((ci, idx) => {
                                if (parts[idx] !== undefined) ci.value = Math.round(parts[idx]);
                            });
                            const changed = parts.length !== typed.length
                                || parts.some((v, i) => Math.round(v) !== Math.round(typed[i]));
                            if (changed) input.value = parts.map(v => Math.round(v)).join(',');
                        };
                    } else if (p.type === 'texture') {
                        // 贴图参数控件 (缩略图 + 路径输入 + 上传下拉) 统一由 buildTextureParamControl 构建，
                        // 与「逐轨道贴图分组框」内的每一行共用同一实现，保证样式与行为完全一致。
                        controlRow.appendChild(buildTextureParamControl(p, keys, card));
                    } else {
                        const input = document.createElement('input');
                        input.type = 'text';
                        input.className = 'param-text-input';
                        input.value = (val !== undefined && val !== null) ? val : '';
                        // 连击数字前缀：留空时提示「实际沿用 score 字体贴图」，避免与画布渲染结果不一致
                        if (p.key === 'ComboPrefix') {
                            const effComboFont = getExplicitComboFontPrefix(keys);
                            input.placeholder = effComboFont
                                ? `如 ${effComboFont}-0.png`
                                : 'ini 未指定 (实际使用: score 字体贴图)';
                        }
                        input.onchange = (e) => onParamChange(p.key, e.target.value);
                        controlRow.appendChild(input);
                    }

                    card.appendChild(controlRow);
                    grid.appendChild(card);
                }

                contentParent.appendChild(grid);
                if (isFontsAdvanced) {
                    block.appendChild(contentParent);
                }
                container.appendChild(block);
            }
        }
// --- END ui/param-render.js ---

// --- BEGIN ui/texture-project-archive.js ---
// ============================================================================
// texture-project-archive.js - 可续编贴图工程数据在皮肤归档内的读写
// 依赖：skin-assets、texture-image-editor-recipes、texture-image-editor-state、JSZip
// ============================================================================

        const TEXTURE_PROJECT_FORMAT = 'osu-mania-skin-editor/texture-project';
        const TEXTURE_PROJECT_VERSION = 1;
        const TEXTURE_PROJECT_ROOT = '_skin-editor';
        const TEXTURE_PROJECT_MANIFEST_PATH = `${TEXTURE_PROJECT_ROOT}/texture-project.json`;
        const TEXTURE_PROJECT_SOURCE_ROOT = `${TEXTURE_PROJECT_ROOT}/sources`;

        let activeTextureProjectImport = false;

        function normalizeTextureProjectEntryPath(value) {
            if (typeof value !== 'string') return null;
            const normalized = value
                .replace(/\\/g, '/')
                .replace(/^\/+/, '')
                .replace(/\/+$/, '');
            if (!normalized || normalized.includes('\0')) return null;
            const parts = normalized.split('/');
            if (parts.some((part) => !part || part === '.' || part === '..')) return null;
            return normalized;
        }

        function isTextureProjectInternalPath(path) {
            const normalized = normalizeTextureProjectEntryPath(path);
            if (!normalized) return false;
            const lower = normalized.toLowerCase();
            return lower === TEXTURE_PROJECT_ROOT || lower.startsWith(`${TEXTURE_PROJECT_ROOT}/`);
        }

        function clearTextureProjectImportState() {
            activeTextureProjectImport = false;
        }

        function hasActiveTextureProjectImport() {
            return activeTextureProjectImport;
        }

        function stripTextureProjectFromArchive(zip) {
            if (!zip || !zip.files) return 0;
            let removed = 0;
            for (const filename of Object.keys(zip.files)) {
                if (!isTextureProjectInternalPath(filename)) continue;
                zip.remove(filename);
                removed++;
            }
            return removed;
        }

        function cloneTextureProjectValue(value, fallback) {
            if (value == null) return fallback;
            try {
                return JSON.parse(JSON.stringify(value));
            } catch (_) {
                return fallback;
            }
        }

        function textureProjectFrameFlags(frame) {
            return {
                is2x: !!(frame && frame._is2x),
                isRootLevel: !!(frame && frame._isRootLevel),
                isTransparent1x1: !!(frame && frame._isTransparent1x1),
                isBlankPlaceholder: !!(frame && frame._isBlankPlaceholder),
                keyImageHeightOffset1x: Number(frame && frame._keyImageHeightOffset1x) || 0,
                keyImageHeightPadding1x: Number(frame && frame._keyImageHeightPadding1x) || 0
            };
        }

        function sanitizeTextureProjectSourceName(value, fallback = 'texture') {
            const clean = String(value || '')
                .replace(/\\/g, '/')
                .split('/')
                .pop()
                .replace(/\.(png|jpe?g)$/i, '')
                .replace(/@2x$/i, '')
                .replace(/[^a-z0-9_-]+/gi, '_')
                .replace(/^_+|_+$/g, '')
                .slice(0, 64);
            return clean || fallback;
        }

        function frameFromTextureProjectDescriptor(image, descriptor) {
            const flags = descriptor && descriptor.flags || {};
            const canvas = document.createElement('canvas');
            canvas.width = image.naturalWidth || image.width || 1;
            canvas.height = image.naturalHeight || image.height || 1;
            canvas.getContext('2d').drawImage(image, 0, 0);
            canvas._is2x = !!flags.is2x;
            canvas._isRootLevel = !!flags.isRootLevel;
            canvas._isTransparent1x1 = !!flags.isTransparent1x1;
            canvas._isBlankPlaceholder = !!flags.isBlankPlaceholder;
            canvas._keyImageHeightOffset1x = Number(flags.keyImageHeightOffset1x) || 0;
            canvas._keyImageHeightPadding1x = Number(flags.keyImageHeightPadding1x) || 0;
            return canvas;
        }

        function textureProjectCanvasToBlob(frame) {
            let canvas = frame;
            if (!canvas || typeof canvas.getContext !== 'function') {
                canvas = document.createElement('canvas');
                canvas.width = frame.naturalWidth || frame.width || 1;
                canvas.height = frame.naturalHeight || frame.height || 1;
                canvas.getContext('2d').drawImage(frame, 0, 0);
            }
            if (typeof canvas.convertToBlob === 'function') {
                return canvas.convertToBlob({ type: 'image/png' });
            }
            return new Promise((resolve, reject) => {
                canvas.toBlob((blob) => {
                    if (blob) resolve(blob);
                    else reject(new Error('无法编码贴图工程源图'));
                }, 'image/png');
            });
        }

        async function hashTextureProjectBuffer(arrayBuffer) {
            const subtle = globalThis.crypto && globalThis.crypto.subtle;
            if (subtle && typeof subtle.digest === 'function') {
                const digest = await subtle.digest('SHA-256', arrayBuffer);
                return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
            }
            const bytes = new Uint8Array(arrayBuffer);
            let hash = 2166136261;
            for (let index = 0; index < bytes.length; index++) {
                hash ^= bytes[index];
                hash = Math.imul(hash, 16777619);
            }
            return `${(hash >>> 0).toString(16).padStart(8, '0')}${bytes.length.toString(16)}`;
        }

        async function writeTextureProjectFrame(zip, frame, writeState, options = {}) {
            if (!frame) return null;
            const blob = await textureProjectCanvasToBlob(frame);
            const arrayBuffer = await blob.arrayBuffer();
            const hash = await hashTextureProjectBuffer(arrayBuffer);
            const sourceGroup = String(options.sourceGroup || 'sources')
                .split('/')
                .filter(Boolean)
                .join('/');
            const sourceName = options.sourceName
                ? `${sanitizeTextureProjectSourceName(options.sourceName)}-`
                : '';
            const file = sourceGroup === 'sources'
                ? `${TEXTURE_PROJECT_SOURCE_ROOT}/${hash}.png`
                : `${TEXTURE_PROJECT_ROOT}/${sourceGroup}/${sourceName}${hash}.png`;
            if (!writeState.files.has(file)) {
                zip.file(file, arrayBuffer);
                writeState.files.add(file);
            }
            return {
                file,
                width: frame.naturalWidth || frame.width || 0,
                height: frame.naturalHeight || frame.height || 0,
                flags: textureProjectFrameFlags(frame)
            };
        }

        async function writeTextureProjectFrames(zip, frames, writeState, options = {}) {
            const descriptors = [];
            const sourceFrames = frames || [];
            for (let index = 0; index < sourceFrames.length; index++) {
                const frame = sourceFrames[index];
                const sourceName = typeof options.sourceName === 'function'
                    ? options.sourceName(index)
                    : options.sourceName;
                const descriptor = await writeTextureProjectFrame(zip, frame, writeState, {
                    sourceGroup: options.sourceGroup,
                    sourceName: sourceFrames.length > 1 && sourceName
                        ? `${sourceName}-${index}`
                        : sourceName
                });
                if (descriptor) descriptors.push(descriptor);
            }
            return descriptors;
        }

        function collectTextureProjectOutputFiles(zip, reference) {
            const files = new Set();
            if (!reference) return files;
            const expected = normalizeSkinKey(reference).replace(/@2x$/i, '');
            if (!expected) return files;
            const consider = (filename) => {
                if (!filename || isTextureProjectInternalPath(filename)) return;
                const normalized = normalizeSkinKey(filename)
                    .replace(/@2x$/i, '')
                    .replace(/-\d+$/i, '');
                if (normalized === expected) files.add(String(filename).replace(/\\/g, '/'));
            };
            for (const filename of Object.keys(zip && zip.files || {})) consider(filename);
            if (typeof userReplacedTextures !== 'undefined') {
                for (const filename of userReplacedTextures.keys()) consider(filename);
            }
            return files;
        }

        function textureProjectReferenceIsCreated(reference) {
            if (!reference || typeof hasCreatedTextureParams !== 'function') return false;
            return hasCreatedTextureParams(reference);
        }

        async function captureTextureProjectRecipe(zip, key, recipe, writeState) {
            if (!recipe || !Array.isArray(recipe.sourceFrames) || recipe.sourceFrames.length === 0) {
                return null;
            }
            const libraryMatch = String(key || '').match(/^library\|(.+)$/i);
            const outputReference = normalizeSkinKey(
                recipe.originalReference || (libraryMatch ? libraryMatch[1] : '')
            );
            if (textureProjectReferenceIsCreated(outputReference)) return null;

            const keyImageOriginalSources = {};
            for (const [paramKey, source] of Object.entries(recipe.keyImageOriginalSources || {})) {
                const frames = await writeTextureProjectFrames(zip, source && source.frames, writeState);
                if (frames.length === 0) continue;
                keyImageOriginalSources[paramKey] = {
                    reference: source && source.reference,
                    frames
                };
            }

            return {
                key,
                originalReference: recipe.originalReference || '',
                outputReference,
                outputFiles: Array.from(collectTextureProjectOutputFiles(zip, outputReference)),
                sourceFrames: await writeTextureProjectFrames(zip, recipe.sourceFrames, writeState),
                keyImageOriginalSources,
                params: cloneTextureProjectValue(recipe.params, {})
            };
        }

        function textureProjectLongBodyColumn(sessionKey) {
            const match = String(sessionKey || '').match(/NoteImage(\d+)L$/i);
            return match ? Number(match[1]) : null;
        }

        async function captureTextureProjectLongBody(zip, sessionKey, session, writeState) {
            if (!session || !Array.isArray(session.baseFrames) || session.baseFrames.length === 0) {
                return null;
            }
            const column = textureProjectLongBodyColumn(sessionKey);
            const outputBase = column == null ? '' : `longbody-body_col${column + 1}L`;
            const bodySourceName = session.bodySourceName || outputBase || 'body';
            const tailSourceName = session.tailSourceName || (column == null ? 'tail' : `tail_col${column + 1}`);
            const baseFrames = await writeTextureProjectFrames(zip, session.baseFrames, writeState, {
                sourceGroup: 'longbody/body',
                sourceName: bodySourceName
            });
            const tailFrame = session.tailFrame
                ? await writeTextureProjectFrame(zip, session.tailFrame, writeState, {
                    sourceGroup: 'longbody/tail',
                    sourceName: tailSourceName
                })
                : null;
            const preComposerState = session.preComposerState &&
                Array.isArray(session.preComposerState.workingFrames) &&
                session.preComposerState.workingFrames.length > 0
                ? {
                    workingFrames: await writeTextureProjectFrames(
                        zip,
                        session.preComposerState.workingFrames,
                        writeState
                    ),
                    cropRect: cloneTextureProjectValue(session.preComposerState.cropRect, null),
                    imageTransform: cloneTextureProjectValue(
                        session.preComposerState.imageTransform,
                        null
                    ),
                    rgbAdjustment: cloneTextureProjectValue(
                        session.preComposerState.rgbAdjustment,
                        null
                    )
                }
                : null;
            return {
                sessionKey,
                column,
                outputBase,
                outputFiles: Array.from(collectTextureProjectOutputFiles(zip, outputBase)),
                baseFrames,
                tailFrame,
                preComposerState,
                bodySourceFiles: baseFrames.map((frame) => frame.file),
                tailSourceFile: tailFrame ? tailFrame.file : null,
                bodySourceName: session.bodySourceName || '',
                tailSourceName: session.tailSourceName || '',
                tailRestoreSourceName: session.tailRestoreSourceName || '',
                tailRestoreState: session.tailRestoreState || 'unset',
                tailRestoreExplicit: typeof session.tailRestoreExplicit === 'boolean'
                    ? session.tailRestoreExplicit
                    : null,
                tailSourceExplicit: !!session.tailSourceExplicit,
                appliedScope: session.appliedScope || 'current',
                settings: {
                    targetHeight: Number(session.targetHeight) || 0,
                    coverage: Number(session.coverage) || 0,
                    fade: Number(session.fade) || 0,
                    tailPreset: session.tailPreset || 'none',
                    presetHeight: Number(session.presetHeight) || 0
                }
            };
        }

        async function writeTextureProjectToArchive(zip, options = {}) {
            if (!zip || typeof zip.file !== 'function') {
                throw new Error('缺少用于写入工程数据的皮肤归档');
            }
            stripTextureProjectFromArchive(zip);
            const includeSources = options.includeSources !== false;
            if (!includeSources) {
                return {
                    manifestPath: null,
                    sourceCount: 0,
                    createdCount: 0,
                    recipeCount: 0,
                    longBodyCount: 0
                };
            }

            const writeState = { files: new Set() };
            const createdTextures = [];
            if (typeof createdSkinTextureParams !== 'undefined' && createdSkinTextureParams instanceof Map) {
                for (const [path, params] of createdSkinTextureParams.entries()) {
                    if (!path || !params || isTextureProjectInternalPath(path)) continue;
                    createdTextures.push({
                        path,
                        generatorVersion: 1,
                        params: cloneTextureProjectValue(params, {}),
                        outputFiles: Array.from(collectTextureProjectOutputFiles(zip, path))
                    });
                }
            }

            const editedTextures = [];
            if (typeof textureEditRecipes !== 'undefined' && textureEditRecipes instanceof Map) {
                for (const [key, recipe] of textureEditRecipes.entries()) {
                    const captured = await captureTextureProjectRecipe(zip, key, recipe, writeState);
                    if (captured) editedTextures.push(captured);
                }
            }

            const longBodies = [];
            if (typeof longBodyComposerSessions !== 'undefined' && longBodyComposerSessions instanceof Map) {
                for (const [sessionKey, session] of longBodyComposerSessions.entries()) {
                    const captured = await captureTextureProjectLongBody(zip, sessionKey, session, writeState);
                    if (captured) longBodies.push(captured);
                }
            }

            const manifest = {
                format: TEXTURE_PROJECT_FORMAT,
                version: TEXTURE_PROJECT_VERSION,
                createdAt: new Date().toISOString(),
                createdTextures,
                editedTextures,
                longBodies
            };
            zip.file(TEXTURE_PROJECT_MANIFEST_PATH, JSON.stringify(manifest, null, 2));
            return {
                manifestPath: TEXTURE_PROJECT_MANIFEST_PATH,
                sourceCount: writeState.files.size,
                createdCount: createdTextures.length,
                recipeCount: editedTextures.length,
                longBodyCount: longBodies.length
            };
        }

        function findTextureProjectManifestEntry(zip) {
            if (!zip || !zip.files) return null;
            const expected = TEXTURE_PROJECT_MANIFEST_PATH.toLowerCase();
            const filename = Object.keys(zip.files).find(
                (name) => name.replace(/\\/g, '/').toLowerCase() === expected
            );
            return filename ? zip.files[filename] : null;
        }

        function parseTextureProjectManifest(manifest) {
            if (!manifest || manifest.format !== TEXTURE_PROJECT_FORMAT) return null;
            if (!Number.isInteger(manifest.version) || manifest.version < 1) return null;
            if (manifest.version > TEXTURE_PROJECT_VERSION) return null;
            return manifest;
        }

        async function readTextureProjectFrame(zip, descriptor, cache) {
            if (!descriptor) return null;
            const file = normalizeTextureProjectEntryPath(descriptor.file);
            if (!file || !isTextureProjectInternalPath(file)) return null;
            if (cache.has(file)) return cache.get(file);
            const promise = (async () => {
                const entry = zip.file(file) || zip.file(file.toLowerCase());
                if (!entry) return null;
                const arrayBuffer = await entry.async('arraybuffer');
                const blob = new Blob([arrayBuffer], { type: 'image/png' });
                const url = URL.createObjectURL(blob);
                try {
                    const image = await new Promise((resolve, reject) => {
                        const img = new Image();
                        img.onload = () => resolve(img);
                        img.onerror = () => reject(new Error(`无法读取工程源图: ${file}`));
                        img.src = url;
                    });
                    return frameFromTextureProjectDescriptor(image, descriptor);
                } finally {
                    URL.revokeObjectURL(url);
                }
            })();
            cache.set(file, promise);
            return promise;
        }

        async function readTextureProjectFrames(zip, descriptors, cache) {
            const frames = [];
            for (const descriptor of descriptors || []) {
                const frame = await readTextureProjectFrame(zip, descriptor, cache);
                if (frame) frames.push(frame);
            }
            return frames;
        }

        function resolveTextureProjectFrames(reference) {
            if (!reference || typeof getSkinAnimationFramesFromStore !== 'function') return [];
            const key = normalizeSkinKey(reference).replace(/@2x$/i, '');
            const candidates = [key];
            const base = key.split('/').pop();
            if (base && base !== key) candidates.push(base);
            const stores = [skinImageStore, skinFallbackImageStore];
            for (const candidate of candidates) {
                for (const store of stores) {
                    const frames = getSkinAnimationFramesFromStore(store, candidate, true);
                    if (frames && frames.length > 0) return frames;
                }
            }
            return [];
        }

        function resolveTextureProjectRecipeOutputFrames(record) {
            const direct = resolveTextureProjectFrames(record && record.outputReference);
            if (direct.length > 0) return direct;
            const match = String(record && record.key || '').match(/^(\d+)\|(.+)$/);
            if (!match || typeof getTextureTabParams !== 'function' || typeof buildEditorTarget !== 'function') {
                return [];
            }
            const paramKey = match[2];
            const param = getTextureTabParams().find((item) => item.key === paramKey);
            const target = param ? buildEditorTarget(param) : null;
            return target && target.frames ? target.frames.slice() : [];
        }

        async function restoreTextureProjectCreated(zip, manifest, cache) {
            const restored = [];
            for (const record of manifest.createdTextures || []) {
                const path = normalizeTextureProjectEntryPath(record && record.path);
                if (!path || !record.params) continue;
                const key = normalizeSkinKey(path);
                createdSkinTextureParams.set(key, {
                    ...cloneTextureProjectValue(record.params, {}),
                    name: path
                });
                restored.push(key);
            }
            return restored;
        }

        async function restoreTextureProjectRecipes(zip, manifest, cache) {
            const restored = [];
            for (const record of manifest.editedTextures || []) {
                const key = String(record && record.key || '');
                if (!key || !record.params) continue;
                const sourceFrames = await readTextureProjectFrames(zip, record.sourceFrames, cache);
                if (sourceFrames.length === 0) continue;
                const keyImageOriginalSources = {};
                for (const [paramKey, source] of Object.entries(record.keyImageOriginalSources || {})) {
                    const frames = await readTextureProjectFrames(zip, source && source.frames, cache);
                    if (frames.length === 0) continue;
                    keyImageOriginalSources[paramKey] = {
                        reference: source && source.reference,
                        frames
                    };
                }
                const outputFrames = resolveTextureProjectRecipeOutputFrames(record);
                if (outputFrames.length === 0) continue;
                textureEditRecipes.set(key, {
                    sourceFrames,
                    originalReference: normalizeSkinKey(record.originalReference || record.outputReference || ''),
                    keyImageOriginalSources,
                    params: cloneTextureProjectValue(record.params, {}),
                    outputFrames
                });
                restored.push(key);
            }
            return restored;
        }

        async function restoreTextureProjectLongBodies(zip, manifest, cache) {
            const restored = [];
            for (const record of manifest.longBodies || []) {
                const sessionKey = String(record && record.sessionKey || '');
                if (!sessionKey) continue;
                const baseFrames = await readTextureProjectFrames(zip, record.baseFrames, cache);
                if (baseFrames.length === 0) continue;
                const tailFrame = await readTextureProjectFrame(zip, record.tailFrame, cache);
                const preComposerRecord = record.preComposerState || null;
                const preComposerFrames = preComposerRecord
                    ? await readTextureProjectFrames(
                        zip,
                        preComposerRecord.workingFrames,
                        cache
                    )
                    : [];
                const settings = record.settings || {};
                longBodyComposerSessions.set(sessionKey, {
                    baseFrames,
                    preComposerState: preComposerFrames.length > 0
                        ? {
                            workingFrames: preComposerFrames,
                            cropRect: cloneTextureProjectValue(
                                preComposerRecord.cropRect,
                                null
                            ),
                            imageTransform: cloneTextureProjectValue(
                                preComposerRecord.imageTransform,
                                null
                            ),
                            rgbAdjustment: cloneTextureProjectValue(
                                preComposerRecord.rgbAdjustment,
                                null
                            )
                        }
                        : null,
                    tailFrame,
                    preserveImportedOutput: true,
                    bodySourceName: record.bodySourceName || '',
                    tailSourceName: record.tailSourceName || '',
                    tailRestoreSourceName: record.tailRestoreSourceName || '',
                    tailRestoreState: record.tailRestoreState || 'unset',
                    tailRestoreExplicit: typeof record.tailRestoreExplicit === 'boolean'
                        ? record.tailRestoreExplicit
                        : null,
                    tailSourceExplicit: !!record.tailSourceExplicit,
                    appliedScope: record.appliedScope || 'current',
                    targetHeight: Number(settings.targetHeight) || LONG_BODY_DEFAULT_HEIGHT,
                    coverage: Number(settings.coverage) || 0,
                    fade: Number(settings.fade) || 0,
                    tailPreset: settings.tailPreset || 'none',
                    presetHeight: Number(settings.presetHeight) || 0
                });
                restored.push(sessionKey);
            }
            return restored;
        }

        async function readTextureProjectFromArchive(zip) {
            activeTextureProjectImport = false;
            const manifestEntry = findTextureProjectManifestEntry(zip);
            if (!manifestEntry) return null;
            try {
                const manifest = parseTextureProjectManifest(
                    JSON.parse(await manifestEntry.async('string'))
                );
                if (!manifest) return null;
                const cache = new Map();
                const created = await restoreTextureProjectCreated(zip, manifest, cache);
                const recipes = await restoreTextureProjectRecipes(zip, manifest, cache);
                const longBodies = await restoreTextureProjectLongBodies(zip, manifest, cache);
                activeTextureProjectImport = true;
                return {
                    version: manifest.version,
                    createdCount: created.length,
                    recipeCount: recipes.length,
                    longBodyCount: longBodies.length,
                    sourceCount: cache.size
                };
            } catch (error) {
                console.warn('读取贴图工程数据失败，已按普通皮肤导入:', error);
                return null;
            }
        }
// --- END ui/texture-project-archive.js ---

// --- BEGIN ui/skin-workspace-revision.js ---
// ============================================================================
// skin-workspace-revision.js - 当前皮肤状态与最近一次成功导出是否一致
// 依赖：无。由历史记录、导出和便携版退出提示调用。
// ============================================================================

        (function initSkinWorkspaceRevision() {
            let nextRevisionId = 1;
            let currentRevisionId = 0;
            let exportedRevisionId = 0;

            function reset() {
                nextRevisionId = 1;
                currentRevisionId = 0;
                exportedRevisionId = 0;
            }

            function advance() {
                currentRevisionId = nextRevisionId;
                nextRevisionId += 1;
                return currentRevisionId;
            }

            function adopt(snapshot) {
                if (!snapshot || !Number.isInteger(snapshot.revisionId)) return currentRevisionId;
                currentRevisionId = snapshot.revisionId;
                if (nextRevisionId <= currentRevisionId) nextRevisionId = currentRevisionId + 1;
                return currentRevisionId;
            }

            function markExported() {
                exportedRevisionId = currentRevisionId;
                return exportedRevisionId;
            }

            function hasUnexportedOperations() {
                return currentRevisionId !== exportedRevisionId;
            }

            window.skinWorkspaceRevision = Object.freeze({
                reset,
                advance,
                adopt,
                markExported,
                hasUnexportedOperations,
                currentId: () => currentRevisionId,
                exportedId: () => exportedRevisionId
            });
        })();
// --- END ui/skin-workspace-revision.js ---

// --- BEGIN ui/export.js ---
// ============================================================================
// export.js - 皮肤替换上传入口与 .osk / 文件夹导出
// 依赖：parser/skin-assets.js、ui/ini-export.js、ui/texture-project-archive.js
// ============================================================================

        let preferredTextureUploadSpec = null;

        function normalizeTextureExportMode(mode) {
            return mode === 'release' ? 'release' : 'editable';
        }

        function normalizeSkinArchivePathKey(path) {
            return String(path || '')
                .replace(/\\/g, '/')
                .replace(/^\/+/, '')
                .toLowerCase();
        }

        function isHighResolutionSkinArchivePath(path) {
            return /@2x(?:\.[^./\\]+)?$/i.test(String(path || '').replace(/\\/g, '/'));
        }

        function getSkinArchivePathVariants(zip, targetPath) {
            if (!zip || !zip.files) return [];
            const targetKey = normalizeSkinArchivePathKey(targetPath);
            if (!targetKey) return [];
            return Object.keys(zip.files).filter((filename) =>
                !zip.files[filename].dir &&
                normalizeSkinArchivePathKey(filename) === targetKey
            );
        }

        function resolveSkinArchiveWritePath(zip, requestedPath) {
            const variants = getSkinArchivePathVariants(zip, requestedPath);
            if (variants.length === 0) return requestedPath;
            if (variants.includes(requestedPath)) return requestedPath;
            if (variants.length === 1) return variants[0];
            throw new Error(`导出路径存在无法确定的大小写冲突: ${variants.join(' / ')}`);
        }

        function removeSkinArchivePathVariants(zip, targetPath) {
            if (!zip || !zip.files) return;
            for (const filename of getSkinArchivePathVariants(zip, targetPath)) {
                zip.remove(filename);
            }
        }

        function assertUniqueSkinArchivePaths(zip) {
            if (!zip || !zip.files) return;
            const namesByPath = new Map();
            for (const filename of Object.keys(zip.files)) {
                if (zip.files[filename].dir) continue;
                const pathKey = normalizeSkinArchivePathKey(filename);
                if (!pathKey) continue;
                if (!namesByPath.has(pathKey)) namesByPath.set(pathKey, []);
                namesByPath.get(pathKey).push(filename);
            }

            const conflicts = Array.from(namesByPath.values()).filter((names) => names.length > 1);
            if (conflicts.length > 0) {
                const details = conflicts
                    .slice(0, 5)
                    .map((names) => names.join(' / '))
                    .join('；');
                const remaining = conflicts.length > 5 ? `；另有 ${conflicts.length - 5} 组` : '';
                throw new Error(`导出失败：皮肤包仍存在大小写冲突路径: ${details}${remaining}`);
            }
        }

        function requestTextureExportMode(format = 'osk') {
            const modal = document.getElementById('textureExportModeModal');
            if (!modal) return Promise.resolve('editable');
            const dialog = document.getElementById('textureExportModeDialog');
            const editableBtn = document.getElementById('textureExportEditableBtn');
            const releaseBtn = document.getElementById('textureExportReleaseBtn');
            const cancelBtn = document.getElementById('textureExportModeCancelBtn');
            const backdrop = document.getElementById('textureExportModeBackdrop');

            return new Promise((resolve) => {
                const finish = (mode) => {
                    modal.style.display = 'none';
                    if (editableBtn) editableBtn.onclick = null;
                    if (releaseBtn) releaseBtn.onclick = null;
                    if (cancelBtn) cancelBtn.onclick = null;
                    if (backdrop) backdrop.onclick = null;
                    window.removeEventListener('keydown', onKeyDown, true);
                    resolve(mode);
                };
                const onKeyDown = (event) => {
                    if (event.key !== 'Escape') return;
                    event.preventDefault();
                    event.stopPropagation();
                    finish(null);
                };
                if (editableBtn) editableBtn.onclick = () => finish('editable');
                if (releaseBtn) releaseBtn.onclick = () => finish('release');
                if (cancelBtn) cancelBtn.onclick = () => finish(null);
                if (backdrop) backdrop.onclick = () => finish(null);
                window.addEventListener('keydown', onKeyDown, true);
                modal.style.display = 'flex';
                if (editableBtn) editableBtn.focus();
                if (dialog) dialog.scrollTop = 0;
            });
        }

        async function requestAndExportSkin(format = 'osk') {
            const mode = await requestTextureExportMode(format);
            if (!mode) return false;
            return exportSkin(format, { mode });
        }

        // 10. 触发本地图片替换
        // 详细设置入口会传入已选择的 '1x' / '2x'，选完本地文件后直接导入；
        // 画布入口不传规格，继续通过弹窗询问导入类型。
        function triggerTextureUpload(textureName, textureKey = null, paramKey = null, colIndex = null, preferredSpec = null) {
            targetTextureUploadKey = textureKey;
            targetTextureUploadFilename = textureName;
            targetTextureUploadParamKey = paramKey;
            targetTextureUploadColIndex = colIndex;
            preferredTextureUploadSpec = preferredSpec;
            const input = document.getElementById('textureReplaceInput');
            if (input) {
                input.value = '';
                input.click();
            }
        }

        // 11. 构建最新完整皮肤包，供普通导出和 Agent 导出共用
        async function buildSkinArchiveBlob(format = 'osk', options = {}) {
            const mode = normalizeTextureExportMode(
                typeof options === 'string' ? options : options.mode
            );
            let zip = currentSkinZip ? currentSkinZip : new JSZip();
            // 音效替换通过虚拟覆盖层参与导出；先复制 ZIP，避免移除低优先级
            // 原始音效变体时破坏内存中的导入资源，保证导出后仍可撤回。
            if (skinHitsoundReplacements.size > 0 &&
                typeof createSkinHitsoundExportArchive === 'function') {
                zip = await createSkinHitsoundExportArchive(zip);
            }
            stripUnsafeSkinArchiveEntries(zip);
            stripTextureProjectFromArchive(zip);
            if (deletedSkinTexturePaths.size > 0) {
                for (const filename of Object.keys(zip.files)) {
                    if (deletedSkinTexturePaths.has(filename.replace(/\\/g, '/').toLowerCase())) {
                        zip.remove(filename);
                    }
                }
            }

            // 1. 以当前编辑结果为底，再按原顺序补回生成结果里没有的原参数（含其他模式）
            const newIniText = buildExportedSkinIniText();
            let iniFilename = 'skin.ini';
            for (const filename of Object.keys(zip.files)) {
                if (filename.toLowerCase().endsWith('skin.ini')) {
                    iniFilename = filename;
                    break;
                }
            }
            zip.file(iniFilename, newIniText);

            // 2. 将所有用户上传替换的贴图写入压缩包。
            // 同一逻辑路径可能因大小写不同在内存 Map 中出现两次，先按 ZIP 路径规则合并。
            const replacementEntriesByPath = new Map();
            for (const [texPath, texData] of userReplacedTextures.entries()) {
                const pathKey = normalizeSkinArchivePathKey(texPath);
                if (!pathKey) continue;
                replacementEntriesByPath.set(pathKey, [texPath, texData]);
            }
            // 已有贴图沿用 ZIP 中的原始拼写；只有全新贴图才使用编辑器请求的路径。
            const replacementEntries = Array.from(replacementEntriesByPath.values()).map(([texPath, texData]) => ({
                writePath: resolveSkinArchiveWritePath(zip, texPath),
                texData
            }));
            const replacementPathKeys = new Set(replacementEntriesByPath.keys());

            // 删除旧条目时必须删除所有大小写变体，再按保留下来的原始路径写入一次。
            for (const entry of replacementEntries) {
                removeSkinArchivePathVariants(zip, entry.writePath);
            }

            // 若替换的是 1x 普通贴图且没有对应的 2x 替换，移除旧 @2x，防止游戏优先读取旧高清贴图。
            for (const entry of replacementEntries) {
                if (isHighResolutionSkinArchivePath(entry.writePath) || !/\.png$/i.test(entry.writePath)) continue;
                const baseName = entry.writePath.replace(/\.png$/i, '');
                const old2xName = `${baseName}@2x.png`;
                if (!replacementPathKeys.has(normalizeSkinArchivePathKey(old2xName))) {
                    removeSkinArchivePathVariants(zip, old2xName);
                }
            }

            for (const entry of replacementEntries) {
                zip.file(entry.writePath, entry.texData);
            }

            // 3. 开始执行异步压缩
            const projectSummary = mode === 'editable'
                ? await writeTextureProjectToArchive(zip, { includeSources: true })
                : null;

            // 最后只做唯一性校验；若仍有冲突，说明导出链路遗漏了修正，不能静默选择其中一张。
            assertUniqueSkinArchivePaths(zip);

            const blob = await zip.generateAsync({
                type: 'blob',
                compression: 'DEFLATE',
                compressionOptions: { level: 6 }
            }, (meta) => {
                updateProgress(Math.round(meta.percent), 100, `正在压缩资源 (${Math.round(meta.percent)}%)...`);
            });

            const rawName = (currentSkinMetadata.general && currentSkinMetadata.general.Name) || currentSkinFileName || 'Mania_Custom_Skin';
            const cleanName = rawName.replace(/\.(osk|zip)$/i, '').replace(/[\\/:*?"<>|]/g, '_');
            const suffix = mode === 'editable' ? '_editable' : '_release';
            const exportFileName = `${cleanName}${suffix}.${format}`;
            return { blob, exportFileName, mode, format, projectSummary };
        }

        // 12. 导出更新后的完整皮肤包 (.osk 或 .zip)
        async function exportSkin(format = 'osk', options = {}) {
            const mode = normalizeTextureExportMode(
                typeof options === 'string' ? options : options.mode
            );
            const modeLabel = mode === 'editable' ? '可继续编辑' : '仅发布';
            showProgress(`正在打包生成 ${format.toUpperCase()} 皮肤文件（${modeLabel}）...`);
            try {
                const { blob, exportFileName, projectSummary } = await buildSkinArchiveBlob(format, { mode });
                const downloadUrl = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = downloadUrl;
                a.download = exportFileName;
                document.body.appendChild(a);
                const pendingDownload = window.skinEditorDesktop &&
                    typeof window.skinEditorDesktop.waitForNextDownload === 'function'
                    ? window.skinEditorDesktop.waitForNextDownload()
                    : null;
                try {
                    a.click();
                } catch (downloadError) {
                    if (pendingDownload) pendingDownload.cancel();
                    throw downloadError;
                }
                document.body.removeChild(a);
                const downloadState = pendingDownload ? await pendingDownload.promise : 'completed';
                setTimeout(() => URL.revokeObjectURL(downloadUrl), 8000);

                hideProgress();
                if (downloadState !== 'completed') {
                    showToast('导出已取消', '文件没有保存，当前操作仍未导出。');
                    return false;
                }
                if (window.skinWorkspaceRevision) window.skinWorkspaceRevision.markExported();
                const projectDetail = projectSummary
                    ? `，工程源图 ${projectSummary.sourceCount} 张`
                    : '，不含工程编辑数据';
                showToast('导出皮肤成功', `已下载生成文件: ${exportFileName}${projectDetail}`);
                return true;
            } catch (err) {
                hideProgress();
                console.error('导出皮肤异常', err);
                showToast('导出失败', err.message || '未知错误');
                return false;
            }
        }
// --- END ui/export.js ---

// --- BEGIN ui/history.js ---
// ============================================================================
// history.js - 皮肤快照、撤销、重做与初始状态复原
// 依赖：parser/skin-assets.js、ui/param-core.js
// ============================================================================

        // ===== 皮肤快照与复原系统 (Skin Snapshot & Restore System) =====
        function cloneSkinAssetEntry(entry) {
            if (!entry) return null;
            return {
                anim2x: Array.isArray(entry.anim2x) ? [...entry.anim2x] : [],
                anim1x: Array.isArray(entry.anim1x) ? [...entry.anim1x] : [],
                static2x: entry.static2x,
                static1x: entry.static1x
            };
        }

        function cloneSkinImageStore(store) {
            const cloned = new Map();
            if (!store) return cloned;
            for (const [key, entry] of store.entries()) {
                cloned.set(key, cloneSkinAssetEntry(entry));
            }
            return cloned;
        }

        function cloneManiaSkinConfig(cfg) {
            if (!cfg) return null;
            const cloned = { ...cfg };
            if (cfg.ImageLookups instanceof Map) {
                cloned.ImageLookups = new Map(cfg.ImageLookups);
            }
            if (cfg.FlipSettings instanceof Map) {
                cloned.FlipSettings = new Map(cfg.FlipSettings);
            }
            if (Array.isArray(cfg.ColumnLineWidth)) cloned.ColumnLineWidth = [...cfg.ColumnLineWidth];
            if (Array.isArray(cfg.ColumnSpacing)) cloned.ColumnSpacing = [...cfg.ColumnSpacing];
            if (Array.isArray(cfg.ColumnWidth)) cloned.ColumnWidth = [...cfg.ColumnWidth];
            if (Array.isArray(cfg.ExplosionWidth)) cloned.ExplosionWidth = [...cfg.ExplosionWidth];
            if (Array.isArray(cfg.HoldNoteLightWidth)) cloned.HoldNoteLightWidth = [...cfg.HoldNoteLightWidth];
            if (Array.isArray(cfg.NoteBodyStyles)) cloned.NoteBodyStyles = [...cfg.NoteBodyStyles];
            if (Array.isArray(cfg.ColumnColour)) cloned.ColumnColour = cfg.ColumnColour.map(c => (c ? { ...c } : c));
            if (Array.isArray(cfg.ColourLight)) cloned.ColourLight = cfg.ColourLight.map(c => (c ? { ...c } : c));
            if (cfg.CustomColours) {
                try {
                    cloned.CustomColours = JSON.parse(JSON.stringify(cfg.CustomColours));
                } catch (_) {
                    cloned.CustomColours = { ...cfg.CustomColours };
                }
            }
            if (cfg.ComboBreakColour) cloned.ComboBreakColour = { ...cfg.ComboBreakColour };
            if (cfg.ColourHold) cloned.ColourHold = { ...cfg.ColourHold };
            if (cfg.ColourBarline) cloned.ColourBarline = { ...cfg.ColourBarline };
            if (cfg.GlobalColourLight) cloned.GlobalColourLight = { ...cfg.GlobalColourLight };
            return cloned;
        }

        function copyNonTextureManiaProperties(sourceCfg, targetCfg) {
            if (!sourceCfg || !targetCfg) return;
            const nonTextureKeys = [
                'Keys', 'SkinVersion', 'WidthForNoteHeightScale',
                'ColumnLineWidth', 'ColumnSpacing', 'ColumnWidth',
                'ColumnStart', 'ColumnRight',
                'HitPosition', 'LightPosition', 'ScorePosition', 'ComboPosition',
                'BarLineHeight', 'ShowJudgementLine', 'JudgementLine',
                'KeysUnderNotes', 'LightFramePerSecond',
                'ExplosionWidth', 'HoldNoteLightWidth',
                'ColumnColour', 'ColourLight', 'GlobalColourLight',
                'ColourHold', 'ColourBarline', 'ComboBreakColour', 'CustomColours',
                'FlipSettings', 'FontCombo', 'ComboOverlap', 'FontScore', 'ScoreOverlap',
                'UpsideDown', 'SplitStages', 'StageSeparation',
                'SpecialStyle',
                '_isDefaultFallback'
            ];
            if (typeof SKIN_INI_PARAM_SCHEMA_MANIA !== 'undefined' && Array.isArray(SKIN_INI_PARAM_SCHEMA_MANIA)) {
                for (const p of SKIN_INI_PARAM_SCHEMA_MANIA) {
                    if (p && p.key && !nonTextureKeys.includes(p.key)) {
                        nonTextureKeys.push(p.key);
                    }
                }
            }
            for (const key of nonTextureKeys) {
                if (key in sourceCfg) {
                    const val = sourceCfg[key];
                    if (Array.isArray(val)) {
                        targetCfg[key] = val.map(item => (item && typeof item === 'object') ? { ...item } : item);
                    } else if (val instanceof Map) {
                        targetCfg[key] = new Map(val);
                    } else if (val && typeof val === 'object') {
                        try {
                            targetCfg[key] = JSON.parse(JSON.stringify(val));
                        } catch (_) {
                            targetCfg[key] = { ...val };
                        }
                    } else {
                        targetCfg[key] = val;
                    }
                }
            }
        }

        function cloneManiaSkinConfigs(map) {
            const newMap = new Map();
            if (!map) return newMap;
            for (const [k, v] of map.entries()) {
                newMap.set(k, cloneManiaSkinConfig(v));
            }
            return newMap;
        }

        const undoStack = [];
        const redoStack = [];
        const MAX_UNDO_STACK = 40;
        let isPerformingUndoRedo = false;
        let continuousActionActive = false;
        let continuousActionTimer = null;

        function updateUndoButtonState() {
            const redoBtn = document.getElementById('canvasRedoBtn');
            const undoBtn = document.getElementById('canvasUndoBtn');
            const modalUndoBtn = document.getElementById('modalUndoBtn');
            const count = undoStack.length;
            const redoCount = redoStack.length;
            const redoDesc = window.I18n.t(redoStack[redoStack.length - 1]?.desc || '已撤回的操作');
            const undoDesc = window.I18n.t(undoStack[undoStack.length - 1]?.desc || '上一步操作');
            const redoTitle = redoCount > 0
                ? window.I18n.t('重做: {desc} (Ctrl+Y / Ctrl+Shift+Z)', { desc: redoDesc })
                : '暂无可重做的操作 (Ctrl+Y / Ctrl+Shift+Z)';
            const title = count > 0
                ? window.I18n.t('撤回: {desc} (Ctrl+Z)', { desc: undoDesc })
                : '暂无可撤回操作 (Ctrl+Z)';

            if (redoBtn) {
                redoBtn.disabled = (redoCount === 0);
                redoBtn.style.opacity = (redoCount === 0) ? '0.45' : '1';
                redoBtn.style.cursor = (redoCount === 0) ? 'not-allowed' : 'pointer';
                redoBtn.title = redoTitle;
            }
            if (undoBtn) {
                undoBtn.disabled = (count === 0);
                undoBtn.style.opacity = (count === 0) ? '0.45' : '1';
                undoBtn.style.cursor = (count === 0) ? 'not-allowed' : 'pointer';
                undoBtn.title = title;
            }
            if (modalUndoBtn) {
                modalUndoBtn.disabled = (count === 0);
                modalUndoBtn.style.opacity = (count === 0) ? '0.45' : '1';
                modalUndoBtn.style.cursor = (count === 0) ? 'not-allowed' : 'pointer';
                modalUndoBtn.title = title;
            }
            const textureEditorModal = document.getElementById('textureImageEditorModal');
            if (textureEditorModal && textureEditorModal.classList.contains('active') &&
                typeof updateEditorHistoryButtons === 'function') {
                updateEditorHistoryButtons();
            }
        }

        function cloneLongBodyComposerSessionForHistory(session) {
            if (!session) return null;
            return {
                baseFrames: (session.baseFrames || []).map((frame) => cloneFrame(frame)),
                preComposerState: cloneLongBodyPreComposerState(session.preComposerState),
                tailFrame: session.tailFrame ? cloneFrame(session.tailFrame) : null,
                bodySourceName: session.bodySourceName || '',
                tailSourceName: session.tailSourceName || '',
                tailRestoreSourceName: session.tailRestoreSourceName || '',
                tailRestoreState: session.tailRestoreState || 'unset',
                tailRestoreExplicit: typeof session.tailRestoreExplicit === 'boolean'
                    ? session.tailRestoreExplicit
                    : null,
                tailSourceExplicit: !!session.tailSourceExplicit,
                appliedScope: session.appliedScope || 'current',
                targetHeight: Number(session.targetHeight) || 0,
                coverage: Number(session.coverage) || 0,
                fade: Number(session.fade) || 0,
                tailPreset: session.tailPreset || 'none',
                presetHeight: Number(session.presetHeight) || 0,
                preserveImportedOutput: !!session.preserveImportedOutput
            };
        }

        function cloneLongBodyComposerSessionsForHistory() {
            if (typeof longBodyComposerSessions === 'undefined' ||
                !(longBodyComposerSessions instanceof Map)) {
                return null;
            }
            return new Map(Array.from(longBodyComposerSessions.entries(), ([key, session]) => [
                key,
                cloneLongBodyComposerSessionForHistory(session)
            ]));
        }

        function createSkinSnapshot(desc = '操作') {
            return {
                desc,
                timestamp: Date.now(),
                maniaSkinConfigurations: cloneManiaSkinConfigs(maniaSkinConfigurations),
                currentSkinMetadata: JSON.parse(JSON.stringify(currentSkinMetadata)),
                skinFontsConfig: { ...skinFontsConfig },
                globalSkinImageLookups: new Map(globalSkinImageLookups),
                skinImageStore: cloneSkinImageStore(skinImageStore),
                skinFallbackImageStore: cloneSkinImageStore(skinFallbackImageStore),
                skinHitsoundReplacements: typeof cloneSkinHitsoundReplacements === 'function'
                    ? cloneSkinHitsoundReplacements()
                    : new Map(),
                userReplacedTextures: new Map(userReplacedTextures),
                deletedSkinTexturePaths: new Set(deletedSkinTexturePaths),
                createdSkinTextureParams: new Map(Array.from(createdSkinTextureParams.entries(), ([k, v]) => [k, { ...v }])),
                textureEditRecipes: (typeof textureEditRecipes !== 'undefined' && textureEditRecipes instanceof Map)
                    ? new Map(Array.from(textureEditRecipes.entries(), ([k, v]) => [k, {
                        sourceFrames: (v.sourceFrames || []).map((f) => cloneFrame(f)),
                        originalReference: v.originalReference,
                        keyImageOriginalSources: typeof cloneKeyImageEditSources === 'function'
                            ? cloneKeyImageEditSources(v.keyImageOriginalSources)
                            : {},
                        params: v.params ? {
                            ...v.params,
                            imageTransform: typeof cloneImageTransform === 'function'
                                ? cloneImageTransform(v.params.imageTransform)
                                : (v.params.imageTransform ? { ...v.params.imageTransform } : null),
                            rgbAdjustment: typeof cloneRgbAdjustment === 'function'
                                ? cloneRgbAdjustment(v.params.rgbAdjustment)
                                : (v.params.rgbAdjustment ? { ...v.params.rgbAdjustment } : null)
                        } : null,
                        outputFrames: (v.outputFrames || []).map((f) => cloneFrame(f))
                    }]))
                    : null,
                longBodyComposerSessions: cloneLongBodyComposerSessionsForHistory(),
                activeEditorKeyCount: activeEditorKeyCount,
                revisionId: window.skinWorkspaceRevision
                    ? window.skinWorkspaceRevision.currentId()
                    : 0
            };
        }

        function recordSkinUndoBeforeChange(desc = '修改参数', options = {}) {
            if (isPerformingUndoRedo) return;
            // Agent 批次在开始前已经记录过一次完整快照。批次内部的贴图、
            // 参数和联动修改继续走原有写入路径，但不再拆成多条撤回记录。
            if (window.skinAgentSession &&
                typeof window.skinAgentSession.isApplying === 'function' &&
                window.skinAgentSession.isApplying()) {
                return;
            }
            if (typeof invalidateKeyImageHeightPersistence === 'function') {
                invalidateKeyImageHeightPersistence();
            }
            if (options.force || !continuousActionActive) {
                const snap = createSkinSnapshot(desc);
                undoStack.push(snap);
                if (undoStack.length > MAX_UNDO_STACK) undoStack.shift();
                redoStack.length = 0;
                if (window.skinWorkspaceRevision) window.skinWorkspaceRevision.advance();
                continuousActionActive = true;
                updateUndoButtonState();
                if (window.skinAgentSession &&
                    typeof window.skinAgentSession.notifyExternalMutation === 'function') {
                    window.skinAgentSession.notifyExternalMutation(desc);
                }
            }
            syncTextureEditorNonTextureSettings();
            if (continuousActionTimer) clearTimeout(continuousActionTimer);
            continuousActionTimer = setTimeout(() => {
                continuousActionActive = false;
            }, 600);
        }

        function syncTextureEditorNonTextureSettings() {
            const modal = document.getElementById('textureImageEditorModal');
            if (!modal || (!modal.classList.contains('active') && modal.style.display === 'none')) {
                return;
            }
            if (typeof syncTextureEditorSnapshotsWithCurrentManiaConfigs === 'function') {
                syncTextureEditorSnapshotsWithCurrentManiaConfigs();
            }
        }

        function applySkinSnapshot(snap, options = {}) {
            if (!snap) return;
            if (typeof invalidateKeyImageHeightPersistence === 'function') {
                invalidateKeyImageHeightPersistence();
            }
            const preserveNonTexture = !!options.preserveNonTextureSettings;
            const currentNonTextureConfigs = preserveNonTexture
                ? cloneManiaSkinConfigs(maniaSkinConfigurations)
                : null;
            const hitsoundReplacementsChanged = !preserveNonTexture &&
                typeof areSkinHitsoundReplacementsEqual === 'function' &&
                !areSkinHitsoundReplacementsEqual(
                    skinHitsoundReplacements,
                    snap.skinHitsoundReplacements
                );
            isPerformingUndoRedo = true;
            try {
                // 0. 还原皮肤音效覆盖层，再重建当前生效的音效目录
                if (hitsoundReplacementsChanged) {
                    if (typeof restoreSkinHitsoundReplacements === 'function') {
                        restoreSkinHitsoundReplacements(snap.skinHitsoundReplacements);
                    }
                    if (typeof refreshSkinHitsoundCatalogWithReplacements === 'function') {
                        refreshSkinHitsoundCatalogWithReplacements();
                    }
                }

                // 1. 还原 userReplacedTextures
                userReplacedTextures.clear();
                if (snap.userReplacedTextures) {
                    for (const [k, v] of snap.userReplacedTextures.entries()) {
                        userReplacedTextures.set(k, v);
                    }
                }
                deletedSkinTexturePaths.clear();
                if (snap.deletedSkinTexturePaths) {
                    for (const name of snap.deletedSkinTexturePaths) {
                        deletedSkinTexturePaths.add(name);
                    }
                }
                createdSkinTextureParams.clear();
                if (snap.createdSkinTextureParams) {
                    for (const [k, v] of snap.createdSkinTextureParams.entries()) {
                        createdSkinTextureParams.set(k, { ...v });
                    }
                }
                if (typeof textureEditRecipes !== 'undefined' && textureEditRecipes instanceof Map) {
                    textureEditRecipes.clear();
                    if (snap.textureEditRecipes) {
                        for (const [k, v] of snap.textureEditRecipes.entries()) {
                            textureEditRecipes.set(k, {
                                sourceFrames: (v.sourceFrames || []).map((f) => cloneFrame(f)),
                                originalReference: v.originalReference,
                                keyImageOriginalSources: typeof cloneKeyImageEditSources === 'function'
                                    ? cloneKeyImageEditSources(v.keyImageOriginalSources)
                                    : {},
                                params: v.params ? {
                                    ...v.params,
                                    imageTransform: typeof cloneImageTransform === 'function'
                                        ? cloneImageTransform(v.params.imageTransform)
                                        : (v.params.imageTransform ? { ...v.params.imageTransform } : null),
                                    rgbAdjustment: typeof cloneRgbAdjustment === 'function'
                                        ? cloneRgbAdjustment(v.params.rgbAdjustment)
                                        : (v.params.rgbAdjustment ? { ...v.params.rgbAdjustment } : null)
                                } : null,
                                outputFrames: (v.outputFrames || []).map((f) => cloneFrame(f))
                            });
                        }
                    }
                }
                if (typeof longBodyComposerSessions !== 'undefined' &&
                    longBodyComposerSessions instanceof Map) {
                    longBodyComposerSessions.clear();
                    if (snap.longBodyComposerSessions) {
                        for (const [key, session] of snap.longBodyComposerSessions.entries()) {
                            const cloned = cloneLongBodyComposerSessionForHistory(session);
                            if (cloned) longBodyComposerSessions.set(key, cloned);
                        }
                    }
                }

                // 2. 还原 maniaSkinConfigurations
                maniaSkinConfigurations.clear();
                if (snap.maniaSkinConfigurations) {
                    for (const [k, v] of snap.maniaSkinConfigurations.entries()) {
                        const cloned = cloneManiaSkinConfig(v);
                        if (preserveNonTexture && currentNonTextureConfigs && currentNonTextureConfigs.has(k)) {
                            copyNonTextureManiaProperties(currentNonTextureConfigs.get(k), cloned);
                        }
                        maniaSkinConfigurations.set(k, cloned);
                    }
                }
                if (preserveNonTexture && currentNonTextureConfigs) {
                    for (const [k, v] of currentNonTextureConfigs.entries()) {
                        if (!maniaSkinConfigurations.has(k)) {
                            maniaSkinConfigurations.set(k, cloneManiaSkinConfig(v));
                        }
                    }
                }

                // 3. 还原 currentSkinMetadata & skinFontsConfig & globalSkinImageLookups
                if (!preserveNonTexture) {
                    if (snap.currentSkinMetadata) {
                        currentSkinMetadata = JSON.parse(JSON.stringify(snap.currentSkinMetadata));
                    }
                    if (snap.skinFontsConfig) {
                        skinFontsConfig = { ...snap.skinFontsConfig };
                    }
                }
                globalSkinImageLookups.clear();
                if (snap.globalSkinImageLookups) {
                    for (const [k, v] of snap.globalSkinImageLookups.entries()) {
                        globalSkinImageLookups.set(k, v);
                    }
                }

                // 4. 还原 skinImageStore 与 skinFallbackImageStore
                skinImageStore.clear();
                if (snap.skinImageStore) {
                    for (const [k, v] of snap.skinImageStore.entries()) {
                        skinImageStore.set(
                            normalizeSkinAssetStoreKey(k),
                            cloneSkinAssetEntry(v)
                        );
                    }
                }
                skinFallbackImageStore.clear();
                if (snap.skinFallbackImageStore) {
                    for (const [k, v] of snap.skinFallbackImageStore.entries()) {
                        skinFallbackImageStore.set(
                            normalizeSkinAssetStoreKey(k),
                            cloneSkinAssetEntry(v)
                        );
                    }
                }
                if (typeof clearComboburstRuntimeEffects === 'function') {
                    clearComboburstRuntimeEffects();
                }
                if (typeof refreshSkinCursor === 'function') refreshSkinCursor();

                // 5. 还原活动键位
                if (!preserveNonTexture && snap.activeEditorKeyCount) {
                    activeEditorKeyCount = snap.activeEditorKeyCount;
                }

                // 6. 重新渲染参数编辑器界面与 ini 预览
                updateSkinEditorKeyPills();
                renderSkinEditorParams();
                const rawTextarea = document.getElementById('rawIniTextarea');
                if (rawTextarea) {
                    rawTextarea.value = generateSkinIniText();
                }

                // 7. 重新同步音符状态与重绘游戏画面
                if (currentBeatmap) {
                    const currentTimeMs = (audio && !isNaN(audio.currentTime)) ? audio.currentTime * 1000 : 0;
                    syncNotesStateWithTime(currentTimeMs);
                }
                drawFrame();
                if (typeof textureLibraryUi !== 'undefined' && textureLibraryUi) {
                    textureLibraryUi.refresh();
                }
                updateSkinInfoDisplay();
                if (hitsoundReplacementsChanged &&
                    typeof refreshManiaHitsoundPlaybackAfterEdit === 'function') {
                    void refreshManiaHitsoundPlaybackAfterEdit();
                }
                if (selectedCanvasElement) {
                    const liveElem = canvasInteractiveElements.find(e => {
                        if (selectedCanvasElement.noteInstanceKey && e.noteInstanceKey) {
                            return e.noteInstanceKey === selectedCanvasElement.noteInstanceKey;
                        }
                        return e.id === selectedCanvasElement.id;
                    }) || selectedCanvasElement;
                    syncCanvasSelectedCard(liveElem);
                }
                if (window.skinWorkspaceRevision) window.skinWorkspaceRevision.adopt(snap);
            } catch (err) {
                console.error('[Undo/Redo] 还原皮肤快照失败:', err);
            } finally {
                isPerformingUndoRedo = false;
                updateUndoButtonState();
            }
        }

        function syncTextureEditorBaseAfterSkinHistory() {
            const modal = document.getElementById('textureImageEditorModal');
            if (!modal || (!modal.classList.contains('active') && modal.style.display === 'none')) {
                return;
            }
            if (typeof updateEditorBaseAfterSave === 'function') {
                updateEditorBaseAfterSave();
            }
            if (typeof refreshTextureImageEditorAfterSkinHistory === 'function') {
                refreshTextureImageEditorAfterSkinHistory();
            }
        }

        function performSkinUndo() {
            if (continuousActionTimer) {
                clearTimeout(continuousActionTimer);
                continuousActionActive = false;
            }
            if (undoStack.length === 0) {
                showToast('提示', '没有可撤回的操作');
                return;
            }
            const currentState = createSkinSnapshot('当前状态');
            redoStack.push(currentState);
            if (redoStack.length > MAX_UNDO_STACK) redoStack.shift();

            const previousState = undoStack.pop();
            applySkinSnapshot(previousState);
            syncTextureEditorBaseAfterSkinHistory();
            if (window.skinAgentSession &&
                typeof window.skinAgentSession.notifyExternalMutation === 'function') {
                window.skinAgentSession.notifyExternalMutation('undo');
            }
            showToast(
                '已撤回 (Ctrl+Z)',
                previousState.desc
                    ? window.I18n.t('已撤回: {desc}', { desc: window.I18n.t(previousState.desc) })
                    : '已恢复上一状态'
            );
        }

        function performSkinRedo() {
            if (continuousActionTimer) {
                clearTimeout(continuousActionTimer);
                continuousActionActive = false;
            }
            if (redoStack.length === 0) {
                showToast('提示', '没有可重做的操作');
                return;
            }
            const currentState = createSkinSnapshot('当前状态');
            undoStack.push(currentState);
            if (undoStack.length > MAX_UNDO_STACK) undoStack.shift();

            const nextState = redoStack.pop();
            applySkinSnapshot(nextState);
            syncTextureEditorBaseAfterSkinHistory();
            if (window.skinAgentSession &&
                typeof window.skinAgentSession.notifyExternalMutation === 'function') {
                window.skinAgentSession.notifyExternalMutation('redo');
            }
            showToast(
                '已重做 (Ctrl+Y)',
                nextState.desc
                    ? window.I18n.t('已重做: {desc}', { desc: window.I18n.t(nextState.desc) })
                    : '已恢复操作'
            );
        }

        function saveInitialSkinSnapshot() {
            try {
                if (window.skinWorkspaceRevision) window.skinWorkspaceRevision.reset();
                initialSkinSnapshot = {
                    maniaSkinConfigurations: cloneManiaSkinConfigs(maniaSkinConfigurations),
                    currentSkinMetadata: JSON.parse(JSON.stringify(currentSkinMetadata)),
                    skinFontsConfig: { ...skinFontsConfig },
                    globalSkinImageLookups: new Map(globalSkinImageLookups),
                    skinImageStore: cloneSkinImageStore(skinImageStore),
                    skinFallbackImageStore: cloneSkinImageStore(skinFallbackImageStore),
                    skinHitsoundReplacements: typeof cloneSkinHitsoundReplacements === 'function'
                        ? cloneSkinHitsoundReplacements()
                        : new Map(),
                    deletedSkinTexturePaths: new Set(deletedSkinTexturePaths),
                    revisionId: 0
                };
                undoStack.length = 0;
                redoStack.length = 0;
                continuousActionActive = false;
                updateUndoButtonState();
                if (window.skinAgentSession &&
                    typeof window.skinAgentSession.notifyExternalMutation === 'function') {
                    window.skinAgentSession.notifyExternalMutation('initial-snapshot');
                }
            } catch (err) {
                console.error('[Snapshot] 保存皮肤初始快照失败:', err);
            }
        }

        function revertSkinToInitial() {
            if (!initialSkinSnapshot) {
                showToast('提示', '暂无已保存的初始皮肤快照');
                return;
            }

            if (!confirm(window.I18n.t('确定要将所有参数和贴图复原为皮肤导入时的初始状态吗？未导出的修改将被丢弃。'))) {
                return;
            }

            recordSkinUndoBeforeChange('复原初始皮肤');
            continuousActionActive = false;

            // 清理画布选中与交互状态
            selectedCanvasElement = null;
            const card = document.getElementById('canvasSelectedCard');
            if (card) card.style.display = 'none';

            applySkinSnapshot(initialSkinSnapshot);
            syncTextureEditorBaseAfterSkinHistory();
            showToast('已复原', '所有参数与贴图已恢复为导入时的初始状态 (可按 Ctrl+Z 撤回)');
        }

        async function startFromDefaultSkin(options = {}) {
            const skipConfirm = options && options.skipConfirm === true;
            if (!skipConfirm && !confirm(window.I18n.t('确定要清空当前皮肤，并从 osu!stable 默认皮肤重新开始吗？未导出的修改将被丢弃。'))) {
                return false;
            }

            if (isPlaying) {
                pauseAudioAndBeatmap();
            }

            const keyCount = getActiveKeyCount();
            clearTextureProjectImportState();
            currentSkinZip = null;
            currentSkinFileName = '默认皮肤';
            if (typeof clearSkinHitsoundReplacements === 'function') {
                clearSkinHitsoundReplacements();
            } else {
                skinHitsoundReplacements.clear();
            }
            skinHitsoundCatalog.clear();
            skinHitsoundSummary = {
                groupCount: 0,
                fileCount: 0,
                selectedFileCount: 0
            };
            deactivateEditableDefaultSkinWorkspace();

            userReplacedTextures.clear();
            deletedSkinTexturePaths.clear();
            createdSkinTextureParams.clear();
            if (typeof textureEditRecipes !== 'undefined' && textureEditRecipes instanceof Map) {
                textureEditRecipes.clear();
            }
            if (typeof longBodyComposerSessions !== 'undefined' && longBodyComposerSessions instanceof Map) {
                longBodyComposerSessions.clear();
            }
            scorePercentSourceImages.clear();
            for (const url of activeSkinBlobUrls) {
                try { URL.revokeObjectURL(url); } catch (_) {}
            }
            activeSkinBlobUrls = [];

            skinImageStore.clear();
            skinFallbackImageStore.clear();
            maniaSkinConfigurations.clear();
            globalSkinImageLookups.clear();
            if (typeof keyImageHeightBaselineState !== 'undefined') {
                keyImageHeightBaselineState.clear();
            }

            skinFontsConfig = {
                scorePrefix: 'score',
                scoreOverlap: 0,
                comboPrefix: 'combo',
                comboOverlap: 0,
                hitCirclePrefix: 'default',
                hitCircleOverlap: -2,
                hasExplicitScoreOverlap: false,
                hasExplicitComboOverlap: false,
                hasExplicitComboPrefix: false
            };
            currentSkinMetadata = createEditableDefaultSkinMetadata();

            if (ui.osk) ui.osk.value = '';
            await loadDefaultSkin();
            const defaultHitsoundCatalog = typeof ensureDefaultSkinHitsoundsLoaded === 'function'
                ? await ensureDefaultSkinHitsoundsLoaded()
                : new Map();
            skinHitsoundCatalog = new Map(defaultHitsoundCatalog);
            if (typeof refreshSkinHitsoundCatalogWithReplacements === 'function') {
                refreshSkinHitsoundCatalogWithReplacements();
            } else {
                skinHitsoundSummary = typeof summarizeSkinHitsoundCatalog === 'function'
                    ? summarizeSkinHitsoundCatalog(skinHitsoundCatalog)
                    : {
                        groupCount: skinHitsoundCatalog.size,
                        fileCount: skinHitsoundCatalog.size,
                        selectedFileCount: skinHitsoundCatalog.size
                    };
            }
            activateEditableDefaultSkinWorkspace(keyCount);
            if (typeof prepareManiaHitsoundPlayback === 'function' && currentBeatmap && activeNotes.length > 0) {
                await prepareManiaHitsoundPlayback();
            }

            selectedCanvasElement = null;
            const card = document.getElementById('canvasSelectedCard');
            if (card) card.style.display = 'none';

            updateSkinInfoDisplay();
            updateSkinEditorKeyPills();
            renderSkinEditorParams();
            if (typeof refreshSkinEditorAfterSkinImport === 'function') {
                refreshSkinEditorAfterSkinImport();
            }
            if (typeof refreshSkinCursor === 'function') refreshSkinCursor();
            if (currentBeatmap) {
                const currentTimeMs = (audio && !isNaN(audio.currentTime)) ? audio.currentTime * 1000 : 0;
                syncNotesStateWithTime(currentTimeMs);
            }
            drawFrame();
            saveInitialSkinSnapshot();
            if (typeof markStartupSkinReady === 'function') {
                markStartupSkinReady('默认皮肤');
            }
            showToast('已切换到默认皮肤', '当前工作区已重置为 osu!stable 默认皮肤');
            return true;
        }
// --- END ui/history.js ---

// --- BEGIN ui/editor-card-controls.js ---
// ============================================================================
// editor-card-controls.js - 画布选中卡片控件与快捷操作
// 从 editor-dialog.js 的弹窗初始化中按职责拆分。
// ============================================================================

        function initSkinEditorCardControlsUI() {
            // 画布悬浮气泡卡片操作按钮绑定
            const cardCloseBtn = document.getElementById('cardCloseBtn');
            const cardLocateBtn = document.getElementById('cardLocateParamBtn');
            const cardReplaceBtn = document.getElementById('cardReplaceTextureBtn');
            const cardReplaceScorebarBgBtn = document.getElementById('cardReplaceScorebarBgBtn');
            const cardReplaceScorebarColourBtn = document.getElementById('cardReplaceScorebarColourBtn');
            const cardWidthDecBtn = document.getElementById('cardWidthDecBtn');
            const cardWidthIncBtn = document.getElementById('cardWidthIncBtn');
            const cardSpacingDecBtn = document.getElementById('cardSpacingDecBtn');
            const cardSpacingIncBtn = document.getElementById('cardSpacingIncBtn');
            const cardPosDecBtn = document.getElementById('cardPosDecBtn');
            const cardPosIncBtn = document.getElementById('cardPosIncBtn');
            const cardPosValEl = document.getElementById('cardPosVal');

            if (cardCloseBtn) {
                cardCloseBtn.onclick = () => {
                    selectedCanvasElement = null;
                    const card = document.getElementById('canvasSelectedCard');
                    if (card) card.style.display = 'none';
                    drawFrame();
                };
            }
            if (cardLocateBtn) {
                cardLocateBtn.onclick = () => {
                    if (!selectedCanvasElement) return;
                    if (selectedCanvasElement.id.startsWith('track_col_')) {
                        focusParameter(['ColumnWidth', 'ColumnSpacing', 'ColumnColour']);
                    } else {
                        focusParameter(selectedCanvasElement.paramKey);
                    }
                };
            }
            const cardApplyAllTracksBtn = document.getElementById('cardApplyAllTracksBtn');
            if (cardApplyAllTracksBtn) {
                cardApplyAllTracksBtn.onclick = () => {
                    if (!selectedCanvasElement || !selectedCanvasElement.id.startsWith('track_col_')) return;
                    const col = selectedCanvasElement.colIndex;
                    const keys = getActiveKeyCount();
                    let cfg = maniaSkinConfigurations.get(keys);
                    if (!cfg) {
                        cfg = ensureManiaConfigForKeys(keys);
                        maniaSkinConfigurations.set(keys, cfg);
                    }
                    if (!Array.isArray(cfg.ColumnWidth)) cfg.ColumnWidth = new Array(keys).fill(30);
                    while (cfg.ColumnWidth.length < keys) cfg.ColumnWidth.push(30);
                    const spacingCount = Math.max(0, keys - 1);
                    if (!Array.isArray(cfg.ColumnSpacing)) cfg.ColumnSpacing = new Array(spacingCount).fill(0);
                    while (cfg.ColumnSpacing.length < spacingCount) cfg.ColumnSpacing.push(0);

                    const curW = cfg.ColumnWidth[col] != null ? cfg.ColumnWidth[col] : 30;
                    const spacingIdx = (col > 0) ? (col - 1) : 0;
                    const curS = cfg.ColumnSpacing[spacingIdx] != null ? cfg.ColumnSpacing[spacingIdx] : 0;

                    // 统一前先校验轨道区总宽度：统一后若超限则直接阻止，避免全轨宽度异常
                    const uniformTotal = keys * curW + (keys - 1) * curS;
                    if (uniformTotal > getTrackMaxWidth480(cfg, keys)) {
                        notifyTrackWidthLimit(
                            '全轨统一列宽/间距',
                            '统一为 ' + curW + 'px 列宽' + (curS > 0 ? ' + ' + curS + 'px 间距' : '') + ' 后总宽度为 ' + Math.round(uniformTotal)
                        );
                        return;
                    }
                    recordSkinUndoBeforeChange('将当前轨宽与间距应用给所有轨道');
                    for (let i = 0; i < keys; i++) {
                        cfg.ColumnWidth[i] = curW;
                        if (i < keys - 1) {
                            cfg.ColumnSpacing[i] = curS;
                        }
                    }
                    continuousActionActive = false;
                    syncColumnRightFromLayout(cfg, keys);
                    drawFrame();
                    syncParamInputValue('ColumnWidth', cfg.ColumnWidth);
                    syncParamInputValue('ColumnSpacing', cfg.ColumnSpacing);
                    syncCanvasSelectedCard(selectedCanvasElement);
                    showToast('已应用给所有轨道', `全部 ${keys} 轨列宽已统一为 ${curW}px${curS > 0 ? `，间距已统一为 ${curS}px` : ''}`);
                };
            }

            // 卡片第 2 行轨道底色与透明度调节事件绑定
            const cardColPicker = document.getElementById('cardColPicker');
            const cardColOpacitySlider = document.getElementById('cardColOpacitySlider');
            const cardColOpacityVal = document.getElementById('cardColOpacityVal');
            const cardApplyAllColourBtn = document.getElementById('cardApplyAllColourBtn');

            function updateTrackColourFromCard(isFinal = false) {
                if (!selectedCanvasElement || !selectedCanvasElement.id.startsWith('track_col_')) return;
                const col = selectedCanvasElement.colIndex;
                const keys = getActiveKeyCount();
                let cfg = maniaSkinConfigurations.get(keys);
                if (!cfg) {
                    cfg = ensureManiaConfigForKeys(keys);
                    maniaSkinConfigurations.set(keys, cfg);
                }
                if (!cfg.ColumnColour) {
                    cfg.ColumnColour = new Array(keys).fill(null).map(() => ({ r: 0, g: 0, b: 0, a: 255 }));
                }
                while (cfg.ColumnColour.length < keys) {
                    cfg.ColumnColour.push({ r: 0, g: 0, b: 0, a: 255 });
                }

                const hex = cardColPicker ? cardColPicker.value : '#000000';
                const r = parseInt(hex.slice(1, 3), 16) || 0;
                const g = parseInt(hex.slice(3, 5), 16) || 0;
                const b = parseInt(hex.slice(5, 7), 16) || 0;
                const a = cardColOpacitySlider ? parseInt(cardColOpacitySlider.value, 10) : 255;
                if (cardColOpacityVal) cardColOpacityVal.textContent = `${a}`;
                if (cardColOpacitySlider) {
                    const pct = ((a / 255) * 100).toFixed(1) + '%';
                    cardColOpacitySlider.style.setProperty('--slider-pct', pct);
                }

                if (isFinal) {
                    recordSkinUndoBeforeChange(`调整第 ${col + 1} 轨底色与透明度`);
                }
                cfg.ColumnColour[col] = { r, g, b, a };
                if (isFinal) {
                    continuousActionActive = false;
                }
                drawFrame();
                const modal = document.getElementById('skinEditorModal');
                if (modal && modal.classList.contains('active')) {
                    renderSkinEditorParams();
                }
            }

            if (cardColPicker) {
                cardColPicker.oninput = () => updateTrackColourFromCard(false);
                cardColPicker.onchange = () => updateTrackColourFromCard(true);
            }
            if (cardColOpacitySlider) {
                cardColOpacitySlider.oninput = () => updateTrackColourFromCard(false);
                cardColOpacitySlider.onchange = () => updateTrackColourFromCard(true);
            }
            if (cardApplyAllColourBtn) {
                cardApplyAllColourBtn.onclick = () => {
                    if (!selectedCanvasElement || !selectedCanvasElement.id.startsWith('track_col_')) return;
                    const col = selectedCanvasElement.colIndex;
                    const keys = getActiveKeyCount();
                    let cfg = maniaSkinConfigurations.get(keys);
                    if (!cfg) {
                        cfg = ensureManiaConfigForKeys(keys);
                        maniaSkinConfigurations.set(keys, cfg);
                    }
                    if (!cfg.ColumnColour) {
                        cfg.ColumnColour = new Array(keys).fill(null).map(() => ({ r: 0, g: 0, b: 0, a: 255 }));
                    }
                    while (cfg.ColumnColour.length < keys) {
                        cfg.ColumnColour.push({ r: 0, g: 0, b: 0, a: 255 });
                    }

                    const hex = cardColPicker ? cardColPicker.value : '#000000';
                    const r = parseInt(hex.slice(1, 3), 16) || 0;
                    const g = parseInt(hex.slice(3, 5), 16) || 0;
                    const b = parseInt(hex.slice(5, 7), 16) || 0;
                    const a = cardColOpacitySlider ? parseInt(cardColOpacitySlider.value, 10) : 255;

                    recordSkinUndoBeforeChange('将当前轨底色与透明度应用给所有轨道');
                    for (let i = 0; i < keys; i++) {
                        cfg.ColumnColour[i] = { r, g, b, a };
                    }
                    continuousActionActive = false;
                    drawFrame();
                    const modal = document.getElementById('skinEditorModal');
                    if (modal && modal.classList.contains('active')) {
                        renderSkinEditorParams();
                    }
                    showToast('已应用全轨同色', `全部 ${keys} 轨底色已统一为 RGBA(${r}, ${g}, ${b}, ${a})`);
                };
            }
            const cardLocateComboTextureBtn = document.getElementById('cardLocateComboTextureBtn');
            if (cardLocateComboTextureBtn) {
                cardLocateComboTextureBtn.onclick = () => {
                    focusComboTexture();
                };
            }

            // 连击悬浮卡片第 2、3 行：直接编辑 Hold 变色与断连遮罩，并在画布上实时预览。
            const cardComboHoldPicker = document.getElementById('cardComboHoldPicker');
            const cardComboHoldAlpha = document.getElementById('cardComboHoldAlpha');
            const cardComboHoldAlphaVal = document.getElementById('cardComboHoldAlphaVal');
            const cardComboHoldPreviewBtn = document.getElementById('cardComboHoldPreviewBtn');
            const cardComboBreakPicker = document.getElementById('cardComboBreakPicker');
            const cardComboBreakPreviewBtn = document.getElementById('cardComboBreakPreviewBtn');

            function getSelectedComboConfig() {
                if (!selectedCanvasElement || selectedCanvasElement.id !== 'combo') return null;
                return ensureManiaConfigForKeys(getActiveKeyCount());
            }

            function refreshComboColourParamPanel() {
                const modal = document.getElementById('skinEditorModal');
                if (modal && modal.classList.contains('active')) {
                    renderSkinEditorParams();
                }
                if (selectedCanvasElement && selectedCanvasElement.id === 'combo') {
                    syncCanvasSelectedCard(selectedCanvasElement);
                }
            }

            function updateComboHoldFromCard(isFinal = false) {
                const cfg = getSelectedComboConfig();
                if (!cfg) return;

                recordSkinUndoBeforeChange('调整 Hold 连击数字变色');
                const hex = cardComboHoldPicker ? cardComboHoldPicker.value : '#ffbf33';
                const r = parseInt(hex.slice(1, 3), 16) || 0;
                const g = parseInt(hex.slice(3, 5), 16) || 0;
                const b = parseInt(hex.slice(5, 7), 16) || 0;
                const a = cardComboHoldAlpha ? parseInt(cardComboHoldAlpha.value, 10) : 255;
                cfg.ColourHold = { r, g, b, a };

                if (cardComboHoldAlphaVal) cardComboHoldAlphaVal.textContent = `${a}`;
                if (cardComboHoldAlpha) {
                    cardComboHoldAlpha.style.setProperty('--slider-pct', `${((a / 255) * 100).toFixed(1)}%`);
                }
                testHoldingUntil = performance.now() + 2500;
                if (isFinal) continuousActionActive = false;
                drawFrame();
                refreshComboColourParamPanel();
            }

            function updateComboBreakFromCard(isFinal = false) {
                const cfg = getSelectedComboConfig();
                if (!cfg) return;

                recordSkinUndoBeforeChange('调整断连遮罩颜色');
                const hex = cardComboBreakPicker ? cardComboBreakPicker.value : '#ff0000';
                const r = parseInt(hex.slice(1, 3), 16) || 0;
                const g = parseInt(hex.slice(3, 5), 16) || 0;
                const b = parseInt(hex.slice(5, 7), 16) || 0;
                cfg.ComboBreakColour = { r, g, b, a: 255 };

                if (isFinal) continuousActionActive = false;
                triggerComboBreakPreview();
                refreshComboColourParamPanel();
            }

            if (cardComboHoldPicker) {
                cardComboHoldPicker.oninput = () => updateComboHoldFromCard(false);
                cardComboHoldPicker.onchange = () => updateComboHoldFromCard(true);
            }
            if (cardComboHoldAlpha) {
                cardComboHoldAlpha.oninput = () => updateComboHoldFromCard(false);
                cardComboHoldAlpha.onchange = () => updateComboHoldFromCard(true);
            }
            if (cardComboHoldPreviewBtn) {
                cardComboHoldPreviewBtn.onclick = () => {
                    testHoldingUntil = performance.now() + 2500;
                    drawFrame();
                };
            }
            if (cardComboBreakPicker) {
                cardComboBreakPicker.oninput = () => updateComboBreakFromCard(false);
                cardComboBreakPicker.onchange = () => updateComboBreakFromCard(true);
            }
            if (cardComboBreakPreviewBtn) {
                cardComboBreakPreviewBtn.onclick = () => {
                    triggerComboBreakPreview();
                };
            }
            const cardPreviewJudgementBtn = document.getElementById('cardPreviewJudgementBtn');
            if (cardPreviewJudgementBtn) {
                cardPreviewJudgementBtn.onclick = () => {
                    setPreviewJudgementActive(!isPreviewJudgementActive);
                };
            }

            // 轨道拖拽模式切换按钮绑定
            const trackModeWidthBtn = document.getElementById('trackModeWidthBtn');
            const trackModeSpacingBtn = document.getElementById('trackModeSpacingBtn');
            const setTrackDragMode = (mode) => {
                currentTrackDragMode = mode;
                if (trackModeWidthBtn) {
                    if (mode === 'width') trackModeWidthBtn.classList.add('active');
                    else trackModeWidthBtn.classList.remove('active');
                }
                if (trackModeSpacingBtn) {
                    if (mode === 'spacing') trackModeSpacingBtn.classList.add('active');
                    else trackModeSpacingBtn.classList.remove('active');
                }
                if (selectedCanvasElement) drawFrame();
            };
            if (trackModeWidthBtn) trackModeWidthBtn.onclick = () => setTrackDragMode('width');
            if (trackModeSpacingBtn) trackModeSpacingBtn.onclick = () => setTrackDragMode('spacing');

            // 卡片快捷调节单轨列宽与列间距步进函数 (两轨间最小间距严格限制为0)
            const stepSelectedTrackWidth = (delta) => {
                if (!selectedCanvasElement) return;

                if (selectedCanvasElement.dragType === 'score_percent_width') {
                    const currentWidth = getScorePercentPaddingWidth(getActiveKeyCount());
                    const nextWidth = clampScorePercentPaddingWidth(currentWidth + delta);
                    setScorePercentPaddingWidth(nextWidth, getActiveKeyCount());
                    drawFrame();
                    syncParamInputValue('ScorePercentWidth', nextWidth);
                    syncParamInputValue('ScorePercentVisible', false);
                    syncCanvasSelectedCard(selectedCanvasElement);
                    return;
                }

                // 打击特效宽度 (LightingNWidth / LightingLWidth)：同一个「宽度」步进器复用给逐轨宽度与特效宽度
                if (selectedCanvasElement.dragType === 'lighting_width') {
                    const lwCol = selectedCanvasElement.colIndex;
                    const widthKey = selectedCanvasElement.paramKey;
                    const lwKeys = getActiveKeyCount();
                    let lwCfg = maniaSkinConfigurations.get(lwKeys);
                    if (!lwCfg) {
                        lwCfg = ensureManiaConfigForKeys(lwKeys);
                        maniaSkinConfigurations.set(lwKeys, lwCfg);
                    }
                    if (!Array.isArray(lwCfg[widthKey])) lwCfg[widthKey] = new Array(lwKeys).fill(0);
                    while (lwCfg[widthKey].length < lwKeys) lwCfg[widthKey].push(0);
                    // 未显式配置时以「当前列宽」为起点，避免从 0 开始跳变
                    const rawCwRes2 = getManiaSkinConfig(lwKeys, LML.ColumnWidth, lwCol);
                    const rawCw2 = (rawCwRes2 && rawCwRes2.value > 0) ? rawCwRes2.value : 30;
                    const lwCur = (lwCfg[widthKey][lwCol] != null && lwCfg[widthKey][lwCol] > 0) ? lwCfg[widthKey][lwCol] : rawCw2;
                    lwCfg[widthKey][lwCol] = Math.max(0, Math.min(300, Math.round(lwCur + delta)));
                    drawFrame();
                    syncParamInputValue(widthKey, lwCfg[widthKey]);
                    syncCanvasSelectedCard(selectedCanvasElement);
                    return;
                }

                if (!selectedCanvasElement.id.startsWith('track_col_')) return;
                const col = selectedCanvasElement.colIndex;
                const keys = getActiveKeyCount();
                let cfg = maniaSkinConfigurations.get(keys);
                if (!cfg) {
                    cfg = ensureManiaConfigForKeys(keys);
                    maniaSkinConfigurations.set(keys, cfg);
                }
                if (!Array.isArray(cfg.ColumnWidth)) cfg.ColumnWidth = new Array(keys).fill(30);
                while (cfg.ColumnWidth.length < keys) cfg.ColumnWidth.push(30);
                const cur = cfg.ColumnWidth[col] != null ? cfg.ColumnWidth[col] : 30;
                let next = Math.max(5, Math.min(300, Math.round(cur + delta)));
                // 轨道区最大总宽度保护：增大到上限即停住并提示
                const boundW = getTrackParamUpperBound(cfg, keys, 'ColumnWidth', col);
                if (next > boundW.maxAllowed) {
                    next = Math.max(5, Math.floor(boundW.maxAllowed));
                    if (delta > 0) notifyTrackWidthLimit(`第 ${col + 1} 轨列宽`);
                }
                cfg.ColumnWidth[col] = next;
                syncColumnRightFromLayout(cfg, keys);
                drawFrame();
                syncParamInputValue('ColumnWidth', cfg.ColumnWidth);
                syncCanvasSelectedCard(selectedCanvasElement);
            };

            const stepSelectedTrackSpacing = (delta) => {
                if (!selectedCanvasElement || !selectedCanvasElement.id.startsWith('track_col_')) return;
                const col = selectedCanvasElement.colIndex;
                if (col <= 0) return; // 第一轨无前距
                const keys = getActiveKeyCount();
                const spacingIdx = col - 1;
                let cfg = maniaSkinConfigurations.get(keys);
                if (!cfg) {
                    cfg = ensureManiaConfigForKeys(keys);
                    maniaSkinConfigurations.set(keys, cfg);
                }
                const spacingCount = Math.max(0, keys - 1);
                if (!Array.isArray(cfg.ColumnSpacing)) cfg.ColumnSpacing = new Array(spacingCount).fill(0);
                while (cfg.ColumnSpacing.length < spacingCount) cfg.ColumnSpacing.push(0);
                const cur = cfg.ColumnSpacing[spacingIdx] != null ? cfg.ColumnSpacing[spacingIdx] : 0;
                // 核心规则：两个轨道之间的最小间距为 0
                let next = Math.max(0, Math.min(200, Math.round(cur + delta)));
                // 轨道区最大总宽度保护：增大到上限即停住并提示
                const boundS = getTrackParamUpperBound(cfg, keys, 'ColumnSpacing', spacingIdx);
                if (next > boundS.maxAllowed) {
                    next = Math.max(0, Math.floor(boundS.maxAllowed));
                    if (delta > 0) notifyTrackWidthLimit(`第 ${spacingIdx + 1} 轨与第 ${spacingIdx + 2} 轨间距`);
                }
                cfg.ColumnSpacing[spacingIdx] = next;
                syncColumnRightFromLayout(cfg, keys);
                drawFrame();
                syncParamInputValue('ColumnSpacing', cfg.ColumnSpacing);
                syncCanvasSelectedCard(selectedCanvasElement);
            };

            const widthStepDesc = () => {
                if (selectedCanvasElement && selectedCanvasElement.dragType === 'score_percent_width') {
                    return '调整准度与进度饼图位置';
                }
                if (selectedCanvasElement && selectedCanvasElement.dragType === 'lighting_width') {
                    return `微调${selectedCanvasElement.name}宽度`;
                }
                return '微调轨道宽度';
            };
            if (cardWidthDecBtn) cardWidthDecBtn.onclick = (e) => {
                recordSkinUndoBeforeChange(widthStepDesc());
                continuousActionActive = false;
                stepSelectedTrackWidth(e.shiftKey ? -5 : -1);
            };
            if (cardWidthIncBtn) cardWidthIncBtn.onclick = (e) => {
                recordSkinUndoBeforeChange(widthStepDesc());
                continuousActionActive = false;
                stepSelectedTrackWidth(e.shiftKey ? 5 : 1);
            };
            if (cardSpacingDecBtn) cardSpacingDecBtn.onclick = (e) => {
                recordSkinUndoBeforeChange('微调轨道间距');
                continuousActionActive = false;
                stepSelectedTrackSpacing(e.shiftKey ? -5 : -1);
            };
            if (cardSpacingIncBtn) cardSpacingIncBtn.onclick = (e) => {
                recordSkinUndoBeforeChange('微调轨道间距');
                continuousActionActive = false;
                stepSelectedTrackSpacing(e.shiftKey ? 5 : 1);
            };

            // 卡片快捷调节位置与数值参数步进函数 (针对连击数、判定线、判定评价、光效高度等)
            const stepSelectedPos = (delta) => {
                if (!selectedCanvasElement) return;
                const paramKey = selectedCanvasElement.paramKey;
                if (!paramKey) return;
                const keys = getActiveKeyCount();
                let cfg = maniaSkinConfigurations.get(keys);
                if (!cfg) {
                    cfg = ensureManiaConfigForKeys(keys);
                    maniaSkinConfigurations.set(keys, cfg);
                }

                let curVal = 0;
                if (paramKey === 'ComboPosition') {
                    curVal = (cfg.ComboPosition != null) ? cfg.ComboPosition : 111;
                } else if (paramKey === 'ScorePosition') {
                    curVal = (cfg.ScorePosition != null) ? cfg.ScorePosition : 300;
                } else if (paramKey === 'HitPosition') {
                    curVal = (cfg.HitPosition != null) ? cfg.HitPosition : 402;
                } else if (paramKey === 'LightPosition') {
                    curVal = (cfg.LightPosition != null) ? cfg.LightPosition : 413;
                } else if (typeof cfg[paramKey] === 'number') {
                    curVal = cfg[paramKey];
                } else {
                    return;
                }

                const nextVal = Math.max(0, Math.min(1000, Math.round(curVal + delta)));
                cfg[paramKey] = nextVal;
                drawFrame();
                syncParamInputValue(paramKey, nextVal);
                syncCanvasSelectedCard(selectedCanvasElement);
            };

            if (cardPosDecBtn) cardPosDecBtn.onclick = (e) => {
                recordSkinUndoBeforeChange(`微调${selectedCanvasElement ? selectedCanvasElement.name : '数值'}`);
                continuousActionActive = false;
                stepSelectedPos(e.shiftKey ? -5 : -1);
            };
            if (cardPosIncBtn) cardPosIncBtn.onclick = (e) => {
                recordSkinUndoBeforeChange(`微调${selectedCanvasElement ? selectedCanvasElement.name : '数值'}`);
                continuousActionActive = false;
                stepSelectedPos(e.shiftKey ? 5 : 1);
            };
            // 打击特效宽度数值：点击可直接输入（与位置数值同样的交互习惯）
            const cardWidthValEl = document.getElementById('cardWidthVal');
            if (cardWidthValEl) {
                cardWidthValEl.style.cursor = 'pointer';
                cardWidthValEl.onclick = () => {
                    if (!selectedCanvasElement) return;
                    if (selectedCanvasElement.dragType === 'score_percent_width') {
                        const current = getScorePercentPaddingWidth(getActiveKeyCount());
                        const input = prompt(window.I18n.t('输入 score-percent 透明垫片的 1x 逻辑宽度 (1 - 2000，1 = 仅隐藏百分号):'), current);
                        if (input === null) return;
                        const parsed = parseInt(input.trim(), 10);
                        if (isNaN(parsed)) return;
                        recordSkinUndoBeforeChange('调整准度与进度饼图位置');
                        continuousActionActive = false;
                        const nextWidth = clampScorePercentPaddingWidth(parsed);
                        setScorePercentPaddingWidth(nextWidth, getActiveKeyCount());
                        drawFrame();
                        syncParamInputValue('ScorePercentWidth', nextWidth);
                        syncParamInputValue('ScorePercentVisible', false);
                        syncCanvasSelectedCard(selectedCanvasElement);
                        return;
                    }
                    if (selectedCanvasElement.dragType !== 'lighting_width') return;
                    const current = parseInt(cardWidthValEl.textContent, 10) || 0;
                    const input = prompt(window.I18n.t('输入新的打击特效宽度 (0 - 300，480p 虚拟像素；0 = 跟随列宽):'), current);
                    if (input === null) return;
                    const parsed = parseInt(input.trim(), 10);
                    if (isNaN(parsed)) return;
                    recordSkinUndoBeforeChange(`修改${selectedCanvasElement.name}宽度`);
                    continuousActionActive = false;
                    stepSelectedTrackWidth(parsed - current);
                };
            }

            if (cardPosValEl) {
                cardPosValEl.title = '点击直接输入数值';
                cardPosValEl.style.cursor = 'pointer';
                cardPosValEl.onclick = () => {
                    const current = parseInt(cardPosValEl.textContent, 10) || 0;
                    const input = prompt(window.I18n.t('输入新的数值 (0 - 1000):'), current);
                    if (input !== null) {
                        const parsed = parseInt(input.trim(), 10);
                        if (!isNaN(parsed)) {
                            recordSkinUndoBeforeChange(`修改${selectedCanvasElement ? selectedCanvasElement.name : '数值'}`);
                            continuousActionActive = false;
                            stepSelectedPos(parsed - current);
                        }
                    }
                };
            };

            if (cardReplaceBtn) {
                cardReplaceBtn.onclick = () => {
                    if (!selectedCanvasElement) return;
                    // 判定提示 (判定结果评价) 由 6 张判定贴图共同决定，不存在「单张对应贴图」：
                    // 因此点击后不再弹出选取文件的窗口，而是定位到 skin.ini 贴图参数区域，
                    // 一次性高亮全部判定贴图 (彩300g / 黄300 / 绿200 / 蓝100 / 灰50 / Miss)。
                    if (selectedCanvasElement.id === 'judgement') {
                        const located = focusParameter(JUDGEMENT_TEXTURE_PARAM_KEYS);
                        if (located === false) {
                            showToast('无法定位判定贴图', '请先确认谱面和皮肤均已载入。');
                            return;
                        }
                        showToast(
                            '已定位判定贴图',
                            '参数面板已高亮全部判定贴图：' + JUDGEMENT_TEXTURE_PARAM_KEYS.join(' / ')
                        );
                        return;
                    }
                    // 按键贴图的「替换贴图」改为定位到详细设置中的逐轨贴图选项，
                    // 同时高亮当前轨的 KeyImage 与 KeyImageD，便于连续替换这两种状态。
                    if (selectedCanvasElement.id.startsWith('key_') && selectedCanvasElement.colIndex != null) {
                        const col = selectedCanvasElement.colIndex;
                        const keyImageParam = `KeyImage${col}`;
                        const keyImageDownParam = `KeyImage${col}D`;
                        const located = focusParameter([keyImageParam, keyImageDownParam]);
                        if (located === false) {
                            showToast('无法定位按键贴图', `未找到 ${keyImageParam} 或 ${keyImageDownParam}。`);
                            return;
                        }
                        showToast(
                            '已定位按键贴图',
                            `参数面板已高亮 ${keyImageParam} 与 ${keyImageDownParam}`
                        );
                        return;
                    }
                    // 打击特效 (LightingN / LightingL) 本质是多帧动态贴图序列：
                    // 点击「替换贴图」不再弹「单张图片」选择框，而是直接打开动态贴图序列管理器。
                    if (selectedCanvasElement.openAnimOnReplace && typeof openAnimTextureEditor === 'function') {
                        openAnimTextureEditor(
                            selectedCanvasElement.textureName,
                            selectedCanvasElement.textureKey,
                            selectedCanvasElement.textureParamKey || selectedCanvasElement.paramKey,
                            '1x'
                        );
                        return;
                    }
                    // 注意：必须使用 textureParamKey（该元素对应的「贴图参数键」）而不是 paramKey。
                    // 有些画布元素同时承载「数值参数」与「贴图」（如按键发光 = LightPosition + StageLight、
                    // 判定线 = HitPosition + StageHint）；若误传 paramKey，会把贴图名写进数值参数，
                    // 导致 skin.ini 出现 `LightPosition: xxx.png` 这类污染。
                    triggerTextureUpload(
                        selectedCanvasElement.textureName,
                        selectedCanvasElement.textureKey,
                        selectedCanvasElement.textureParamKey || selectedCanvasElement.paramKey,
                        selectedCanvasElement.colIndex
                    );
                };
            }
            if (cardReplaceScorebarBgBtn) {
                cardReplaceScorebarBgBtn.onclick = () => {
                    triggerTextureUpload('scorebar-bg', null, 'scorebar-bg');
                };
            }
            if (cardReplaceScorebarColourBtn) {
                cardReplaceScorebarColourBtn.onclick = () => {
                    triggerTextureUpload('scorebar-colour', null, 'scorebar-colour');
                };
            }

        }
// --- END ui/editor-card-controls.js ---

// --- BEGIN ui/editor-dialog.js ---
// ============================================================================
// editor-dialog.js - 皮肤编辑器弹窗、窗口拖拽、搜索与选中卡片交互
// 依赖：ui/param-render.js、ui/param-core.js
// ============================================================================

        let activeFloatingWindow = null;
        let skinEditorCloseTimer = null;
        let skinEditorCloseToken = 0;

        function closeSkinEditorDialog(options = {}) {
            const modal = document.getElementById('skinEditorModal');
            const dialog = document.getElementById('skinEditorDialog');
            if (!modal) return false;

            if (typeof stopHitsoundPreview === 'function') stopHitsoundPreview();

            if (activeFloatingWindow === 'skin-editor') {
                const textureModal = document.getElementById('textureImageEditorModal');
                if (textureModal && (textureModal.classList.contains('active') || textureModal.style.display !== 'none') && !textureModal.classList.contains('is-closing')) {
                    bringFloatingWindowToFront('texture-editor');
                } else {
                    activeFloatingWindow = null;
                }
            }

            if (!modal.classList.contains('active')) {
                modal.classList.remove('is-closing');
                return false;
            }

            if (options && options.immediate) {
                skinEditorCloseToken++;
                if (skinEditorCloseTimer) {
                    clearTimeout(skinEditorCloseTimer);
                    skinEditorCloseTimer = null;
                }
                modal.classList.remove('active');
                modal.classList.remove('is-closing');
                return true;
            }

            if (skinEditorCloseTimer) {
                return true;
            }

            const currentToken = ++skinEditorCloseToken;
            modal.classList.add('is-closing');

            const finishClose = () => {
                if (skinEditorCloseToken !== currentToken) return;
                if (skinEditorCloseTimer) {
                    clearTimeout(skinEditorCloseTimer);
                    skinEditorCloseTimer = null;
                }
                if (dialog) dialog.removeEventListener('animationend', onAnimEnd);
                modal.classList.remove('active');
                modal.classList.remove('is-closing');
            };

            const onAnimEnd = (e) => {
                if (e.target === dialog) finishClose();
            };

            if (dialog) {
                dialog.addEventListener('animationend', onAnimEnd, { once: true });
            }
            const duration = (typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) ? 0 : 180;
            skinEditorCloseTimer = setTimeout(finishClose, duration);
            return true;
        }

        function bringFloatingWindowToFront(windowName) {
            const skinModal = document.getElementById('skinEditorModal');
            const textureModal = document.getElementById('textureImageEditorModal');

            if (windowName === 'skin-editor') {
                if (skinModal) skinModal.style.zIndex = '2400';
                if (textureModal) textureModal.style.zIndex = '2000';
                activeFloatingWindow = 'skin-editor';
            } else if (windowName === 'texture-editor') {
                if (textureModal) textureModal.style.zIndex = '2400';
                if (skinModal) skinModal.style.zIndex = '2000';
                activeFloatingWindow = 'texture-editor';
            }
        }

        function openSkinEditorDialog() {
            const modal = document.getElementById('skinEditorModal');
            if (!modal) return false;
            skinEditorCloseToken++;
            if (skinEditorCloseTimer) {
                clearTimeout(skinEditorCloseTimer);
                skinEditorCloseTimer = null;
            }
            modal.classList.remove('is-closing');
            syncSkinEditingAvailabilityUI();
            modal.classList.add('active');
            bringFloatingWindowToFront('skin-editor');
            if (!isSkinEditingWorkspaceReady()) return true;
            updateSkinEditorKeyPills();
            renderSkinEditorParams();
            return true;
        }

        async function openSkinEditorDialogFromToolbar() {
            return openSkinEditorDialog();
        }

        function initSkinEditorDialogUI() {
            // 打开 / 关闭弹窗
            const openBtn = document.getElementById('openSkinEditorBtn');
            const closeBtn = document.getElementById('closeSkinEditorBtn');
            const backdrop = document.getElementById('skinEditorBackdrop');
            const modal = document.getElementById('skinEditorModal');

            const closeSkinEditor = () => closeSkinEditorDialog();
            window.closeSkinEditorDialog = closeSkinEditorDialog;

            if (openBtn && modal) {
                openBtn.onclick = openSkinEditorDialogFromToolbar;
            }
            if (closeBtn && modal) {
                closeBtn.onclick = closeSkinEditor;
            }
            if (backdrop && modal) {
                backdrop.onclick = closeSkinEditor;
            }

            // 绑定可拖拽窗口及折叠/复位行为
            const dialog = document.getElementById('skinEditorDialog');
            const header = document.getElementById('skinEditorHeader');
            const dockBtn = document.getElementById('dockSkinEditorBtn');
            if (dialog) {
                dialog.addEventListener('mousedown', () => {
                    bringFloatingWindowToFront('skin-editor');
                });
            }
            const collapseBtn = document.getElementById('collapseSkinEditorBtn');

            if (dialog && header) {
                let isDraggingWindow = false;
                let dragStartX = 0, dragStartY = 0;
                let dialogStartLeft = 0, dialogStartTop = 0;

                header.addEventListener('mousedown', (e) => {
                    if (e.target.closest('button') || e.target.closest('input')) return;

                    isDraggingWindow = true;
                    dragStartX = e.clientX;
                    dragStartY = e.clientY;

                    const rect = dialog.getBoundingClientRect();
                    dialogStartLeft = rect.left;
                    dialogStartTop = rect.top;

                    dialog.style.left = `${dialogStartLeft}px`;
                    dialog.style.top = `${dialogStartTop}px`;
                    dialog.style.right = 'auto';
                    dialog.style.bottom = 'auto';

                    dialog.classList.add('is-dragging');

                    const onMouseMove = (moveEvent) => {
                        if (!isDraggingWindow) return;
                        const deltaX = moveEvent.clientX - dragStartX;
                        const deltaY = moveEvent.clientY - dragStartY;

                        let nextLeft = dialogStartLeft + deltaX;
                        let nextTop = dialogStartTop + deltaY;

                        const maxLeft = window.innerWidth - 80;
                        const minLeft = -dialog.offsetWidth + 80;
                        const maxTop = window.innerHeight - 50;
                        const minTop = 0;

                        nextLeft = Math.max(minLeft, Math.min(maxLeft, nextLeft));
                        nextTop = Math.max(minTop, Math.min(maxTop, nextTop));

                        dialog.style.left = `${nextLeft}px`;
                        dialog.style.top = `${nextTop}px`;
                    };

                    const onMouseUp = () => {
                        if (isDraggingWindow) {
                            isDraggingWindow = false;
                            dialog.classList.remove('is-dragging');
                        }
                        window.removeEventListener('mousemove', onMouseMove);
                        window.removeEventListener('mouseup', onMouseUp);
                    };

                    window.addEventListener('mousemove', onMouseMove);
                    window.addEventListener('mouseup', onMouseUp);
                    e.preventDefault();
                });

                // 双击标题栏折叠 / 展开
                header.addEventListener('dblclick', (e) => {
                    if (e.target.closest('button')) return;
                    if (collapseBtn) collapseBtn.click();
                });

                // 折叠 / 展开按钮
                if (collapseBtn) {
                    collapseBtn.onclick = () => {
                        const isCollapsed = dialog.classList.toggle('is-collapsed');
                        collapseBtn.textContent = isCollapsed ? '+' : '−';
                        collapseBtn.title = isCollapsed ? '展开窗口' : '折叠窗口';
                    };
                }

                // 恢复靠右停靠默认位置
                if (dockBtn) {
                    dockBtn.onclick = () => {
                        dialog.style.left = 'auto';
                        dialog.style.top = '48px';
                        dialog.style.right = '24px';
                        dialog.style.bottom = 'auto';
                        dialog.style.width = '680px';
                        dialog.style.height = '84vh';
                        dialog.classList.remove('is-collapsed');
                        if (collapseBtn) {
                            collapseBtn.textContent = '−';
                            collapseBtn.title = '折叠/展开窗口';
                        }
                    };
                }
            }

            // 判定提示动态演示开关
            const previewJudgementToggle = document.getElementById('previewJudgementToggle');
            if (previewJudgementToggle) {
                previewJudgementToggle.checked = isPreviewJudgementActive;
                previewJudgementToggle.onchange = (e) => {
                    setPreviewJudgementActive(e.target.checked);
                };
            }

            // 连击提示图编辑器内预览开关
            const comboburstPreviewToggle = document.getElementById('comboburstPreviewToggle');
            if (comboburstPreviewToggle) {
                comboburstPreviewToggle.checked = isComboburstPreviewEnabled;
                comboburstPreviewToggle.onchange = (e) => {
                    setComboburstPreviewEnabled(e.target.checked);
                };
            }

            // 故事板渲染开关
            const storyboardToggle = document.getElementById('storyboardToggle');
            if (storyboardToggle) {
                storyboardToggle.checked = enableStoryboard;
                storyboardToggle.onchange = (e) => {
                    enableStoryboard = e.target.checked;
                    if (storyboardPlaybackState) {
                        storyboardPlaybackState.compositeDirty = true;
                    }
                    drawFrame();
                };
            }

            // 视频背景渲染开关
            const videoToggle = document.getElementById('videoToggle');
            if (videoToggle) {
                videoToggle.checked = enableVideo;
                videoToggle.onchange = (e) => {
                    enableVideo = e.target.checked;
                    if (storyboardPlaybackState) {
                        storyboardPlaybackState.compositeDirty = true;
                        if (!enableVideo && storyboardPlaybackState.video && storyboardPlaybackState.video.element) {
                            try { storyboardPlaybackState.video.element.pause(); } catch (_) {}
                        } else if (enableVideo) {
                            ensureStoryboardVideoLoaded(storyboardPlaybackState, true);
                            syncStoryboardVideoToTime(getPlaybackTimeSeconds() * 1000, isPlaying);
                        }
                    }
                    drawFrame();
                };
            }

            // 顶部菜单按钮与下拉容器
            const fileDropdown = document.getElementById('fileDropdownWrapper');
            const fileMenuBtn = document.getElementById('fileMenuBtn');
            const exportDropdown = document.getElementById('exportDropdownWrapper');
            const exportSkinBtn = document.getElementById('exportSkinBtn');
            const otherDropdown = document.getElementById('otherDropdownWrapper');
            const otherMenuBtn = document.getElementById('otherMenuBtn');
            const exportOskBtn = document.getElementById('exportOskBtn');
            const exportZipBtn = document.getElementById('exportZipBtn');
            const modalExportOskBtn = document.getElementById('modalExportOskBtn');
            const modalExportZipBtn = document.getElementById('modalExportZipBtn');

            const topbarDropdowns = [
                { button: fileMenuBtn, wrapper: fileDropdown },
                { button: ui.diffBtn, wrapper: ui.diffDropdown },
                { button: exportSkinBtn, wrapper: exportDropdown },
                { button: otherMenuBtn, wrapper: otherDropdown }
            ].filter(item => item.button && item.wrapper);

            const closeTopbarDropdowns = (exceptWrapper = null) => {
                topbarDropdowns.forEach(({ wrapper }) => {
                    if (wrapper !== exceptWrapper) wrapper.classList.remove('open');
                });
            };

            topbarDropdowns.forEach(({ button, wrapper }) => {
                button.onclick = (e) => {
                    e.stopPropagation();
                    const shouldOpen = !wrapper.classList.contains('open');
                    closeTopbarDropdowns();
                    wrapper.classList.toggle('open', shouldOpen);
                };
            });

            window.addEventListener('click', () => closeTopbarDropdowns());

            // 初始化谱面难度下拉列表
            renderDiffDropdownMenu();

            if (exportOskBtn) exportOskBtn.onclick = () => requestAndExportSkin('osk');
            if (exportZipBtn) exportZipBtn.onclick = () => requestAndExportSkin('zip');
            if (modalExportOskBtn) modalExportOskBtn.onclick = () => requestAndExportSkin('osk');
            if (modalExportZipBtn) modalExportZipBtn.onclick = () => requestAndExportSkin('zip');
            const useDefaultSkinBtn = document.getElementById('useDefaultSkinBtn');
            if (useDefaultSkinBtn) useDefaultSkinBtn.onclick = () => startFromDefaultSkin();

            // 搜索过滤与清空
            const searchInput = document.getElementById('paramSearchInput');
            const clearSearchBtn = document.getElementById('clearSearchBtn');
            if (searchInput) {
                searchInput.oninput = (e) => {
                    paramSearchQuery = e.target.value;
                    if (clearSearchBtn) clearSearchBtn.style.display = paramSearchQuery ? 'block' : 'none';
                    renderSkinEditorParams();
                };
            }
            if (clearSearchBtn && searchInput) {
                clearSearchBtn.onclick = () => {
                    searchInput.value = '';
                    paramSearchQuery = '';
                    clearSearchBtn.style.display = 'none';
                    renderSkinEditorParams();
                };
            }

            // Tab 标签页切换
            const tabs = document.querySelectorAll('#skinEditorTabs .tab-btn');
            tabs.forEach(btn => {
                btn.onclick = () => switchEditorTab(btn.dataset.tab);
            });

            // 动态初始化键数切换按钮 (仅展示实际从 skin.ini 中读取到的键位配置)
            updateSkinEditorKeyPills();

            // 重做、撤回与恢复初始皮肤按钮 (顶部编辑菜单与详细设置弹窗底部)
            const canvasRedoBtn = document.getElementById('canvasRedoBtn');
            const canvasUndoBtn = document.getElementById('canvasUndoBtn');
            const modalUndoBtn = document.getElementById('modalUndoBtn');
            if (canvasRedoBtn) canvasRedoBtn.onclick = () => performSkinRedo();
            if (canvasUndoBtn) canvasUndoBtn.onclick = () => performSkinUndo();
            if (modalUndoBtn) modalUndoBtn.onclick = () => performSkinUndo();
            updateUndoButtonState();

            const sidebarRevertBtn = document.getElementById('sidebarRevertSkinBtn');
            const modalRevertBtn = document.getElementById('modalRevertSkinBtn');
            if (sidebarRevertBtn) sidebarRevertBtn.onclick = () => revertSkinToInitial();
            if (modalRevertBtn) modalRevertBtn.onclick = () => revertSkinToInitial();

            // 重置当前组默认值与复制 raw skin.ini
            const resetBtn = document.getElementById('resetSkinParamsBtn');
            if (resetBtn) {
                resetBtn.onclick = () => {
                    if (confirm(window.I18n.t('确定要将当前分类下的所有参数恢复为推荐默认值吗？'))) {
                        recordSkinUndoBeforeChange('恢复分类默认值');
                        const items = SKIN_INI_PARAM_SCHEMA.filter(p => p.tab === activeEditorTab && !p.virtual);
                        for (const p of items) onParamChange(p.key, p.default);
                        continuousActionActive = false;
                        renderSkinEditorParams();
                    }
                };
            }

            const copyRawBtn = document.getElementById('copyRawIniBtn');
            if (copyRawBtn) {
                copyRawBtn.onclick = async () => {
                    const txt = generateSkinIniText();
                    try {
                        await navigator.clipboard.writeText(txt);
                        showToast('复制成功', '已将生成的完整 skin.ini 内容复制到剪贴板');
                    } catch (_) {
                        showToast('请手动复制', '浏览器剪贴板权限受限，请在下方全选文本');
                    }
                };
            }

            initSkinEditorCardControlsUI();
            if (typeof initHitsoundEditorUI === 'function') initHitsoundEditorUI();
            if (typeof initComboburstEditorUI === 'function') initComboburstEditorUI();
        }

        function initSkinEditorUI() {
            initSkinEditorDialogUI();
            initAnimationTextureEditorUI();
            initTextureUploadUI();
            initTextureExistingPickerUI();
            initTextureImageEditorUI();
            initCanvasEditorUI();
            initSkinEditorShortcutsUI();
        }
// --- END ui/editor-dialog.js ---

// --- BEGIN ui/animation-editor.js ---
// ============================================================================
// animation-editor.js - 多帧动态贴图制作、预览、排序与应用
// 依赖：parser/skin-assets.js、ui/history.js、ui/texture-controls.js
// ============================================================================

        function initAnimationTextureEditorUI() {
            // ===== 动态贴图序列制作 / 上传系统 (多帧动画) =====
            let animEditorState = {
                targetParamKey: null,
                targetKey: null,
                targetFilename: null,
                cleanRawBase: '',
                targetBase: '',
                spec: '1x',
                frames: [],
                fps: 30,
                isPlaying: true,
                currentPreviewFrameIdx: 0,
                previewTimer: null
            };

            function getTextureKeyAliases(targetBase, pKey) {
                const aliases = new Set();
                const tb = String(targetBase || '').toLowerCase().trim();
                const pk = String(pKey || '').toLowerCase().trim();
                if (tb) aliases.add(tb);
                if (pk) aliases.add(pk);

                if (pk === 'stagehint' || tb === 'stagehint' || tb === 'mania-stage-hint') {
                    aliases.add('mania-stage-hint');
                    aliases.add('stagehint');
                    aliases.add('hittarget');
                }
                if (pk === 'stagelight' || tb === 'stagelight' || tb === 'mania-stage-light') {
                    aliases.add('mania-stage-light');
                    aliases.add('stagelight');
                }
                if (pk === 'stagebottom' || tb === 'stagebottom' || tb === 'mania-stage-bottom' || tb === 'stage_bottom') {
                    aliases.add('mania-stage-bottom');
                    aliases.add('stagebottom');
                    aliases.add('stage_bottom');
                }
                if (pk === 'stageleft' || tb === 'stageleft' || tb === 'mania-stage-left' || tb === 'stage_left') {
                    aliases.add('mania-stage-left');
                    aliases.add('stageleft');
                    aliases.add('stage_left');
                }
                if (pk === 'stageright' || tb === 'stageright' || tb === 'mania-stage-right' || tb === 'stage_right') {
                    aliases.add('mania-stage-right');
                    aliases.add('stageright');
                    aliases.add('stage_right');
                }
                if (pk === 'lightingn' || (tb === 'lightingn' && pk !== 'lightingl')) {
                    aliases.add('lightingn');
                }
                if (pk === 'lightingl' || (tb === 'lightingl' && pk !== 'lightingn')) {
                    aliases.add('lightingl');
                }
                if (pk === 'hit0' || tb === 'hit0' || tb === 'mania-hit0') {
                    aliases.add('mania-hit0');
                    aliases.add('hit0');
                }
                if (pk === 'hit50' || tb === 'hit50' || tb === 'mania-hit50') {
                    aliases.add('mania-hit50');
                    aliases.add('hit50');
                }
                if (pk === 'hit100' || tb === 'hit100' || tb === 'mania-hit100') {
                    aliases.add('mania-hit100');
                    aliases.add('hit100');
                }
                if (pk === 'hit200' || tb === 'hit200' || tb === 'mania-hit200') {
                    aliases.add('mania-hit200');
                    aliases.add('hit200');
                }
                if (pk === 'hit300' || tb === 'hit300' || tb === 'mania-hit300') {
                    aliases.add('mania-hit300');
                    aliases.add('hit300');
                }
                if (pk === 'hit300g' || tb === 'hit300g' || tb === 'mania-hit300g' || tb === 'hit300k') {
                    aliases.add('mania-hit300g');
                    aliases.add('hit300g');
                    aliases.add('hit300k');
                }
                return Array.from(aliases);
            }

            function drawAnimPreviewFrame() {
                const canvas = document.getElementById('animPreviewCanvas');
                if (!canvas) return;
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                const frames = animEditorState.frames;
                const countBadge = document.getElementById('animPreviewFrameCount');

                if (!frames || frames.length === 0) {
                    if (countBadge) countBadge.textContent = '0 帧';
                    ctx.save();
                    ctx.fillStyle = '#64748b';
                    ctx.font = '12px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.fillText(window.I18n.t('等待添加帧贴图...'), canvas.width / 2, canvas.height / 2);
                    ctx.restore();
                    return;
                }

                if (animEditorState.currentPreviewFrameIdx >= frames.length) {
                    animEditorState.currentPreviewFrameIdx = 0;
                }
                const curIdx = animEditorState.currentPreviewFrameIdx;
                const curFrame = frames[curIdx];
                if (curFrame && curFrame.img) {
                    const img = curFrame.img;
                    const scale = Math.min((canvas.width - 16) / img.width, (canvas.height - 16) / img.height, 1);
                    const dw = img.width * scale;
                    const dh = img.height * scale;
                    const dx = (canvas.width - dw) / 2;
                    const dy = (canvas.height - dh) / 2;
                    ctx.drawImage(img, dx, dy, dw, dh);
                }
                if (countBadge) {
                    countBadge.textContent = `${curIdx + 1} / ${frames.length} 帧`;
                }
            }

            function startAnimPreview() {
                stopAnimPreview();
                animEditorState.previewTimer = setInterval(() => {
                    if (!animEditorState.isPlaying) return;
                    if (animEditorState.frames && animEditorState.frames.length > 0) {
                        animEditorState.currentPreviewFrameIdx = (animEditorState.currentPreviewFrameIdx + 1) % animEditorState.frames.length;
                        drawAnimPreviewFrame();
                    }
                }, 1000 / Math.max(1, animEditorState.fps));
                drawAnimPreviewFrame();
            }

            function stopAnimPreview() {
                if (animEditorState.previewTimer) {
                    clearInterval(animEditorState.previewTimer);
                    animEditorState.previewTimer = null;
                }
            }

            function updateAnimSpecButtons() {
                const btn1x = document.getElementById('animSpec1xBtn');
                const btn2x = document.getElementById('animSpec2xBtn');
                if (btn1x) btn1x.classList.toggle('active', animEditorState.spec === '1x');
                if (btn2x) btn2x.classList.toggle('active', animEditorState.spec === '2x');
                renderAnimFramesGrid();
            }

            function renderAnimFramesGrid() {
                const emptyState = document.getElementById('animEmptyState');
                const grid = document.getElementById('animFramesGrid');
                const previewPanel = document.getElementById('animPreviewPanel');
                const confirmBtn = document.getElementById('animConfirmBtn');
                const clearAllBtn = document.getElementById('animClearAllBtn');
                const countBadge = document.getElementById('animPreviewFrameCount');

                const frames = animEditorState.frames;
                const totalFrames = frames ? frames.length : 0;

                if (confirmBtn) {
                    confirmBtn.disabled = (totalFrames === 0);
                    confirmBtn.textContent = totalFrames > 0 ? `确认应用动态贴图 (${totalFrames} 帧)` : '确认应用动态贴图 (0 帧)';
                }
                if (clearAllBtn) {
                    clearAllBtn.style.display = totalFrames > 0 ? 'inline-flex' : 'none';
                }
                if (countBadge) {
                    countBadge.textContent = `${totalFrames} 帧`;
                }

                if (!frames || totalFrames === 0) {
                    if (emptyState) emptyState.style.display = 'flex';
                    if (grid) {
                        grid.style.display = 'none';
                        grid.innerHTML = '';
                    }
                    if (previewPanel) previewPanel.style.display = 'none';
                    drawAnimPreviewFrame();
                    return;
                }

                if (emptyState) emptyState.style.display = 'none';
                if (grid) grid.style.display = 'grid';
                if (previewPanel) previewPanel.style.display = 'flex';
                grid.innerHTML = '';

                const cleanRawBase = animEditorState.cleanRawBase;
                const is2x = (animEditorState.spec === '2x');
                const suffix = is2x ? '@2x.png' : '.png';

                frames.forEach((frame, idx) => {
                    const card = document.createElement('div');
                    card.className = 'anim-frame-card';

                    const exportName = `${cleanRawBase}-${idx}${suffix}`;
                    const kb = (frame.size / 1024).toFixed(1);

                    card.innerHTML = `
                        <div class="anim-frame-header">
                            <span class="anim-frame-badge">第 ${idx} 帧</span>
                            <span class="anim-frame-export-name" title="${exportName}">${exportName}</span>
                            <button type="button" class="anim-frame-delete-btn" title="删除此帧">✕</button>
                        </div>
                        <div class="anim-frame-thumb-box">
                            <img src="${frame.blobUrl}" alt="Frame ${idx}">
                        </div>
                        <div class="anim-frame-meta">
                            <span class="anim-frame-name" title="${frame.name}">${frame.name}</span>
                            <span class="anim-frame-dim">${frame.width}×${frame.height} (${kb} KB)</span>
                        </div>
                        <div class="anim-frame-move-btns">
                            <button type="button" class="anim-move-btn anim-move-left" title="向前移动一帧" ${idx === 0 ? 'disabled' : ''}>◀ 前移</button>
                            <button type="button" class="anim-move-btn anim-move-right" title="向后移动一帧" ${idx === frames.length - 1 ? 'disabled' : ''}>后移 ▶</button>
                        </div>
                    `;

                    const moveLeftBtn = card.querySelector('.anim-move-left');
                    const moveRightBtn = card.querySelector('.anim-move-right');
                    const deleteBtn = card.querySelector('.anim-frame-delete-btn');

                    if (moveLeftBtn && idx > 0) {
                        moveLeftBtn.onclick = () => {
                            const temp = frames[idx];
                            frames[idx] = frames[idx - 1];
                            frames[idx - 1] = temp;
                            renderAnimFramesGrid();
                        };
                    }
                    if (moveRightBtn && idx < frames.length - 1) {
                        moveRightBtn.onclick = () => {
                            const temp = frames[idx];
                            frames[idx] = frames[idx + 1];
                            frames[idx + 1] = temp;
                            renderAnimFramesGrid();
                        };
                    }
                    if (deleteBtn) {
                        deleteBtn.onclick = () => {
                            if (frame.blobUrl) {
                                try { URL.revokeObjectURL(frame.blobUrl); } catch (_) {}
                            }
                            frames.splice(idx, 1);
                            renderAnimFramesGrid();
                        };
                    }

                    grid.appendChild(card);
                });

                drawAnimPreviewFrame();
            }

            openAnimTextureEditor = function(param1, param2 = null, param3 = null, defaultSpec = '1x') {
                stopAnimPreview();

                if (animEditorState.frames && animEditorState.frames.length > 0) {
                    animEditorState.frames.forEach(f => {
                        if (f.blobUrl) {
                            try { URL.revokeObjectURL(f.blobUrl); } catch (_) {}
                        }
                    });
                }

                let targetFilename = (typeof param1 === 'string' && param1.includes('.')) ? param1 : (param3 || param1);
                let targetParamKey = param3 || (param1 && !param1.includes('.') ? param1 : null) || param2;
                let targetKey = param2 || targetParamKey;

                if (!isTextureAnimationSupported(targetParamKey, targetKey, targetFilename)) {
                    showToast('不支持动态贴图', '该贴图在 osu!stable 中只支持静态图片。');
                    return;
                }

                let rawName = targetFilename;
                if (!rawName || isDummyBlankName(rawName)) {
                    rawName = targetParamKey || targetKey || 'texture';
                }
                let cleanBase = String(rawName).replace(/\.[^/.]+$/, '').replace(/@2x/i, '').replace(/-\d+$/, '');
                if (!cleanBase || isDummyBlankName(cleanBase)) {
                    cleanBase = targetParamKey || targetKey || 'texture';
                }

                // 需求重点：打开窗口时初始状态为空
                animEditorState = {
                    targetParamKey: targetParamKey || null,
                    targetKey: targetKey || null,
                    targetFilename: targetFilename || null,
                    cleanRawBase: cleanBase,
                    targetBase: cleanBase.toLowerCase(),
                    spec: (defaultSpec === '2x') ? '2x' : '1x',
                    frames: [],
                    fps: 30,
                    isPlaying: true,
                    currentPreviewFrameIdx: 0,
                    previewTimer: null
                };

                const titleTextEl = document.getElementById('animTextureTitleText');
                const targetLabelEl = document.getElementById('animTextureTargetLabel');
                let friendlyName = targetParamKey || targetKey || cleanBase;
                const schemaItem = (typeof SKIN_INI_PARAM_SCHEMA !== 'undefined') && SKIN_INI_PARAM_SCHEMA.find(item => item.key === friendlyName);
                const displayName = (schemaItem && schemaItem.zhName) ? `${schemaItem.zhName} (${cleanBase})` : cleanBase;
                if (titleTextEl) {
                    titleTextEl.textContent = `动态贴图序列管理 - ${displayName}`;
                }
                if (targetLabelEl) {
                    targetLabelEl.textContent = `目标贴图: ${cleanBase}`;
                }

                const fpsRange = document.getElementById('animFpsRange');
                const fpsVal = document.getElementById('animFpsVal');
                if (fpsRange) fpsRange.value = 30;
                if (fpsVal) fpsVal.textContent = '30';

                const playBtn = document.getElementById('animPlayToggleBtn');
                if (playBtn) playBtn.textContent = window.I18n.t('⏸ 暂停');

                updateAnimSpecButtons();
                renderAnimFramesGrid();

                const modal = document.getElementById('animTextureModal');
                if (modal) modal.style.display = 'flex';

                startAnimPreview();
            };

            closeAnimTextureEditor = function() {
                stopAnimPreview();
                if (animEditorState.frames && animEditorState.frames.length > 0) {
                    animEditorState.frames.forEach(f => {
                        if (f.blobUrl) {
                            try { URL.revokeObjectURL(f.blobUrl); } catch (_) {}
                        }
                    });
                }
                animEditorState.frames = [];
                const singleInput = document.getElementById('animSingleFrameInput');
                const batchInput = document.getElementById('animBatchFrameInput');
                if (singleInput) singleInput.value = '';
                if (batchInput) batchInput.value = '';

                const modal = document.getElementById('animTextureModal');
                if (modal) modal.style.display = 'none';
            };

            async function handleAnimSingleAdd(file) {
                if (!file) return;
                try {
                    const arrayBuffer = await file.arrayBuffer();
                    const blob = new Blob([arrayBuffer]);
                    const blobUrl = URL.createObjectURL(blob);
                    const img = await new Promise((resolve, reject) => {
                        const i = new Image();
                        i.onload = () => resolve(i);
                        i.onerror = () => reject(new Error('图片加载失败'));
                        i.src = blobUrl;
                    });

                    animEditorState.frames.push({
                        file,
                        arrayBuffer,
                        img,
                        blobUrl,
                        name: file.name,
                        width: img.width,
                        height: img.height,
                        size: file.size
                    });

                    renderAnimFramesGrid();
                    showToast('添加单帧成功', `已添加第 ${animEditorState.frames.length - 1} 帧: ${file.name}`);
                } catch (err) {
                    console.error('单帧添加失败', err);
                    showToast('添加失败', err.message || '图片文件无法解析');
                }
            }

            async function handleAnimBatchAdd(fileList) {
                if (!fileList || fileList.length === 0) return;
                try {
                    const sortedFiles = Array.from(fileList);
                    // 需求重点：贴图顺序由上传的所有贴图的名称顺序决定（自然数/字母升序，如 -0, -1, -2 或 1, 2, 10）
                    sortedFiles.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));

                    let addedCount = 0;
                    for (const file of sortedFiles) {
                        try {
                            const arrayBuffer = await file.arrayBuffer();
                            const blob = new Blob([arrayBuffer]);
                            const blobUrl = URL.createObjectURL(blob);
                            const img = await new Promise((resolve, reject) => {
                                const i = new Image();
                                i.onload = () => resolve(i);
                                i.onerror = () => reject(new Error('图片加载失败'));
                                i.src = blobUrl;
                            });

                            animEditorState.frames.push({
                                file,
                                arrayBuffer,
                                img,
                                blobUrl,
                                name: file.name,
                                width: img.width,
                                height: img.height,
                                size: file.size
                            });
                            addedCount++;
                        } catch (frameErr) {
                            console.warn(`跳过无法解析的图片: ${file.name}`, frameErr);
                        }
                    }

                    renderAnimFramesGrid();
                    showToast('批量添加完成', `已按文件名顺序添加 ${addedCount} 帧贴图`);
                } catch (err) {
                    console.error('批量添加失败', err);
                    showToast('批量添加失败', err.message || '未知错误');
                }
            }

            async function confirmApplyAnimTexture() {
                if (!animEditorState.frames || animEditorState.frames.length === 0) {
                    showToast('无法应用', '请至少添加 1 张动画贴图帧');
                    return;
                }

                const is2x = (animEditorState.spec === '2x');
                const cleanRawBase = animEditorState.cleanRawBase;
                const targetBase = animEditorState.targetBase;
                const pKey = animEditorState.targetParamKey || animEditorState.targetKey;
                const appliedCount = animEditorState.frames.length;

                recordSkinUndoBeforeChange(`替换动态贴图: ${cleanRawBase} (${appliedCount} 帧)`);
                continuousActionActive = false;

                const curExt = is2x ? '@2x.png' : '.png';
                const oppExt = is2x ? '.png' : '@2x.png';

                // 获取该贴图参数的所有标准 osu! mania 别名与变体
                const allAliases = getTextureKeyAliases(targetBase, pKey);

                // 1. 对所有别名统一重置与注入贴图资产表
                for (const alias of allAliases) {
                    const animEntry = getOrCreateSkinAssetEntry(skinImageStore, alias);
                    const fallbackEntry = getOrCreateSkinAssetEntry(skinFallbackImageStore, alias);
                    if (is2x) {
                        animEntry.anim2x = [];
                        fallbackEntry.anim2x = [];
                    } else {
                        animEntry.anim1x = [];
                        fallbackEntry.anim1x = [];
                        // 若上传 1x 动画，清除可能导致冲突的旧 2x 帧与静态图
                        animEntry.anim2x = [];
                        fallbackEntry.anim2x = [];
                        animEntry.static2x = null;
                        fallbackEntry.static2x = null;
                    }

                    animEditorState.frames.forEach((frame, idx) => {
                        frame.img._is2x = is2x;
                        frame.img._isRootLevel = true;

                        if (is2x) {
                            animEntry.anim2x[idx] = frame.img;
                            fallbackEntry.anim2x[idx] = frame.img;
                        } else {
                            animEntry.anim1x[idx] = frame.img;
                            fallbackEntry.anim1x[idx] = frame.img;
                        }

                        const frameKey = `${alias}-${idx}`;
                        saveSkinAssetToStore(skinImageStore, frameKey, frame.img, is2x, true, true);
                        saveSkinAssetToStore(skinFallbackImageStore, frameKey, frame.img, is2x, true, true);

                        userReplacedTextures.set(`${alias}-${idx}${curExt}`, frame.arrayBuffer);
                        userReplacedTextures.delete(`${alias}-${idx}${oppExt}`);
                    });

                    if (animEditorState.frames[0] && animEditorState.frames[0].img) {
                        const frame0Img = animEditorState.frames[0].img;
                        if (is2x) {
                            animEntry.static2x = frame0Img;
                            fallbackEntry.static2x = frame0Img;
                        } else {
                            animEntry.static1x = frame0Img;
                            fallbackEntry.static1x = frame0Img;
                        }
                    }
                }

                // 2. 将主原始命名也写入用户替换字典
                animEditorState.frames.forEach((frame, idx) => {
                    const exportFilename = `${cleanRawBase}-${idx}${curExt}`;
                    userReplacedTextures.set(exportFilename, frame.arrayBuffer);
                    userReplacedTextures.delete(`${cleanRawBase}-${idx}${oppExt}`);
                });

                // 3. 清理超出新帧数的多余旧帧缓存 (防止旧帧多于新帧产生幽灵遗留)
                for (let i = animEditorState.frames.length; i < 64; i++) {
                    for (const alias of allAliases) {
                        skinImageStore.delete(`${alias}-${i}`);
                        skinFallbackImageStore.delete(`${alias}-${i}`);
                        userReplacedTextures.delete(`${alias}-${i}.png`);
                        userReplacedTextures.delete(`${alias}-${i}@2x.png`);
                        if (currentSkinZip) {
                            currentSkinZip.remove(`${alias}-${i}.png`);
                            currentSkinZip.remove(`${alias}-${i}@2x.png`);
                        }
                    }
                    userReplacedTextures.delete(`${cleanRawBase}-${i}.png`);
                    userReplacedTextures.delete(`${cleanRawBase}-${i}@2x.png`);
                    if (currentSkinZip) {
                        currentSkinZip.remove(`${cleanRawBase}-${i}.png`);
                        currentSkinZip.remove(`${cleanRawBase}-${i}@2x.png`);
                    }
                }

                // 4. 更新 skin.ini 配置
                if (pKey) {
                    const finalBase = cleanRawBase || targetBase;
                    const curKeys = getActiveKeyCount();
                    let primaryCfg = maniaSkinConfigurations.get(curKeys);
                    if (!primaryCfg) {
                        primaryCfg = ensureManiaConfigForKeys(curKeys);
                        maniaSkinConfigurations.set(curKeys, primaryCfg);
                    }
                    const isTrackNoteParam = /^(NoteImage|HoldNoteHeadImage|HoldNoteBodyImage|HoldNoteTailImage|KeyImageDown|KeyImage)(\d+)/i.test(pKey);
                    if (isTrackNoteParam) {
                        if (!primaryCfg.ImageLookups) primaryCfg.ImageLookups = new Map();
                        primaryCfg[pKey] = finalBase;
                        primaryCfg.ImageLookups.set(pKey, finalBase);
                        primaryCfg.ImageLookups.set(pKey.toLowerCase(), finalBase);
                    } else {
                        for (const [, cfgItem] of maniaSkinConfigurations) {
                            if (!cfgItem.ImageLookups) cfgItem.ImageLookups = new Map();
                            cfgItem[pKey] = finalBase;
                            cfgItem.ImageLookups.set(pKey, finalBase);
                            cfgItem.ImageLookups.set(pKey.toLowerCase(), finalBase);
                        }
                        if (globalSkinImageLookups) {
                            globalSkinImageLookups.set(pKey, finalBase);
                            globalSkinImageLookups.set(pKey.toLowerCase(), finalBase);
                        }
                    }
                    syncParamInputValue(pKey, finalBase);
                }

                closeAnimTextureEditor();
                showToast('动态贴图应用成功', `已成功配置 ${cleanRawBase} 共 ${appliedCount} 帧 ${is2x ? '@2x 高清' : '1x 普通'}动画`);
                drawFrame();
                renderSkinEditorParams();
            }

            // 绑定动态贴图弹窗交互事件
            const animSingleInput = document.getElementById('animSingleFrameInput');
            const animBatchInput = document.getElementById('animBatchFrameInput');

            const animAddSingleBtn = document.getElementById('animAddSingleBtn');
            const animBatchBtn = document.getElementById('animBatchBtn');
            const animEmptyAddBtn = document.getElementById('animEmptyAddBtn');
            const animEmptyBatchBtn = document.getElementById('animEmptyBatchBtn');

            if (animAddSingleBtn && animSingleInput) {
                animAddSingleBtn.onclick = () => {
                    animSingleInput.value = '';
                    animSingleInput.click();
                };
            }
            if (animEmptyAddBtn && animSingleInput) {
                animEmptyAddBtn.onclick = () => {
                    animSingleInput.value = '';
                    animSingleInput.click();
                };
            }
            if (animSingleInput) {
                animSingleInput.onchange = (e) => {
                    const file = e.target.files && e.target.files[0];
                    e.target.value = '';
                    if (file) handleAnimSingleAdd(file);
                };
            }

            if (animBatchBtn && animBatchInput) {
                animBatchBtn.onclick = () => {
                    animBatchInput.value = '';
                    animBatchInput.click();
                };
            }
            if (animEmptyBatchBtn && animBatchInput) {
                animEmptyBatchBtn.onclick = () => {
                    animBatchInput.value = '';
                    animBatchInput.click();
                };
            }
            if (animBatchInput) {
                animBatchInput.onchange = (e) => {
                    if (e.target.files && e.target.files.length > 0) {
                        const files = Array.from(e.target.files);
                        e.target.value = '';
                        handleAnimBatchAdd(files);
                    } else {
                        e.target.value = '';
                    }
                };
            }

            const animSpec1xBtn = document.getElementById('animSpec1xBtn');
            const animSpec2xBtn = document.getElementById('animSpec2xBtn');
            if (animSpec1xBtn) {
                animSpec1xBtn.onclick = () => {
                    animEditorState.spec = '1x';
                    updateAnimSpecButtons();
                };
            }
            if (animSpec2xBtn) {
                animSpec2xBtn.onclick = () => {
                    animEditorState.spec = '2x';
                    updateAnimSpecButtons();
                };
            }

            const animClearAllBtn = document.getElementById('animClearAllBtn');
            if (animClearAllBtn) {
                animClearAllBtn.onclick = () => {
                    if (animEditorState.frames && animEditorState.frames.length > 0) {
                        animEditorState.frames.forEach(f => {
                            if (f.blobUrl) {
                                try { URL.revokeObjectURL(f.blobUrl); } catch (_) {}
                            }
                        });
                        animEditorState.frames = [];
                        renderAnimFramesGrid();
                        showToast('已清空', '所有动画帧贴图已清空');
                    }
                };
            }

            const animCloseBtn = document.getElementById('animTextureCloseBtn');
            const animCancelBtn = document.getElementById('animCancelBtn');
            const animBackdrop = document.getElementById('animTextureBackdrop');
            if (animCloseBtn) animCloseBtn.onclick = closeAnimTextureEditor;
            if (animCancelBtn) animCancelBtn.onclick = closeAnimTextureEditor;
            if (animBackdrop) animBackdrop.onclick = closeAnimTextureEditor;

            const animConfirmBtn = document.getElementById('animConfirmBtn');
            if (animConfirmBtn) animConfirmBtn.onclick = confirmApplyAnimTexture;

            const animPlayToggleBtn = document.getElementById('animPlayToggleBtn');
            if (animPlayToggleBtn) {
                animPlayToggleBtn.onclick = () => {
                    animEditorState.isPlaying = !animEditorState.isPlaying;
                    animPlayToggleBtn.textContent = window.I18n.t(animEditorState.isPlaying ? '⏸ 暂停' : '▶ 播放');
                };
            }

            const animFpsRange = document.getElementById('animFpsRange');
            const animFpsVal = document.getElementById('animFpsVal');
            if (animFpsRange) {
                const updateFpsFill = (v) => {
                    const min = parseFloat(animFpsRange.min) || 5;
                    const max = parseFloat(animFpsRange.max) || 60;
                    const vf = parseFloat(v) || min;
                    const pct = ((vf - min) / (max - min)) * 100;
                    animFpsRange.style.setProperty('--slider-pct', `${pct}%`);
                };
                updateFpsFill(animFpsRange.value);
                animFpsRange.oninput = (e) => {
                    updateFpsFill(e.target.value);
                    const fps = parseInt(e.target.value, 10) || 30;
                    animEditorState.fps = fps;
                    if (animFpsVal) animFpsVal.textContent = `${fps} fps`;
                    if (animEditorState.isPlaying) {
                        startAnimPreview();
                    }
                };
            }

        }
// --- END ui/animation-editor.js ---

// --- BEGIN ui/texture-upload.js ---
// ============================================================================
// texture-upload.js - 单张贴图上传、1x/@2x 规格选择与替换应用
// 依赖：parser/skin-assets.js、ui/history.js、ui/texture-controls.js
// ============================================================================

        function initTextureUploadUI() {
            // ===== 贴图上传规格选择弹窗管理系统 (1x 普通贴图 vs @2x 高清贴图) =====
            let pendingTextureUpload = null;
            let selectedTextureSpec = '1x';

            function updateTextureUploadSpecCards() {
                const card1x = document.getElementById('specCard1x');
                const card2x = document.getElementById('specCard2x');
                const cardAnim = document.getElementById('specCardAnim');
                if (card1x) card1x.classList.toggle('selected', selectedTextureSpec === '1x');
                if (card2x) card2x.classList.toggle('selected', selectedTextureSpec === '2x');
                if (cardAnim) cardAnim.classList.toggle('selected', selectedTextureSpec === 'anim');
            }

            function openTextureUploadModal() {
                if (!pendingTextureUpload) return;
                const modal = document.getElementById('textureUploadModal');
                if (!modal) return;

                const p = pendingTextureUpload;
                const previewImg = document.getElementById('textureUploadPreviewImg');
                if (previewImg) previewImg.src = p.blobUrl;

                const targetLabel = document.getElementById('textureUploadTargetLabel');
                if (targetLabel) {
                    let friendlyName = p.targetParamKey || p.targetKey || p.cleanRawBase;
                    const schemaItem = (typeof SKIN_INI_PARAM_SCHEMA !== 'undefined') && SKIN_INI_PARAM_SCHEMA.find(item => item.key === friendlyName);
                    if (schemaItem && schemaItem.zhName) {
                        targetLabel.textContent = `${schemaItem.zhName} (${p.cleanRawBase})`;
                    } else {
                        targetLabel.textContent = p.cleanRawBase;
                    }
                }

                const fileNameEl = document.getElementById('textureUploadFileName');
                if (fileNameEl) fileNameEl.textContent = p.file.name;

                const dimEl = document.getElementById('textureUploadFileSizeDim');
                if (dimEl) {
                    const kb = (p.file.size / 1024).toFixed(1);
                    dimEl.textContent = `${p.img.width} × ${p.img.height} px (${kb} KB)`;
                }

                const file1xEl = document.getElementById('specFileName1x');
                if (file1xEl) file1xEl.textContent = `导出文件名: ${p.cleanRawBase}.png`;

                const file2xEl = document.getElementById('specFileName2x');
                if (file2xEl) file2xEl.textContent = `导出文件名: ${p.cleanRawBase}@2x.png`;

                const fileAnimEl = document.getElementById('specFileNameAnim');
                if (fileAnimEl) fileAnimEl.textContent = `制作多帧序列: ${p.cleanRawBase}-0.png, ${p.cleanRawBase}-1.png...`;

                const animationSupported = isTextureAnimationSupported(
                    p.targetParamKey,
                    p.targetKey,
                    p.targetFilename || p.cleanRawBase
                );
                const animCard = document.getElementById('specCardAnim');
                if (animCard) {
                    animCard.style.display = animationSupported ? '' : 'none';
                    animCard.setAttribute('aria-hidden', animationSupported ? 'false' : 'true');
                }

                updateTextureUploadSpecCards();
                modal.style.display = 'flex';
            }

            function closeTextureUploadModal() {
                const modal = document.getElementById('textureUploadModal');
                if (modal) modal.style.display = 'none';
                if (pendingTextureUpload && pendingTextureUpload.blobUrl) {
                    try { URL.revokeObjectURL(pendingTextureUpload.blobUrl); } catch (_) { }
                }
                pendingTextureUpload = null;
                const input = document.getElementById('textureReplaceInput');
                if (input) input.value = '';
            }

            async function confirmTextureUpload() {
                if (!pendingTextureUpload) return;
                const p = pendingTextureUpload;
                const is2x = (selectedTextureSpec === '2x');
                closeTextureUploadModal();

                await applyUploadedTexture(
                    p.file,
                    p.arrayBuffer,
                    p.img,
                    is2x,
                    p.targetFilename,
                    p.targetKey,
                    p.targetParamKey,
                    p.targetColIndex
                );
            }

            async function applyUploadedTexture(file, arrayBuffer, img, is2x, targetFilename, targetKey, targetParamKey, targetColIndex, options = {}) {
                const shouldRecordUndo = options.recordUndo !== false;
                const shouldNotify = options.notify !== false;
                const shouldRefresh = options.refresh !== false;
                try {
                    img._is2x = is2x;

                    const curKeys = getActiveKeyCount();
                    let trackCol = (targetColIndex != null && !isNaN(targetColIndex)) ? parseInt(targetColIndex, 10) : null;
                    let isTrackNote = false;
                    let noteType = 'note'; // 'note' | 'head' | 'body' | 'tail' | 'key' | 'keydown'

                    const pKey = targetParamKey || targetKey || '';

                    // 防呆守卫：绝不允许把「贴图名」写进非贴图参数（如 LightPosition / HitPosition
                    // 这类数值、位置参数），否则会直接污染 skin.ini（历史上画布「替换贴图」传错
                    // paramKey 就会写出 `LightPosition: mylight` 这种脏数据，并让画布发光位置失效）。
                    // 例外：ScorePrefix / ComboPrefix 是「字体前缀」参数，字形贴图上传时会被显式传进来，
                    //       它们本就不写回 cfg，而是通过字形 ini 键 (score-0 等) 生效，故必须放行。
                    const schemaEntry = (typeof SKIN_INI_PARAM_SCHEMA !== 'undefined')
                        ? SKIN_INI_PARAM_SCHEMA.find(x => x.key === pKey)
                        : null;
                    const isFontPrefixParam = (pKey === 'ScorePrefix' || pKey === 'ComboPrefix' || pKey.startsWith('Font_'));
                    if (schemaEntry && schemaEntry.type !== 'texture' && !isFontPrefixParam) {
                        console.warn(`[替换贴图] 参数 ${pKey} 不是贴图参数，已拒绝写入，避免污染 skin.ini`);
                        showToast('无法替换贴图', `「${schemaEntry.zhName || pKey}」是数值 / 位置参数，不能写入贴图名，请改用对应的贴图参数卡片。`);
                        return false;
                    }

                    const mTrackNote = pKey.match(/^(NoteImage|HoldNoteHeadImage|HoldNoteBodyImage|HoldNoteTailImage|KeyImageDown|KeyImage)(\d+)([HLTD])?$/i);
                    if (mTrackNote) {
                        isTrackNote = true;
                        if (trackCol == null) trackCol = parseInt(mTrackNote[2], 10);
                        const prefixLow = mTrackNote[1].toLowerCase();
                        const suffix = (mTrackNote[3] || '').toUpperCase();
                        if (prefixLow.startsWith('holdnotehead') || suffix === 'H') noteType = 'head';
                        else if (prefixLow.startsWith('holdnotebody') || suffix === 'L') noteType = 'body';
                        else if (prefixLow.startsWith('holdnotetail') || suffix === 'T') noteType = 'tail';
                        else if (prefixLow.startsWith('keyimagedown') || suffix === 'D') noteType = 'keydown';
                        else if (prefixLow.startsWith('keyimage')) noteType = 'key';
                        else noteType = 'note';
                    } else if (trackCol != null) {
                        if (targetKey === LML.NoteImage || pKey.startsWith('NoteImage')) {
                            isTrackNote = true;
                            noteType = 'note';
                        } else if (targetKey === LML.HoldNoteHeadImage || pKey.startsWith('HoldNoteHeadImage')) {
                            isTrackNote = true;
                            noteType = 'head';
                        } else if (targetKey === LML.HoldNoteBodyImage || pKey.startsWith('HoldNoteBodyImage')) {
                            isTrackNote = true;
                            noteType = 'body';
                        } else if (targetKey === LML.HoldNoteTailImage || pKey.startsWith('HoldNoteTailImage')) {
                            isTrackNote = true;
                            noteType = 'tail';
                        } else if (targetKey === LML.KeyImage || pKey.startsWith('KeyImage')) {
                            isTrackNote = true;
                            noteType = 'key';
                        } else if (targetKey === LML.KeyImageDown || pKey.startsWith('KeyImageDown')) {
                            isTrackNote = true;
                            noteType = 'keydown';
                        }
                    }

                    let canonicalParamKey = pKey;
                    let paramAliases = [pKey];

                    if (isTrackNote && trackCol != null) {
                        if (noteType === 'note') {
                            canonicalParamKey = `NoteImage${trackCol}`;
                            paramAliases = [`NoteImage${trackCol}`];
                        } else if (noteType === 'head') {
                            canonicalParamKey = `NoteImage${trackCol}H`;
                            paramAliases = [`NoteImage${trackCol}H`, `HoldNoteHeadImage${trackCol}`];
                        } else if (noteType === 'body') {
                            canonicalParamKey = `NoteImage${trackCol}L`;
                            paramAliases = [`NoteImage${trackCol}L`, `HoldNoteBodyImage${trackCol}`];
                        } else if (noteType === 'tail') {
                            canonicalParamKey = `NoteImage${trackCol}T`;
                            paramAliases = [`NoteImage${trackCol}T`, `HoldNoteTailImage${trackCol}`];
                        } else if (noteType === 'key') {
                            canonicalParamKey = `KeyImage${trackCol}`;
                            paramAliases = [`KeyImage${trackCol}`];
                        } else if (noteType === 'keydown') {
                            canonicalParamKey = `KeyImage${trackCol}D`;
                            paramAliases = [`KeyImage${trackCol}D`, `KeyImageDown${trackCol}`, `KeyImage${trackCol}Down`];
                        }
                    }

                    const rawFileBase = file.name.replace(/\.[^/.]+$/, '').replace(/@2x/i, '');
                    let cleanRawBase;
                    let targetBase;

                    if (isTrackNote && trackCol != null) {
                        // 轨道贴图隔离核心逻辑:
                        // 必须确保该轨道的贴图名称独属于该轨道 (如 note_col1, note_col2 等)，
                        // 即使上传的文件名或者原有贴图与其他轨道重名 (如都叫 note.png 或 mania-note1)，
                        // 也绝不覆盖其他轨道正在引用的贴图或共享默认贴图！
                        const colRegex = new RegExp(`(?:col|track|轨)[-_]?${trackCol + 1}\\b`, 'i');
                        let base = rawFileBase;
                        if (!colRegex.test(base)) {
                            if (noteType === 'head' && !base.toLowerCase().endsWith('h')) {
                                base = `${base}_col${trackCol + 1}H`;
                            } else if (noteType === 'body' && !base.toLowerCase().endsWith('l')) {
                                base = `${base}_col${trackCol + 1}L`;
                            } else if (noteType === 'tail' && !base.toLowerCase().endsWith('t')) {
                                base = `${base}_col${trackCol + 1}T`;
                            } else if (noteType === 'keydown' && !base.toLowerCase().endsWith('d')) {
                                base = `${base}_col${trackCol + 1}D`;
                            } else {
                                base = `${base}_col${trackCol + 1}`;
                            }
                        }
                        cleanRawBase = base;
                        targetBase = base.toLowerCase();
                    } else {
                        const targetRawName = targetFilename || file.name;
                        cleanRawBase = targetRawName.replace(/\.[^/.]+$/, '').replace(/@2x/i, '');
                        targetBase = cleanRawBase.toLowerCase();
                    }

                    const exportFilename = is2x ? `${cleanRawBase}@2x.png` : `${cleanRawBase}.png`;
                    const exportFilenameLower = is2x ? `${targetBase}@2x.png` : `${targetBase}.png`;
                    const curExt = is2x ? '@2x.png' : '.png';
                    const oppExt = is2x ? '.png' : '@2x.png';
                    const replacementParam = {
                        key: canonicalParamKey,
                        _trackLookup: targetKey,
                        _trackCol: isTrackNote && trackCol != null ? trackCol : null
                    };
                    const replacement = typeof prepareTextureReplacement === 'function'
                        ? prepareTextureReplacement(replacementParam, curKeys, exportFilename)
                        : null;

                    if (shouldRecordUndo) {
                        recordSkinUndoBeforeChange(`替换贴图: ${exportFilename}`, { force: true });
                        continuousActionActive = false;
                    }
                    if (isTrackNote && trackCol != null && noteType === 'key') {
                        preserveTrackKeyImageDownBeforeKeyImageEdit(curKeys, trackCol, { syncInput: true });
                    }
                    preserveHoldHeadsBeforeNoteEdit(curKeys, {
                        key: canonicalParamKey,
                        _trackLookup: noteType === 'note' ? LML.NoteImage : null,
                        _trackCol: isTrackNote && noteType === 'note' ? trackCol : null
                    }, { syncInput: true });

                    const keysToUpdate = new Set();
                    keysToUpdate.add(targetBase);

                    if (isTrackNote && trackCol != null) {
                        // 关键隔离: 仅更新属于当前轨道的别名，严禁添加全局/共享通用 key (如 'noteimage', 'mania-note1' 等)
                        for (const a of paramAliases) {
                            keysToUpdate.add(a.toLowerCase());
                        }
                    } else {
                        if (targetFilename) {
                            keysToUpdate.add(targetFilename.replace(/\.[^/.]+$/, '').replace(/@2x/i, '').toLowerCase());
                        }
                        if (targetKey) {
                            keysToUpdate.add(String(targetKey).toLowerCase());
                        }
                        if (targetParamKey) {
                            keysToUpdate.add(String(targetParamKey).toLowerCase());
                        }

                        // 特殊映射与别名 (StageLeft / StageRight / StageBottom / StageHint / StageLight 等)
                        if (pKey === 'StageLeft' || targetBase === 'mania-stage-left' || targetBase === 'stageleft') {
                            keysToUpdate.add('mania-stage-left');
                            keysToUpdate.add('stageleft');
                            keysToUpdate.add('stage_left');
                            for (let k = 0; k < 18; k++) keysToUpdate.add(`stageleft${k}`);
                        } else if (pKey === 'StageRight' || targetBase === 'mania-stage-right' || targetBase === 'stageright') {
                            keysToUpdate.add('mania-stage-right');
                            keysToUpdate.add('stageright');
                            keysToUpdate.add('stage_right');
                            for (let k = 0; k < 18; k++) keysToUpdate.add(`stageright${k}`);
                        } else if (pKey === 'StageBottom' || targetBase === 'mania-stage-bottom' || targetBase === 'stagebottom') {
                            keysToUpdate.add('mania-stage-bottom');
                            keysToUpdate.add('stagebottom');
                            keysToUpdate.add('stage_bottom');
                        } else if (pKey === 'StageHint' || targetBase === 'mania-stage-hint' || targetBase === 'stagehint') {
                            keysToUpdate.add('mania-stage-hint');
                            keysToUpdate.add('stagehint');
                            keysToUpdate.add('hittarget');
                        } else if (pKey === 'StageLight' || targetBase === 'mania-stage-light' || targetBase === 'stagelight') {
                            keysToUpdate.add('mania-stage-light');
                            keysToUpdate.add('stagelight');
                        } else if (targetBase.includes('-') && !targetBase.startsWith('scorebar-')) {
                            const parts = targetBase.split('-');
                            const suffix = parts.slice(1).join('-');
                            keysToUpdate.add(`score-${suffix}`);
                            keysToUpdate.add(`default-${suffix}`);
                        }

                        // 同步检查当前皮肤配置中的自定义映射别名
                        for (const [, cfgItem] of maniaSkinConfigurations) {
                            if (cfgItem && cfgItem.ImageLookups && pKey) {
                                const customLookup = cfgItem.ImageLookups.get(pKey) || cfgItem.ImageLookups.get(pKey.toLowerCase());
                                if (customLookup) keysToUpdate.add(String(customLookup).toLowerCase());
                            }
                        }
                    }

                    // 强制写入内存图片仓库 (force = true)
                    for (const k of keysToUpdate) {
                        saveSkinAssetToStore(skinImageStore, k, img, is2x, true, true);
                        if (skinFallbackImageStore) {
                            saveSkinAssetToStore(skinFallbackImageStore, k, img, is2x, true, true);
                        }
                    }

                    // 存入待导出打包文件列表
                    userReplacedTextures.set(exportFilename, arrayBuffer);
                    if (exportFilenameLower !== exportFilename) {
                        userReplacedTextures.set(exportFilenameLower, arrayBuffer);
                    }

                    // 清除冲突的相反规格贴图条目，避免在导出或解析时混淆
                    userReplacedTextures.delete(`${cleanRawBase}${oppExt}`);
                    userReplacedTextures.delete(`${targetBase}${oppExt}`);

                    if (!isTrackNote) {
                        if (pKey === 'StageLeft' || targetBase === 'mania-stage-left' || targetBase === 'stageleft') {
                            userReplacedTextures.set(`mania-stage-left${curExt}`, arrayBuffer);
                            userReplacedTextures.set(`StageLeft${curExt}`, arrayBuffer);
                            userReplacedTextures.delete(`mania-stage-left${oppExt}`);
                            userReplacedTextures.delete(`StageLeft${oppExt}`);
                        } else if (pKey === 'StageRight' || targetBase === 'mania-stage-right' || targetBase === 'stageright') {
                            userReplacedTextures.set(`mania-stage-right${curExt}`, arrayBuffer);
                            userReplacedTextures.set(`StageRight${curExt}`, arrayBuffer);
                            userReplacedTextures.delete(`mania-stage-right${oppExt}`);
                            userReplacedTextures.delete(`StageRight${oppExt}`);
                        } else if (pKey === 'StageBottom' || targetBase === 'mania-stage-bottom' || targetBase === 'stagebottom') {
                            userReplacedTextures.set(`stagebottom${curExt}`, arrayBuffer);
                            userReplacedTextures.delete(`stagebottom${oppExt}`);
                            userReplacedTextures.delete(`mania-stage-bottom${oppExt}`);
                            userReplacedTextures.delete(`StageBottom${oppExt}`);
                        } else if (pKey === 'StageHint' || targetBase === 'mania-stage-hint' || targetBase === 'stagehint') {
                            userReplacedTextures.set(`mania-stage-hint${curExt}`, arrayBuffer);
                            userReplacedTextures.set(`StageHint${curExt}`, arrayBuffer);
                            userReplacedTextures.delete(`mania-stage-hint${oppExt}`);
                            userReplacedTextures.delete(`StageHint${oppExt}`);
                        } else if (pKey === 'StageLight' || targetBase === 'mania-stage-light' || targetBase === 'stagelight') {
                            userReplacedTextures.set(`mania-stage-light${curExt}`, arrayBuffer);
                            userReplacedTextures.set(`StageLight${curExt}`, arrayBuffer);
                            userReplacedTextures.delete(`mania-stage-light${oppExt}`);
                            userReplacedTextures.delete(`StageLight${oppExt}`);
                        }
                    }

                    // 更新 ini 配置与 ImageLookups
                    if (isTrackNote && trackCol != null) {
                        let primaryCfg = maniaSkinConfigurations.get(curKeys);
                        if (!primaryCfg) {
                            primaryCfg = ensureManiaConfigForKeys(curKeys);
                            maniaSkinConfigurations.set(curKeys, primaryCfg);
                        }
                        if (!primaryCfg.ImageLookups) primaryCfg.ImageLookups = new Map();

                        for (const alias of paramAliases) {
                            primaryCfg[alias] = cleanRawBase;
                            primaryCfg.ImageLookups.set(alias, cleanRawBase);
                            primaryCfg.ImageLookups.set(alias.toLowerCase(), cleanRawBase);
                        }
                        syncParamInputValue(canonicalParamKey, cleanRawBase);
                    } else if (pKey &&
                        pKey !== 'ScorePrefix' &&
                        pKey !== 'ComboPrefix' &&
                        !pKey.startsWith('Font_') &&
                        !pKey.startsWith('scorebar-')
                    ) {
                        let primaryCfg = maniaSkinConfigurations.get(curKeys);
                        if (!primaryCfg) {
                            primaryCfg = ensureManiaConfigForKeys(curKeys);
                            maniaSkinConfigurations.set(curKeys, primaryCfg);
                        }
                        for (const [, cfgItem] of maniaSkinConfigurations) {
                            if (!cfgItem.ImageLookups) cfgItem.ImageLookups = new Map();
                            cfgItem[pKey] = targetBase;
                            cfgItem.ImageLookups.set(pKey, targetBase);
                            cfgItem.ImageLookups.set(pKey.toLowerCase(), targetBase);
                        }
                        if (globalSkinImageLookups) {
                            globalSkinImageLookups.set(pKey, targetBase);
                            globalSkinImageLookups.set(pKey.toLowerCase(), targetBase);
                        }
                        syncParamInputValue(pKey, targetBase);
                    }

                    if (typeof completeTextureReplacement === 'function') {
                        completeTextureReplacement(replacement);
                    }
                    if (shouldNotify) {
                        const toastMsg = (isTrackNote && trackCol != null)
                            ? `第 ${trackCol + 1} 轨已单独更新为 ${is2x ? '@2x 高清' : '1x 普通'}贴图: ${exportFilename}`
                            : `已更新为 ${is2x ? '@2x 高清' : '1x 普通'}贴图: ${exportFilename}`;
                        showToast('替换贴图成功', toastMsg);
                    }
                    if (shouldRefresh) {
                        drawFrame();
                        renderSkinEditorParams();
                        const imageEditorModal = document.getElementById('textureImageEditorModal');
                        const imageEditorPicker = document.getElementById('textureImagePickerView');
                        if (imageEditorModal && imageEditorModal.classList.contains('active') &&
                            imageEditorPicker && getComputedStyle(imageEditorPicker).display !== 'none' &&
                            typeof renderPicker === 'function') {
                            renderPicker();
                        }
                        if (selectedCanvasElement) {
                            syncCanvasSelectedCard(selectedCanvasElement);
                        }
                    }
                    return true;
                } catch (err) {
                    console.error('替换贴图失败', err);
                    if (shouldNotify) showToast('替换失败', err.message || '未知错误');
                    return false;
                }
            }

            // 绑定贴图规格弹窗交互事件
            const specCard1x = document.getElementById('specCard1x');
            const specCard2x = document.getElementById('specCard2x');
            if (specCard1x) {
                specCard1x.onclick = () => {
                    selectedTextureSpec = '1x';
                    updateTextureUploadSpecCards();
                };
                specCard1x.ondblclick = () => {
                    selectedTextureSpec = '1x';
                    updateTextureUploadSpecCards();
                    confirmTextureUpload();
                };
            }
            if (specCard2x) {
                specCard2x.onclick = () => {
                    selectedTextureSpec = '2x';
                    updateTextureUploadSpecCards();
                };
                specCard2x.ondblclick = () => {
                    selectedTextureSpec = '2x';
                    updateTextureUploadSpecCards();
                    confirmTextureUpload();
                };
            }

            const specCardAnim = document.getElementById('specCardAnim');
            if (specCardAnim) {
                specCardAnim.onclick = () => {
                    const p = pendingTextureUpload;
                    const texName = p ? (p.targetFilename || p.cleanRawBase) : null;
                    const texKey = p ? p.targetKey : null;
                    const pKey = p ? p.targetParamKey : null;
                    if (!p || !isTextureAnimationSupported(pKey, texKey, texName)) {
                        showToast('不支持动态贴图', '该贴图在 osu!stable 中只支持静态图片，请选择 1x 或 @2x 规格。');
                        return;
                    }
                    const spec = (selectedTextureSpec === '2x') ? '2x' : '1x';
                    closeTextureUploadModal();
                    if (typeof openAnimTextureEditor === 'function') {
                        openAnimTextureEditor(texName, texKey, pKey, spec);
                    }
                };
            }

            const uploadCloseBtn = document.getElementById('textureUploadCloseBtn');
            const uploadCancelBtn = document.getElementById('textureUploadCancelBtn');
            const uploadBackdrop = document.getElementById('textureUploadBackdrop');
            const uploadConfirmBtn = document.getElementById('textureUploadConfirmBtn');
            if (uploadCloseBtn) uploadCloseBtn.onclick = closeTextureUploadModal;
            if (uploadCancelBtn) uploadCancelBtn.onclick = closeTextureUploadModal;
            if (uploadBackdrop) uploadBackdrop.onclick = closeTextureUploadModal;
            if (uploadConfirmBtn) uploadConfirmBtn.onclick = confirmTextureUpload;

            // 隐藏的贴图文件替换表单绑定
            const textureInput = document.getElementById('textureReplaceInput');
            if (textureInput) {
                textureInput.onchange = async (e) => {
                    const file = e.target.files && e.target.files[0];
                    if (!file) return;

                    try {
                        const arrayBuffer = await file.arrayBuffer();
                        const imgBlob = new Blob([arrayBuffer]);
                        const blobUrl = URL.createObjectURL(imgBlob);

                        const img = await new Promise((resolve, reject) => {
                            const tempImg = new Image();
                            tempImg.onload = () => resolve(tempImg);
                            tempImg.onerror = () => reject(new Error('无法解析该图片文件'));
                            tempImg.src = blobUrl;
                        });

                        const targetRawName = targetTextureUploadFilename || file.name;
                        let cleanRawBase = targetRawName.replace(/\.[^/.]+$/, '').replace(/@2x/i, '');
                        if (!cleanRawBase || isDummyBlankName(cleanRawBase)) {
                            cleanRawBase = (targetTextureUploadParamKey || targetTextureUploadKey || file.name).replace(/\.[^/.]+$/, '').replace(/@2x/i, '');
                        }
                        const targetBase = cleanRawBase.toLowerCase();

                        // 详细设置入口已明确选择 1x / @2x 时直接应用，不再二次询问；
                        // 只有画布入口未指定规格时，才打开规格确认弹窗。
                        const requestedSpec = preferredTextureUploadSpec;
                        preferredTextureUploadSpec = null;

                        if (requestedSpec === '1x' || requestedSpec === '2x') {
                            try {
                                URL.revokeObjectURL(blobUrl);
                                await applyUploadedTexture(
                                    file,
                                    arrayBuffer,
                                    img,
                                    requestedSpec === '2x',
                                    targetTextureUploadFilename,
                                    targetTextureUploadKey,
                                    targetTextureUploadParamKey,
                                    targetTextureUploadColIndex
                                );
                            } finally {
                                if (textureInput) textureInput.value = '';
                            }
                            return;
                        }

                        if (!requestedSpec) {
                            const autoIs2x = file.name.toLowerCase().includes('@2x');
                            selectedTextureSpec = autoIs2x ? '2x' : '1x';
                        }

                        pendingTextureUpload = {
                            file,
                            arrayBuffer,
                            img,
                            blobUrl,
                            targetFilename: targetTextureUploadFilename,
                            targetKey: targetTextureUploadKey,
                            targetParamKey: targetTextureUploadParamKey,
                            targetColIndex: targetTextureUploadColIndex,
                            targetBase,
                            cleanRawBase
                        };

                        openTextureUploadModal();
                    } catch (err) {
                        console.error('解析上传贴图失败', err);
                        showToast('读取贴图失败', err.message || '未知错误');
                    }
                };
            }

            textureUploadUi = {
                close: closeTextureUploadModal,
                confirm: confirmTextureUpload,
                applyEditedTexture: (file, arrayBuffer, img, is2x, targetFilename, targetKey, targetParamKey, targetColIndex, options) =>
                    applyUploadedTexture(file, arrayBuffer, img, is2x, targetFilename, targetKey, targetParamKey, targetColIndex, options),
                setSpec: (spec) => {
                    selectedTextureSpec = (spec === '2x') ? '2x' : '1x';
                    updateTextureUploadSpecCards();
                },
                toggleSpec: () => {
                    selectedTextureSpec = (selectedTextureSpec === '1x') ? '2x' : '1x';
                    updateTextureUploadSpecCards();
                },
                updateSpecCards: updateTextureUploadSpecCards
            };
        }
